UPDATE words SET examples='[["The chameleon uses camouflage.","آفتاب پرست از استتار استفاده می‌کند."],["The chameleon uses camouflage to hide.","آفتاب پرست برای پنهان شدن از استتار استفاده می‌کند."],["Soldiers wore camouflage uniforms.","سربازان لباس استتار به تن داشتند."],["The moth''s camouflage makes it look like tree bark.","استتار پروانه آن را شبیه پوست درخت می‌کند."]]', updated_at=1792231925620 WHERE slug='toefl:camouflage';
UPDATE words SET examples='[["He was a contemporary of Shakespeare.","او معاصر شکسپیر بود."],["She is a famous contemporary artist.","او یک هنرمند مشهور معاصر است."],["The novel was popular with contemporary readers.","این رمان در میان خوانندگان معاصر محبوبیت داشت."],["Contemporary architecture uses a lot of glass.","در معماری معاصر از شیشه‌های زیادی استفاده شده است."]]', updated_at=1792231925620 WHERE slug='toefl:contemporary';
UPDATE words SET examples='[["Farmers cultivate rice in wet fields.","کشاورزان برنج را در مزارع مرطوب کشت می‌کنند."],["Farmers cultivate rice in the north of Iran.","کشاورزان در شمال ایران برنج کشت می‌کنند."],["She cultivated friendships with influential people.","او با افراد با نفوذ دوستی ایجاد کرد."],["The land has been cultivated for centuries.","زمین برای قرن‌ها زیر کشت بوده است."]]', updated_at=1792231925620 WHERE slug='toefl:cultivate';
UPDATE words SET examples='[["The paintings deteriorated over time.","نقاشی‌ها به مرور زمان خراب شدند."],["The paintings deteriorated in the damp room.","نقاشی‌ها در اتاق مرطوب خراب شدند."],["Air quality has deteriorated in recent years.","کیفیت هوا در سال‌های اخیر بدتر شده است."],["Without care, the old building will deteriorate.","بدون مراقبت، ساختمان قدیمی خراب می‌شود."]]', updated_at=1792231925620 WHERE slug='toefl:deteriorate';
UPDATE words SET examples='[["The excavation uncovered ancient tombs.","در این حفاری مقبره‌های باستانی کشف شد."],["The excavation revealed ancient tombs.","در این حفاری مقبره‌های باستانی کشف شد."],["Excavation of the site began in 1931.","حفاری این سایت در سال 1931 آغاز شد."],["The excavation uncovered Roman coins.","در این حفاری سکه‌های رومی کشف شد."]]', updated_at=1792231925620 WHERE slug='toefl:excavation';
UPDATE words SET examples='[["Temperatures fluctuate widely in deserts.","دما در بیابان‌ها به شدت در نوسان است."],["Animal populations fluctuate with the seasons.","جمعیت حیوانات با فصول در نوسان است."],["Her mood fluctuates from day to day.","خلق و خوی او روز به روز در نوسان است."],["The price of gold fluctuates daily.","قیمت طلا روزانه در نوسان است."]]', updated_at=1792231925620 WHERE slug='toefl:fluctuate';
UPDATE words SET examples='[["Wolves live in a strict hierarchy.","گرگ‌ها در یک سلسله مراتب سخت زندگی می‌کنند."],["There is a strict hierarchy in the army.","یک سلسله مراتب سخت در ارتش وجود دارد."],["Wolves live in a social hierarchy.","گرگ‌ها در یک سلسله مراتب اجتماعی زندگی می‌کنند."],["She rose quickly through the company hierarchy.","او به سرعت در سلسله مراتب شرکت ارتقا یافت."]]', updated_at=1792231925620 WHERE slug='toefl:hierarchy';
UPDATE words SET examples='[["Researchers hypothesize that the climate was warmer.","محققان فرض می‌کنند که آب و هوا گرمتر بوده است."],["Scientists hypothesize that the asteroid caused extinction.","دانشمندان فرض می‌کنند که این سیارک باعث انقراض شده است."],["Researchers hypothesized that sleep improves memory.","محققان فرض کردند که خواب حافظه را بهبود می‌بخشد."],["We can only hypothesize about what happened.","ما فقط می‌توانیم در مورد آنچه اتفاق افتاده است فرضیه کنیم."]]', updated_at=1792231925620 WHERE slug='toefl:hypothesize';
UPDATE words SET examples='[["The discovery caused a paradigm shift.","این کشف باعث تغییر پارادایم شد."],["The discovery caused a paradigm shift in physics.","این کشف باعث تغییر پارادایم در فیزیک شد."],["The old paradigm of education is changing.","پارادایم قدیمی آموزش در حال تغییر است."],["Darwin''s theory became the new paradigm in biology.","نظریه داروین به پارادایم جدید در زیست شناسی تبدیل شد."]]', updated_at=1792231925620 WHERE slug='toefl:paradigm';
UPDATE words SET examples='[["Prehistoric people painted on cave walls.","مردم ماقبل تاریخ روی دیوارهای غار نقاشی می‌کردند."],["Prehistoric people painted animals on cave walls.","مردم ماقبل تاریخ حیوانات را روی دیوارهای غار نقاشی می‌کردند."],["The museum displays prehistoric tools.","این موزه ابزارهای ماقبل تاریخ را به نمایش می‌گذارد."],["Dinosaurs lived in prehistoric times.","دایناسورها در دوران ماقبل تاریخ زندگی می‌کردند."]]', updated_at=1792231925620 WHERE slug='toefl:prehistoric';
UPDATE words SET examples='[["Bacteria proliferate in warm conditions.","باکتری‌ها در شرایط گرم تکثیر می‌شوند."],["Fast-food restaurants have proliferated in the city.","رستوران‌های فست فود در شهر زیاد شده اند."],["Cancer cells proliferate rapidly.","سلول‌های سرطانی به سرعت تکثیر می‌شوند."]]', updated_at=1792231925620 WHERE slug='toefl:proliferate';
UPDATE words SET examples='[["Residual heat stays in the rocks.","گرمای باقیمانده در سنگ‌ها باقی می‌ماند."],["There is still some residual pain after the operation.","بعد از عمل هنوز مقداری درد باقی مانده است."],["Residual chemicals were found in the water.","مواد شیمیایی باقی مانده در آب پیدا شد."],["The residual heat kept the room warm.","گرمای باقیمانده اتاق را گرم نگه می‌داشت."]]', updated_at=1792231925620 WHERE slug='toefl:residual';
UPDATE words SET examples='[["Each stratum represents a different period.","هر قشر نشان دهنده یک دوره متفاوت است."],["Each stratum of rock represents a different period.","هر لایه سنگ نشان دهنده دوره متفاوتی است."],["Fossils were found in the lowest stratum.","فسیل‌ها در پایین‌ترین طبقه یافت شدند."],["The policy affects every stratum of society.","این سیاست بر هر قشری از جامعه تأثیر می‌گذارد."]]', updated_at=1792231925620 WHERE slug='toefl:stratum';
UPDATE words SET examples='[["Plants synthesize sugar from sunlight.","گیاهان از نور خورشید قند را سنتز می‌کنند."],["The drug was synthesized in a laboratory.","این دارو در آزمایشگاه سنتز شد."],["The essay synthesizes ideas from many sources.","این مقاله ایده‌ها را از منابع بسیاری ترکیب می‌کند."]]', updated_at=1792231925620 WHERE slug='toefl:synthesize';
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fundamental','fundamental','adj','اساسی، بنیادی','forming the basic and most important part of something','Clean water is a fundamental human need.','[["Clean water is a fundamental human need.","آب پاک یک نیاز اساسی انسان است."],["There are fundamental differences between the two theories.","بین این دو نظریه تفاوت‌های اساسی وجود دارد."],["The study questions some fundamental assumptions about learning.","این مطالعه برخی از مفروضات اساسی در مورد یادگیری را زیر سوال می‌برد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:willing','willing','adj','مایل، راغب، حاضر (به انجام کاری)','ready and happy to do something','Are you willing to work at weekends?','[["Are you willing to work at weekends?","آیا حاضرید در تعطیلات آخر هفته کار کنید؟"],["Few farmers were willing to try the new method.","تعداد کمی از کشاورزان حاضر به آزمایش روش جدید بودند."],["Volunteers are always willing to help.","داوطلبان همیشه مایل به کمک هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inhabitant','inhabitant','n','ساکن، سکنه (یک مکان)','a person or animal that lives in a particular place','The island has fewer than 500 inhabitants.','[["The island has fewer than 500 inhabitants.","این جزیره کمتر از 500 نفر جمعیت دارد."],["The original inhabitants of the valley were farmers.","ساکنان اولیه دره کشاورز بودند."],["Many inhabitants of the city work in tourism.","بسیاری از ساکنان این شهر در زمینه گردشگری فعالیت می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:criteria','criteria','n','معیارها، ملاک‌ها','standards used for judging or deciding something (plural of criterion)','The judges used strict criteria to choose the winner.','[["The judges used strict criteria to choose the winner.","داوران از معیارهای سختگیرانه ای برای انتخاب برنده استفاده کردند."],["Applicants must meet all the criteria listed below.","متقاضیان باید تمام معیارهای ذکر شده در زیر را داشته باشند."],["What criteria do scientists use to classify species?","دانشمندان از چه معیارهایی برای طبقه بندی گونه‌ها استفاده می‌کنند؟"]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:irrigation','irrigation','n','آبیاری','the supply of water to land or crops through channels or pipes','Ancient Persians built qanats for irrigation.','[["Ancient Persians built qanats for irrigation.","ایرانیان باستان قنات‌هایی برای آبیاری می‌ساختند."],["Without irrigation, crops cannot grow in the desert.","بدون آبیاری، محصولات در بیابان رشد نمی‌کنند."],["Modern irrigation systems save a lot of water.","سیستم‌های آبیاری مدرن تا حد زیادی در مصرف آب صرفه جویی می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:eccentric','eccentric','adj','عجیب، غیرعادی، خاص','behaving in a strange or unusual way','The eccentric inventor lived alone with forty cats.','[["The eccentric inventor lived alone with forty cats.","مخترع عجیب و غریب با چهل گربه تنها زندگی می‌کرد."],["He was known for his eccentric habits.","او به خاطر عادت‌های عجیب و غریبش معروف بود."],["Her eccentric style of dressing attracted attention.","سبک لباس پوشیدن عجیب او توجه‌ها را به خود جلب کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:comprise','comprise','v','شامل شدن، تشکیل شدن از','to consist of or be made up of','The course comprises ten lessons.','[["The course comprises ten lessons.","این دوره شامل ده درس می‌باشد."],["Women comprise over half of the workforce.","زنان بیش از نیمی از نیروی کار را تشکیل می‌دهند."],["The collection comprises 300 paintings.","این مجموعه شامل 300 نقاشی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deduction','deduction','n','استنتاج، نتیجه‌گیری؛ کسر (از مبلغ)','the process of reaching a conclusion from facts; also an amount taken away','By careful deduction, the detective found the thief.','[["By careful deduction, the detective found the thief.","با کسر دقیق، کارآگاه دزد را پیدا کرد."],["Her deduction was based on the available evidence.","استنباط او بر اساس شواهد موجود بود."],["Tax deductions reduce the amount you have to pay.","کسر مالیات باعث کاهش مبلغی می‌شود که باید پرداخت کنید."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:descend','descend','v','پایین آمدن، پایین رفتن','to move or go down','The plane began to descend towards the airport.','[["The plane began to descend towards the airport.","هواپیما به سمت فرودگاه شروع به فرود کرد."],["We descended the mountain before dark.","قبل از تاریک شدن هوا از کوه پایین آمدیم."],["The road descends steeply into the valley.","جاده با شیب تند به دره فرود می‌آید."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:mortality','mortality','n','مرگ‌ومیر، میزان مرگ','the number of deaths in a particular group or period','Infant mortality has fallen sharply in the last century.','[["Infant mortality has fallen sharply in the last century.","مرگ و میر نوزادان در قرن گذشته به شدت کاهش یافته است."],["The disease has a high mortality rate.","این بیماری میزان مرگ و میر بالایی دارد."],["Better healthcare reduced mortality among older people.","مراقبت‌های بهداشتی بهتر باعث کاهش مرگ و میر در میان افراد مسن شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:elaborate','elaborate','adj','مفصل، پیچیده و پرجزئیات','carefully planned with many detailed parts','The palace has elaborate decorations.','[["The palace has elaborate decorations.","این کاخ دارای تزئینات پیچیده است."],["They made elaborate plans for the wedding.","آنها برای عروسی برنامه ریزی دقیقی انجام دادند."],["The bird performs an elaborate dance to attract a mate.","پرنده برای جذب جفت، رقصی مفصل اجرا می‌کند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:incidence','incidence','n','میزان وقوع، شیوع','the rate at which something happens, especially something bad','The incidence of heart disease is higher in cities.','[["The incidence of heart disease is higher in cities.","بروز بیماری‌های قلبی در شهرها بیشتر است."],["There is a low incidence of crime in the village.","میزان وقوع جرم در روستا کم است."],["Researchers studied the incidence of malaria in the region.","محققان شیوع مالاریا را در منطقه مورد مطالعه قرار دادند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:renowned','renowned','adj','مشهور، نامدار','famous and respected for a special quality or skill','Isfahan is renowned for its beautiful mosques.','[["Isfahan is renowned for its beautiful mosques.","اصفهان به مساجد زیبایش معروف است."],["She is a renowned expert in marine biology.","او یک متخصص مشهور در زیست شناسی دریایی است."],["The restaurant is renowned for its seafood.","این رستوران به خاطر غذاهای دریایی اش مشهور است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:reveal','reveal','v','فاش کردن، آشکار کردن','to make something known that was secret or hidden','The study revealed a link between diet and memory.','[["The study revealed a link between diet and memory.","این مطالعه ارتباط بین رژیم غذایی و حافظه را نشان داد."],["X-rays revealed a crack in the bone.","اشعه ایکس شکافی را در استخوان نشان داد."],["He refused to reveal the name of his source.","او از افشای نام منبع خود خودداری کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:monument','monument','n','بنای یادبود، اثر تاریخی','a building or statue built to remember a person or event; an important old building','The monument was built in honor of the soldiers.','[["The monument was built in honor of the soldiers.","این بنا به افتخار سربازان ساخته شده است."],["Persepolis is one of the most famous monuments in Iran.","تخت جمشید یکی از معروف‌ترین بناهای ایران است."],["Many ancient monuments are protected by law.","بسیاری از آثار باستانی توسط قانون محافظت می‌شوند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:purify','purify','v','خالص کردن، تصفیه کردن','to remove dirty or harmful substances from something','Plants help purify the air in our homes.','[["Plants help purify the air in our homes.","گیاهان به تصفیه هوای خانه ما کمک می‌کنند."],["The water is purified before it reaches our taps.","آب قبل از اینکه به شیر ما برسد تصفیه می‌شود."],["Sand and charcoal can be used to purify water.","برای تصفیه آب می‌توان از ماسه و زغال چوب استفاده کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intricate','intricate','adj','پیچیده و ظریف، پرجزئیات','having many small parts arranged in a complicated way','Persian carpets have intricate patterns.','[["Persian carpets have intricate patterns.","فرش‌های ایرانی نقوش پیچیده ای دارند."],["The watch has an intricate mechanism.","این ساعت مکانیزم پیچیده ای دارد."],["The novel has an intricate plot.","رمان داستان پیچیده ای دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:abandon','abandon','v','رها کردن، ترک کردن','to leave someone or something completely; to stop doing something','The village was abandoned after the earthquake.','[["The village was abandoned after the earthquake.","این روستا پس از زلزله متروکه شد."],["They had to abandon the project because of a lack of money.","آنها مجبور شدند پروژه را به دلیل کمبود پول رها کنند."],["Many pets are abandoned every summer.","بسیاری از حیوانات خانگی هر تابستان رها می‌شوند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:vigorous','vigorous','adj','پرانرژی، نیرومند، شدید','strong, healthy and full of energy','Thirty minutes of vigorous exercise a day is recommended.','[["Thirty minutes of vigorous exercise a day is recommended.","سی دقیقه ورزش شدید در روز توصیه می‌شود."],["The plant shows vigorous growth in spring.","این گیاه در بهار رشد شدیدی از خود نشان می‌دهد."],["There was a vigorous debate about the new law.","بحث‌های شدیدی در مورد قانون جدید وجود داشت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:gifted','gifted','adj','بااستعداد، مستعد','having a natural ability to do something very well','She is a gifted musician.','[["She is a gifted musician.","او یک نوازنده با استعداد است."],["The school offers special classes for gifted children.","این مدرسه کلاس‌های ویژه ای را برای کودکان تیزهوش برگزار می‌کند."],["He was a gifted scientist who made many discoveries.","او دانشمندی با استعداد بود که اکتشافات زیادی انجام داد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:spectacular','spectacular','adj','دیدنی، چشمگیر، باشکوه','extremely impressive or exciting to see','The view from the top of the mountain is spectacular.','[["The view from the top of the mountain is spectacular.","منظره ای از بالای کوه دیدنی است."],["The city celebrated with a spectacular fireworks display.","شهر با یک آتش بازی تماشایی جشن گرفت."],["The company has had spectacular success this year.","این شرکت در سال جاری موفقیت چشمگیری داشته است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:contribute','contribute','v','کمک کردن، سهیم بودن؛ باعث شدن (contribute to)','to help cause something; to give something to help achieve a goal','Smoking contributes to heart disease.','[["Smoking contributes to heart disease.","سیگار به بیماری قلبی کمک می‌کند."],["Many factors contributed to the decline of the empire.","عوامل زیادی در سقوط امپراتوری نقش داشتند."],["Everyone contributed some money to the gift.","همه مقداری پول به این هدیه کمک کردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:decade','decade','n','دهه (ده سال)','a period of ten years','The city has grown rapidly over the last decade.','[["The city has grown rapidly over the last decade.","این شهر در دهه گذشته به سرعت رشد کرده است."],["Prices have doubled in a decade.","قیمت‌ها در یک دهه دو برابر شده است."],["It took scientists decades to solve the problem.","دانشمندان چندین دهه طول کشید تا این مشکل را حل کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:compensate','compensate','v','جبران کردن، غرامت دادن','to reduce the bad effect of something; to pay someone for loss or damage','Nothing can compensate for the loss of a natural habitat.','[["Nothing can compensate for the loss of a natural habitat.","هیچ چیز نمی‌تواند از دست دادن یک زیستگاه طبیعی را جبران کند."],["The company compensated the farmers for their damaged crops.","این شرکت به کشاورزان محصولات زیان دیده خود غرامت پرداخت کرد."],["Some animals compensate for poor eyesight with a strong sense of smell.","برخی از حیوانات ضعف بینایی را با حس بویایی قوی جبران می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:abolish','abolish','v','لغو کردن، منسوخ کردن','to officially end a law, system or practice','Slavery was abolished in the nineteenth century.','[["Slavery was abolished in the nineteenth century.","برده داری در قرن نوزدهم لغو شد."],["The government plans to abolish the tax.","دولت قصد دارد این مالیات را لغو کند."],["Many countries have abolished the death penalty.","بسیاری از کشورها مجازات اعدام را لغو کرده اند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:evaluate','evaluate','v','ارزیابی کردن','to judge or calculate the quality, value or importance of something','Researchers evaluated the effects of the new drug.','[["Researchers evaluated the effects of the new drug.","محققان اثرات داروی جدید را ارزیابی کردند."],["It is difficult to evaluate the success of the program.","ارزیابی موفقیت برنامه دشوار است."],["Teachers evaluate students'' progress regularly.","معلمان به طور منظم پیشرفت دانش آموزان را ارزیابی می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:distribute','distribute','v','توزیع کردن، پخش کردن','to give or spread something among many people or places','Food was distributed to the flood victims.','[["Food was distributed to the flood victims.","برای سیل زدگان مواد غذایی توزیع شد."],["Seeds are distributed by wind and animals.","دانه‌ها توسط باد و حیوانات توزیع می‌شوند."],["The species is widely distributed across Asia.","این گونه به طور گسترده در سراسر آسیا پراکنده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:succinct','succinct','adj','مختصر و مفید، موجز','expressed clearly in few words','Give a succinct summary of the passage.','[["Give a succinct summary of the passage.","خلاصه ای مختصر از متن بیان کنید."],["Her answer was succinct and accurate.","پاسخ او موجز و دقیق بود."],["The report is succinct but informative.","گزارش مختصر اما آموزنده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:sustainable','sustainable','adj','پایدار، سازگار با محیط زیست','able to continue for a long time without damaging the environment','Sustainable farming protects the soil.','[["Sustainable farming protects the soil.","کشاورزی پایدار از خاک محافظت می‌کند."],["The city aims to become more sustainable.","هدف این شهر پایدارتر شدن است."],["Is this level of economic growth sustainable?","آیا این سطح از رشد اقتصادی پایدار است؟"]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:conversely','conversely','adv','برعکس، از سوی دیگر، به‌طور متضاد','in an opposite way; used to introduce a contrasting idea','Some animals sleep in winter; conversely, others are active only in the cold.','[["Some animals sleep in winter; conversely, others are active only in the cold.","برخی از حیوانات در زمستان می‌خوابند. برعکس، دیگران فقط در سرما فعال هستند."],["Higher prices reduce demand; conversely, lower prices increase it.","قیمت‌های بالاتر تقاضا را کاهش می‌دهد. برعکس، قیمت‌های پایین‌تر آن را افزایش می‌دهد."],["You can add the numbers in either order, and conversely subtract them.","می‌توانید اعداد را به هر ترتیب اضافه کنید و برعکس آنها را کم کنید."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:emission','emission','n','انتشار، تولید (گاز، نور، گرما)','the sending out of gas, heat or light; a gas that is sent out','Cars are a major source of carbon emissions.','[["Cars are a major source of carbon emissions.","خودروها منبع اصلی انتشار کربن هستند."],["The factory reduced its emissions by forty percent.","کارخانه تولید گازهای گلخانه ای خود را تا چهل درصد کاهش داد."],["Many countries have promised to cut greenhouse gas emissions.","بسیاری از کشورها وعده کاهش انتشار گازهای گلخانه ای را داده اند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deprived','deprived','adj','محروم، فقیر','without enough food, money, education or other basic things','The charity helps children from deprived areas.','[["The charity helps children from deprived areas.","این موسسه خیریه به کودکان مناطق محروم کمک می‌کند."],["Many deprived families cannot afford healthy food.","بسیاری از خانواده‌های محروم توانایی خرید غذای سالم را ندارند."],["Sleep-deprived drivers are more likely to have accidents.","رانندگان کم خواب بیشتر در معرض تصادف هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:emerge','emerge','v','ظاهر شدن، پدیدار شدن؛ معلوم شدن','to appear or come out; to become known','The butterfly emerged from its cocoon.','[["The butterfly emerged from its cocoon.","پروانه از پیله بیرون آمد."],["New evidence has emerged about the cause of the fire.","شواهد جدیدی در مورد علت آتش سوزی به دست آمده است."],["China emerged as a major economic power.","چین به عنوان یک قدرت اقتصادی بزرگ ظاهر شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:expertise','expertise','n','تخصص، مهارت، تبحر','expert knowledge or skill in a particular area','The project requires technical expertise.','[["The project requires technical expertise.","پروژه نیاز به تخصص فنی دارد."],["She has considerable expertise in ancient languages.","او تخصص قابل توجهی در زبان‌های باستانی دارد."],["We need people with expertise in computer science.","به افراد متخصص در رشته کامپیوتر نیازمندیم."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:approach','approach','n','رویکرد، روش؛ نزدیک شدن','a way of dealing with something; (v.) to come near','Scientists are trying a new approach to the problem.','[["Scientists are trying a new approach to the problem.","دانشمندان در حال تلاش برای رویکرد جدیدی برای حل این مشکل هستند."],["Her approach to teaching is very practical.","رویکرد او به تدریس بسیار کاربردی است."],["As winter approaches, birds fly south.","با نزدیک شدن به زمستان، پرندگان به سمت جنوب پرواز می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:harness','harness','v','مهار کردن و به کار گرفتن','to control and use the force or power of something','Dams harness the power of rivers to produce electricity.','[["Dams harness the power of rivers to produce electricity.","سدها از قدرت رودخانه‌ها برای تولید برق استفاده می‌کنند."],["We need to harness solar energy more effectively.","ما باید از انرژی خورشیدی به طور موثرتری استفاده کنیم."],["The company harnessed new technology to improve production.","این شرکت از فناوری جدید برای بهبود تولید استفاده کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:innovation','innovation','n','نوآوری','a new idea, method or invention; the introduction of new things','The printing press was a great innovation.','[["The printing press was a great innovation.","چاپخانه نوآوری بزرگی بود."],["Innovation is essential for economic growth.","نوآوری برای رشد اقتصادی ضروری است."],["The company is famous for its technological innovations.","این شرکت به دلیل نوآوری‌های تکنولوژیکی خود مشهور است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:halt','halt','v','متوقف کردن، متوقف شدن','to stop or make something stop','Production was halted because of the strike.','[["Production was halted because of the strike.","تولید به دلیل اعتصاب متوقف شد."],["The government acted to halt the spread of the disease.","دولت برای جلوگیری از شیوع این بیماری اقدام کرد."],["The train halted suddenly.","قطار ناگهان متوقف شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:substantial','substantial','adj','قابل‌توجه، چشمگیر، زیاد','large in amount, size or importance','The research received substantial funding.','[["The research received substantial funding.","این تحقیق بودجه قابل توجهی دریافت کرد."],["There has been a substantial increase in population.","افزایش قابل توجهی در جمعیت داشته است."],["A substantial number of species are threatened.","تعداد قابل توجهی از گونه‌ها در معرض تهدید هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:manuscript','manuscript','n','نسخه خطی؛ دست‌نوشته','a book or document written by hand, or a writer''s original text before printing','The library holds ancient manuscripts of Persian poetry.','[["The library holds ancient manuscripts of Persian poetry.","این کتابخانه دارای نسخ خطی کهن شعر فارسی است."],["The manuscript was discovered in a monastery.","این نسخه خطی در یک صومعه کشف شد."],["She sent the manuscript of her novel to a publisher.","او نسخه خطی رمان خود را برای یک ناشر فرستاد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:stimulate','stimulate','v','تحریک کردن، برانگیختن، تقویت کردن','to make something more active or encourage it to develop','Light stimulates the growth of plants.','[["Light stimulates the growth of plants.","نور باعث تحریک رشد گیاهان می‌شود."],["The government lowered taxes to stimulate the economy.","دولت مالیات‌ها را کاهش داد تا اقتصاد را تحریک کند."],["Good teachers stimulate students'' curiosity.","معلمان خوب حس کنجکاوی دانش آموزان را تحریک می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:interpret','interpret','v','تفسیر کردن؛ ترجمه شفاهی کردن','to explain the meaning of something; to understand something in a particular way','Scientists interpret the data in different ways.','[["Scientists interpret the data in different ways.","دانشمندان داده‌ها را به روش‌های مختلف تفسیر می‌کنند."],["How do you interpret the results of the survey?","نتایج نظرسنجی را چگونه تفسیر می‌کنید؟"],["Ancient symbols are difficult to interpret.","تفسیر نمادهای باستانی دشوار است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:revolutionize','revolutionize','v','متحول کردن، دگرگون کردن','to completely change something, usually in a positive way','The internet has revolutionized communication.','[["The internet has revolutionized communication.","اینترنت ارتباطات را متحول کرده است."],["The steam engine revolutionized transport.","موتور بخار حمل و نقل را متحول کرد."],["New drugs could revolutionize the treatment of cancer.","داروهای جدید می‌توانند انقلابی در درمان سرطان ایجاد کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:apprentice','apprentice','n','کارآموز، شاگرد (در حرفه)','a person who learns a skill by working for an expert for a period of time','He worked as an apprentice to a carpenter.','[["He worked as an apprentice to a carpenter.","او به عنوان شاگرد یک نجار کار می‌کرد."],["Apprentices are paid while they learn.","کارآموزان در حین یادگیری حقوق می‌گیرند."],["In the past, painters trained apprentices in their workshops.","در گذشته نقاشان در کارگاه‌های خود به آموزش شاگردان می‌پرداختند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:species','species','n','گونه (جانوری یا گیاهی)','a group of animals or plants that are similar and can breed together','Thousands of species are in danger of extinction.','[["Thousands of species are in danger of extinction.","هزاران گونه در خطر انقراض هستند."],["Scientists discovered a new species of frog.","دانشمندان گونه جدیدی از قورباغه را کشف کردند."],["The forest is home to many rare species.","این جنگل زیستگاه بسیاری از گونه‌های کمیاب است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unique','unique','adj','منحصربه‌فرد، بی‌همتا','being the only one of its kind; very special','Every person''s fingerprints are unique.','[["Every person''s fingerprints are unique.","اثر انگشت هر فردی منحصر به فرد است."],["The island has a unique ecosystem.","این جزیره دارای یک اکوسیستم منحصر به فرد است."],["This plant is unique to the region.","این گیاه منحصر به فرد در منطقه است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:delicate','delicate','adj','ظریف، شکننده، حساس','easily damaged or broken; needing careful handling','The ecosystem is in a delicate balance.','[["The ecosystem is in a delicate balance.","اکوسیستم در یک تعادل ظریف قرار دارد."],["Be careful with the delicate glass.","مراقب شیشه‌های ظریف باشید."],["Negotiations are at a delicate stage.","مذاکرات در مرحله حساسی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:reinforce','reinforce','v','تقویت کردن، تشدید کردن','to make something stronger','The walls were reinforced with steel.','[["The walls were reinforced with steel.","دیوارها با فولاد تقویت شدند."],["The results reinforce the idea that exercise helps memory.","نتایج این ایده را تقویت می‌کند که ورزش به حافظه کمک می‌کند."],["Repetition reinforces learning.","تکرار یادگیری را تقویت می‌کند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:rival','rival','n','رقیب','a person or group competing with another for the same thing','The two companies are rivals in the phone market.','[["The two companies are rivals in the phone market.","این دو شرکت در بازار گوشی رقیب یکدیگر هستند."],["He beat his rival in the final.","او در فینال رقیب خود را شکست داد."],["The city was once a rival of Rome.","این شهر زمانی رقیب رم بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:alter','alter','v','تغییر دادن، اصلاح کردن','to change something, usually slightly','Climate change may alter the migration patterns of birds.','[["Climate change may alter the migration patterns of birds.","تغییرات آب و هوایی ممکن است الگوهای مهاجرت پرندگان را تغییر دهد."],["The dress was altered to fit her.","لباس به تناسب او تغییر یافت."],["Nothing can alter the fact that he lied.","هیچ چیز نمی‌تواند این واقعیت را تغییر دهد که او دروغ گفته است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:advocate','advocate','n','مدافع، طرفدار؛ وکیل مدافع','a person who publicly supports an idea or cause; a lawyer','She is a strong advocate of women''s rights.','[["She is a strong advocate of women''s rights.","او از مدافعان قوی حقوق زنان است."],["Advocates of the plan say it will create jobs.","طرفداران این طرح می‌گویند که این طرح شغل ایجاد می‌کند."],["He was an advocate for environmental protection.","او مدافع حفاظت از محیط زیست بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:superficial','superficial','adj','سطحی، غیرعمیق','only on the surface; not deep or thorough','The cut was only superficial.','[["The cut was only superficial.","برش فقط سطحی بود."],["He has only a superficial knowledge of the subject.","او فقط شناخت سطحی از موضوع دارد."],["There are superficial similarities between the two languages.","شباهت‌های ظاهری بین این دو زبان وجود دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:simultaneous','simultaneous','adj','همزمان','happening or done at the same time','There were simultaneous explosions in two cities.','[["There were simultaneous explosions in two cities.","انفجارهای همزمان در دو شهر رخ داد."],["The conference offers simultaneous translation.","این کنفرانس دارای ترجمه همزمان است."],["Simultaneous tasks can reduce concentration.","انجام کارهای همزمان می‌تواند تمرکز را کاهش دهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:authentic','authentic','adj','اصل، معتبر، موثق','real and not false or copied; true and accurate','Experts confirmed that the painting was authentic.','[["Experts confirmed that the painting was authentic.","کارشناسان تایید کردند که این نقاشی معتبر است."],["The restaurant serves authentic Italian food.","این رستوران غذاهای اصیل ایتالیایی سرو می‌کند."],["The book gives an authentic picture of life in the village.","این کتاب تصویری واقعی از زندگی در روستا به دست می‌دهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:primitive','primitive','adj','ابتدایی، اولیه','belonging to an early stage of development; simple','Primitive humans used stone tools.','[["Primitive humans used stone tools.","انسان‌های اولیه از ابزارهای سنگی استفاده می‌کردند."],["The tools they used were primitive.","ابزارهایی که استفاده می‌کردند ابتدایی بود."],["Bacteria are primitive forms of life.","باکتری‌ها اشکال اولیه حیات هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:battle','battle','n','نبرد، مبارزه، جدال','a fight between armies; a struggle to achieve something','The battle lasted three days.','[["The battle lasted three days.","نبرد سه روز طول کشید."],["Her battle against cancer inspired many people.","نبرد او با سرطان الهام بخش بسیاری از مردم بود."],["There is a constant battle between predators and prey.","نبرد دائمی بین شکارچیان و طعمه‌ها وجود دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:phenomenon','phenomenon','n','پدیده','a fact or event that can be observed, especially one that is unusual','Rainbows are a natural phenomenon.','[["Rainbows are a natural phenomenon.","رنگین کمان یک پدیده طبیعی است."],["Global warming is a worldwide phenomenon.","گرمایش زمین یک پدیده جهانی است."],["Scientists still cannot fully explain this phenomenon.","دانشمندان هنوز نمی‌توانند این پدیده را به طور کامل توضیح دهند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unintentional','unintentional','adj','غیرعمدی، سهوی','not done on purpose','The damage was unintentional.','[["The damage was unintentional.","آسیب ناخواسته بود."],["The introduction of rabbits to Australia had unintentional consequences.","ورود خرگوش‌ها به استرالیا عواقب غیرعمدی داشت."],["I''m sorry; the mistake was completely unintentional.","متاسفم؛ اشتباه کاملا غیر عمدی بود"]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:segment','segment','n','بخش، قسمت','one of the parts into which something is divided','An orange is divided into segments.','[["An orange is divided into segments.","یک پرتقال به بخش‌هایی تقسیم می‌شود."],["Older people are a growing segment of the population.","افراد مسن بخش رو به رشدی از جمعیت هستند."],["The worm''s body is made up of many segments.","بدن کرم از بخش‌های زیادی تشکیل شده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:eradicate','eradicate','v','ریشه‌کن کردن','to destroy or get rid of something completely','Smallpox was eradicated in 1980.','[["Smallpox was eradicated in 1980.","آبله در سال 1980 ریشه کن شد."],["The aim is to eradicate poverty.","هدف از بین بردن فقر است."],["Farmers struggle to eradicate weeds.","کشاورزان برای از بین بردن علف‌های هرز تلاش می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:estimate','estimate','v','تخمین زدن، برآورد کردن','to guess the size, amount or value of something roughly','Scientists estimate that the tree is 2,000 years old.','[["Scientists estimate that the tree is 2,000 years old.","دانشمندان تخمین می‌زنند که این درخت 2000 سال سن دارد."],["It is estimated that a million people visited the exhibition.","تخمین زده می‌شود که یک میلیون نفر از این نمایشگاه بازدید کرده اند."],["Can you estimate how long the work will take?","آیا می‌توانید تخمین بزنید که کار چقدر طول می‌کشد؟"]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:praise','praise','v','تحسین کردن، ستایش کردن','to express approval or admiration for someone or something','The teacher praised her excellent essay.','[["The teacher praised her excellent essay.","معلم از مقاله عالی او تمجید کرد."],["Critics praised the film for its realism.","منتقدان فیلم را به خاطر واقع گرایی آن تحسین کردند."],["Children should be praised for their efforts.","کودکان را باید به خاطر تلاش هایشان ستود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:obscure','obscure','v','پنهان کردن، مبهم کردن؛ (adj.) ناشناخته','to hide or make something difficult to see or understand','Clouds obscured the moon.','[["Clouds obscured the moon.","ابرها ماه را پنهان کردند."],["Too many details can obscure the main point.","جزئیات بیش از حد می‌تواند موضوع اصلی را مبهم کند."],["The origins of the custom are obscure.","منشا رسم مبهم است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:peculiar','peculiar','adj','عجیب، غیرعادی؛ خاص (peculiar to)','strange or unusual; belonging only to a particular person or place','There was a peculiar smell in the room.','[["There was a peculiar smell in the room.","بوی عجیبی در اتاق به مشام می‌رسید."],["This custom is peculiar to the region.","این رسم مخصوص منطقه است."],["The animal has a peculiar way of walking.","این حیوان راه رفتن عجیبی دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:regional','regional','adj','منطقه‌ای، محلی','relating to a particular area of a country or the world','Each regional dish has its own flavor.','[["Each regional dish has its own flavor.","هر غذای منطقه ای طعم خاص خود را دارد."],["Regional differences in climate affect farming.","تفاوت‌های منطقه ای در آب و هوا بر کشاورزی تأثیر می‌گذارد."],["The company has regional offices in five cities.","این شرکت دارای دفاتر منطقه ای در پنج شهر است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:infrastructure','infrastructure','n','زیرساخت','the basic systems and services a country needs, such as roads, power and water','The country invested heavily in infrastructure.','[["The country invested heavily in infrastructure.","این کشور سرمایه گذاری زیادی در زیرساخت‌ها انجام داد."],["Poor infrastructure slows economic growth.","زیرساخت‌های ضعیف رشد اقتصادی را کند می‌کند."],["The earthquake damaged the city''s infrastructure.","این زلزله به زیرساخت‌های شهر آسیب وارد کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:statistics','statistics','n','آمار','numbers that show facts about a subject; the science of collecting and analyzing numbers','Statistics show that crime has fallen.','[["Statistics show that crime has fallen.","آمارها نشان می‌دهد که جرم و جنایت کاهش یافته است."],["According to official statistics, unemployment is rising.","طبق آمار رسمی، بیکاری در حال افزایش است."],["She studied statistics at university.","او در دانشگاه آمار خواند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:diversity','diversity','n','تنوع','the fact of many different types of things or people being included','The rainforest has an amazing diversity of plants.','[["The rainforest has an amazing diversity of plants.","جنگل‌های بارانی دارای تنوع شگفت انگیزی از گیاهان است."],["The city is proud of its cultural diversity.","این شهر به تنوع فرهنگی خود افتخار می‌کند."],["Genetic diversity helps species survive.","تنوع ژنتیکی به زنده ماندن گونه‌ها کمک می‌کند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:evacuate','evacuate','v','تخلیه کردن (به‌سرعت)','to move people out of a dangerous place','Thousands of people were evacuated before the hurricane.','[["Thousands of people were evacuated before the hurricane.","هزاران نفر قبل از طوفان تخلیه شدند."],["The building was evacuated after a bomb warning.","ساختمان پس از هشدار بمب تخلیه شد."],["Residents were told to evacuate immediately.","به ساکنان گفته شد که فوراً تخلیه شوند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:underestimate','underestimate','v','دست‌کم گرفتن','to think something is smaller, less important or weaker than it really is','Never underestimate the power of education.','[["Never underestimate the power of education.","هرگز قدرت آموزش را دست کم نگیرید."],["We underestimated how long the journey would take.","ما مدت زمان سفر را دست کم گرفتیم."],["Scientists may have underestimated the speed of climate change.","دانشمندان ممکن است سرعت تغییرات آب و هوا را دست کم گرفته باشند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:measure','measure','n','اقدام، تدبیر؛ معیار','an official action taken to deal with a problem','The government introduced measures to reduce pollution.','[["The government introduced measures to reduce pollution.","دولت اقداماتی را برای کاهش آلودگی ارائه کرد."],["Safety measures were increased after the accident.","تدابیر ایمنی پس از حادثه افزایش یافت."],["Strict measures were taken to stop the disease.","اقدامات جدی برای جلوگیری از این بیماری انجام شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:captivating','captivating','adj','مسحورکننده، بسیار جذاب','extremely interesting or attractive','The book tells a captivating story.','[["The book tells a captivating story.","کتاب داستانی جذاب را روایت می‌کند."],["She has a captivating smile.","او لبخندی گیرا دارد."],["The documentary was captivating from start to finish.","این مستند از ابتدا تا انتها جذاب بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:trait','trait','n','ویژگی، خصیصه','a particular quality in someone''s character or a feature of a living thing','Patience is an important trait for a teacher.','[["Patience is an important trait for a teacher.","صبر برای یک معلم یک ویژگی مهم است."],["Eye color is a genetic trait.","رنگ چشم یک ویژگی ژنتیکی است."],["Shyness is a common personality trait.","خجالتی بودن یک ویژگی شخصیتی رایج است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cultivate','cultivate','v','کشت کردن، پرورش دادن؛ پروراندن','to prepare and use land for crops; to develop a skill or relationship','Rice has been cultivated in this region for centuries.','[["Rice has been cultivated in this region for centuries.","قرن هاست که در این منطقه برنج کشت می‌شود."],["The land is too dry to cultivate.","زمین خشک‌تر از آن است که بتوان کشت کرد."],["She cultivated a love of reading in her children.","او عشق به مطالعه را در فرزندانش پرورش داد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hemisphere','hemisphere','n','نیمکره','one half of the Earth or of the brain','Australia is in the Southern Hemisphere.','[["Australia is in the Southern Hemisphere.","استرالیا در نیمکره جنوبی قرار دارد."],["The left hemisphere of the brain controls language.","نیمکره چپ مغز زبان را کنترل می‌کند."],["Seasons are reversed in the two hemispheres.","فصول در دو نیمکره برعکس می‌شوند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:introverted','introverted','adj','درون‌گرا','quiet and more interested in one''s own thoughts than in being with others','Introverted people often prefer working alone.','[["Introverted people often prefer working alone.","افراد درونگرا اغلب ترجیح می‌دهند به تنهایی کار کنند."],["He was an introverted child who loved books.","او کودکی درونگرا بود که عاشق کتاب بود."],["Being introverted is not the same as being shy.","درونگرا بودن مساوی با خجالتی بودن نیست."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deplete','deplete','v','تحلیل بردن، کاهش دادن، تهی کردن','to reduce the amount of something until little is left','Overfishing has depleted fish populations.','[["Overfishing has depleted fish populations.","صید بی رویه باعث کاهش جمعیت ماهیان شده است."],["The long winter depleted our food supplies.","زمستان طولانی ذخایر غذایی ما را خالی کرد."],["Some chemicals deplete the ozone layer.","برخی از مواد شیمیایی لایه اوزون را تخریب می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inherent','inherent','adj','ذاتی، درونی','existing as a natural and permanent part of something','There are risks inherent in all forms of travel.','[["There are risks inherent in all forms of travel.","خطرات ذاتی در همه اشکال سفر وجود دارد."],["Curiosity is inherent in children.","کنجکاوی در کودکان ذاتی است."],["The system has inherent weaknesses.","سیستم دارای نقاط ضعف ذاتی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:dominate','dominate','v','مسلط شدن، غالب بودن، تسلط داشتن','to control or have power over; to be the most important feature','Large companies dominate the market.','[["Large companies dominate the market.","شرکت‌های بزرگ بر بازار تسلط دارند."],["The castle dominates the town.","قلعه بر شهر مسلط است."],["Men once dominated the field of science.","زمانی مردان بر عرصه علم تسلط داشتند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:extroverted','extroverted','adj','برون‌گرا','confident, lively and enjoying the company of other people','Extroverted people enjoy meeting strangers.','[["Extroverted people enjoy meeting strangers.","افراد برونگرا از ملاقات با غریبه‌ها لذت می‌برند."],["She is an extroverted student who loves group work.","او یک دانش آموز برونگرا است که عاشق کار گروهی است."],["Extroverted leaders are often good communicators.","رهبران برونگرا معمولاً ارتباطات خوبی دارند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:withdraw','withdraw','v','عقب‌نشینی کردن؛ پس گرفتن؛ برداشت کردن (پول)','to move back or away; to take something out or back','The army withdrew from the city.','[["The army withdrew from the city.","ارتش از شهر عقب نشینی کرد."],["He withdrew money from the bank.","از بانک پول برداشت."],["The company withdrew the product after complaints.","این شرکت پس از شکایت محصول را پس گرفت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:rehabilitate','rehabilitate','v','توانبخشی کردن، بازپروری کردن','to help someone return to a normal life after illness or prison; to restore to good condition','The center rehabilitates injured wild animals.','[["The center rehabilitates injured wild animals.","این مرکز حیوانات وحشی آسیب دیده را بازپروری می‌کند."],["Patients are rehabilitated after surgery.","بیماران پس از جراحی توانبخشی می‌شوند."],["The program aims to rehabilitate young offenders.","هدف این برنامه بازپروری مجرمان جوان است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fungus','fungus','n','قارچ (موجود)','a type of organism such as a mushroom or mould that gets food from dead or living matter','The tree was killed by a fungus.','[["The tree was killed by a fungus.","درخت توسط قارچ کشته شد."],["Some types of fungus are used to make medicine.","از برخی از انواع قارچ‌ها برای تهیه دارو استفاده می‌شود."],["Fungi play an important role in breaking down dead plants.","قارچ‌ها نقش مهمی در شکستن گیاهان مرده دارند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:stamina','stamina','n','استقامت، توان جسمی','the physical or mental strength to continue doing something for a long time','Long-distance runners need great stamina.','[["Long-distance runners need great stamina.","دوندگان مسافت‌های طولانی به استقامت زیادی نیاز دارند."],["Swimming builds stamina.","شنا باعث ایجاد استقامت می‌شود."],["The job requires mental stamina.","کار مستلزم استقامت ذهنی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:tolerance','tolerance','n','تحمل، مدارا','the ability to accept or bear something; willingness to accept different opinions','Some plants have a high tolerance for salt.','[["Some plants have a high tolerance for salt.","برخی از گیاهان تحمل زیادی به نمک دارند."],["We should show tolerance towards other cultures.","ما باید نسبت به فرهنگ‌های دیگر مدارا نشان دهیم."],["His tolerance for pain is remarkable.","تحمل او در برابر درد قابل توجه است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:acquire','acquire','v','به دست آوردن، کسب کردن','to get or gain something, such as knowledge or skills','Children acquire language naturally.','[["Children acquire language naturally.","کودکان زبان را به طور طبیعی فرا می‌گیرند."],["The museum acquired the painting in 1990.","موزه این نقاشی را در سال 1990 به دست آورد."],["She acquired a good knowledge of Arabic.","او دانش عربی را به خوبی کسب کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:plausible','plausible','adj','باورپذیر، معقول','seeming reasonable or likely to be true','Her explanation sounded plausible.','[["Her explanation sounded plausible.","توضیح او قابل قبول به نظر می‌رسید."],["Scientists offered a plausible theory for the extinction.","دانشمندان یک نظریه قابل قبول برای انقراض ارائه کردند."],["It is plausible that the city was built by traders.","این احتمال وجود دارد که شهر توسط بازرگانان ساخته شده باشد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:transformation','transformation','n','تحول، دگرگونی','a complete change in the appearance or character of something','The city has undergone a complete transformation.','[["The city has undergone a complete transformation.","این شهر دستخوش دگرگونی کامل شده است."],["The transformation of a caterpillar into a butterfly is amazing.","تبدیل کاترپیلار به پروانه شگفت انگیز است."],["Digital technology caused a transformation in education.","فناوری دیجیتال باعث تحول در آموزش شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:archaeology','archaeology','n','باستان‌شناسی','the study of ancient cultures by examining their remains','She studied archaeology at university.','[["She studied archaeology at university.","او در دانشگاه باستان شناسی خوانده است."],["Archaeology tells us how ancient people lived.","باستان شناسی به ما می‌گوید که مردم باستان چگونه زندگی می‌کردند."],["Modern archaeology uses satellite images.","باستان شناسی مدرن از تصاویر ماهواره ای استفاده می‌کند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:principle','principle','n','اصل، قاعده','a basic truth or rule that explains how something works or guides behavior','The machine works on a simple principle.','[["The machine works on a simple principle.","دستگاه بر اساس یک اصل ساده کار می‌کند."],["Equality is a fundamental principle of democracy.","برابری یک اصل اساسی دموکراسی است."],["He refused on principle.","او در اصل امتناع کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ancestor','ancestor','n','نیا، جد','a person or animal from whom one is descended','Our ancestors lived by hunting and gathering.','[["Our ancestors lived by hunting and gathering.","اجداد ما با شکار و گردآوری زندگی می‌کردند."],["The horse''s ancestor was much smaller.","جد اسب خیلی کوچکتر بود."],["Humans and apes share a common ancestor.","انسان‌ها و میمون‌ها اجداد مشترکی دارند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:evolution','evolution','n','تکامل؛ تحول تدریجی','the gradual development of living things over time; gradual change','Darwin developed the theory of evolution.','[["Darwin developed the theory of evolution.","داروین نظریه تکامل را توسعه داد."],["The evolution of birds from dinosaurs is well documented.","تکامل پرندگان از دایناسورها به خوبی مستند شده است."],["The book describes the evolution of the English language.","این کتاب سیر تکاملی زبان انگلیسی را شرح می‌دهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:derelict','derelict','adj','متروکه، مخروبه','in very bad condition because it has not been used or cared for','The old factory is now derelict.','[["The old factory is now derelict.","کارخانه قدیمی اکنون متروکه است."],["They turned a derelict building into a museum.","آنها یک ساختمان متروک را به موزه تبدیل کردند."],["Derelict land was turned into a public park.","زمین متروکه به یک پارک عمومی تبدیل شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:irreversible','irreversible','adj','برگشت‌ناپذیر','impossible to change back to a previous condition','Some damage to the environment is irreversible.','[["Some damage to the environment is irreversible.","برخی آسیب‌ها به محیط زیست غیر قابل برگشت است."],["The disease causes irreversible brain damage.","این بیماری باعث آسیب غیرقابل برگشت مغز می‌شود."],["It was an irreversible decision.","این یک تصمیم برگشت ناپذیر بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cemetery','cemetery','n','قبرستان، گورستان','a place where dead people are buried','The ancient cemetery contains hundreds of graves.','[["The ancient cemetery contains hundreds of graves.","گورستان باستانی شامل صدها قبر است."],["Archaeologists excavated a Roman cemetery.","باستان شناسان یک گورستان رومی را کاوش کردند."],["His grandparents are buried in the local cemetery.","پدربزرگ و مادربزرگ او در قبرستان محلی دفن شده اند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:characteristic','characteristic','n','ویژگی، خصوصیت','a typical quality or feature of a person or thing','Long necks are a characteristic of giraffes.','[["Long necks are a characteristic of giraffes.","گردن بلند از ویژگی‌های زرافه هاست."],["What are the main characteristics of this climate?","ویژگی‌های اصلی این اقلیم چیست؟"],["Honesty is one of his best characteristics.","صداقت یکی از بهترین خصوصیات اوست."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:seedling','seedling','n','نهال، گیاه جوان','a young plant grown from a seed','Plant the seedlings in spring.','[["Plant the seedlings in spring.","نهال‌ها را در بهار بکارید."],["Thousands of seedlings were planted to restore the forest.","هزاران نهال برای احیای جنگل کاشته شد."],["Seedlings need plenty of light and water.","نهال‌ها به نور و آب فراوان نیاز دارند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:retain','retain','v','حفظ کردن، نگه داشتن','to keep or continue to have something','Clay soil retains water well.','[["Clay soil retains water well.","خاک رسی آب را به خوبی حفظ می‌کند."],["The town has retained its traditional character.","این شهر ویژگی سنتی خود را حفظ کرده است."],["Repetition helps students retain new vocabulary.","تکرار به دانش آموزان کمک می‌کند واژگان جدید را حفظ کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:equivalent','equivalent','adj','معادل، هم‌ارز','equal in value, amount, meaning or importance','One kilometre is equivalent to about 0.62 miles.','[["One kilometre is equivalent to about 0.62 miles.","یک کیلومتر معادل حدود 0.62 مایل است."],["There is no equivalent word in Persian.","در فارسی کلمه معادلی وجود ندارد."],["The degree is equivalent to a master''s degree.","مدرک معادل فوق لیسانس می‌باشد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intriguing','intriguing','adj','جذاب، کنجکاوی‌برانگیز','very interesting because unusual or mysterious','The results of the study are intriguing.','[["The results of the study are intriguing.","نتایج مطالعه جالب است."],["She told an intriguing story about her travels.","او داستانی جالب از سفرهایش تعریف کرد."],["An intriguing question is why some birds migrate at night.","یک سوال جالب این است که چرا برخی از پرندگان در شب مهاجرت می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:abundant','abundant','adj','فراوان، وافر','existing in large amounts','Fish are abundant in these waters.','[["Fish are abundant in these waters.","ماهی در این آب‌ها فراوان است."],["The region has abundant rainfall.","این منطقه دارای بارندگی فراوان است."],["Abundant food allowed the population to grow.","غذای فراوان باعث رشد جمعیت شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:likelihood','likelihood','n','احتمال','the chance that something will happen','There is a strong likelihood of rain tomorrow.','[["There is a strong likelihood of rain tomorrow.","فردا احتمال بارش شدید وجود دارد."],["Exercise reduces the likelihood of heart disease.","ورزش احتمال بیماری قلبی را کاهش می‌دهد."],["In all likelihood, the project will be delayed.","به احتمال زیاد این پروژه به تعویق خواهد افتاد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:assumption','assumption','n','فرض، گمان','something that you accept as true without proof','The theory is based on a false assumption.','[["The theory is based on a false assumption.","این نظریه مبتنی بر یک فرض غلط است."],["We made the assumption that prices would stay the same.","ما این فرض را داشتیم که قیمت‌ها ثابت می‌ماند."],["Scientists questioned the assumption that the planet was dead.","دانشمندان فرض مرده بودن سیاره را زیر سوال بردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:juvenile','juvenile','adj','نوجوان، نابالغ؛ مربوط به نوجوانان','relating to young people or young animals','Juvenile crime has decreased in the city.','[["Juvenile crime has decreased in the city.","جرایم نوجوانان در این شهر کاهش یافته است."],["Juvenile birds have brown feathers.","پرندگان جوان پرهای قهوه ای دارند."],["The fish return to the sea after their juvenile stage.","ماهی‌ها پس از مرحله جوانی به دریا باز می‌گردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:disrupt','disrupt','v','مختل کردن، برهم زدن','to stop something from continuing normally','The storm disrupted flights across the country.','[["The storm disrupted flights across the country.","طوفان باعث اختلال در پروازهای سراسر کشور شد."],["Noise can disrupt sleep.","سر و صدا می‌تواند خواب را مختل کند."],["The new road disrupted the habitat of many animals.","جاده جدید زیستگاه بسیاری از حیوانات را مختل کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:evolve','evolve','v','تکامل یافتن، به‌تدریج تغییر کردن','to develop gradually over time','Whales evolved from land animals.','[["Whales evolved from land animals.","نهنگ‌ها از حیوانات خشکی تکامل یافته اند."],["The company has evolved into a global business.","این شرکت به یک تجارت جهانی تبدیل شده است."],["Languages evolve over centuries.","زبان‌ها در طول قرن‌ها تکامل می‌یابند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:demographic','demographic','adj','جمعیتی، جمعیت‌شناختی','relating to the structure and changes of a population','Demographic changes affect the job market.','[["Demographic changes affect the job market.","تغییرات جمعیتی بر بازار کار تأثیر می‌گذارد."],["The census provides demographic data.","سرشماری داده‌های جمعیت شناختی را ارائه می‌دهد."],["Japan faces serious demographic challenges.","ژاپن با چالش‌های جمعیتی جدی مواجه است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fleet','fleet','n','ناوگان','a group of ships, planes or vehicles owned or controlled by one organization','The company operates a fleet of buses.','[["The company operates a fleet of buses.","این شرکت دارای ناوگان اتوبوسرانی است."],["The fishing fleet returned to the harbor.","ناوگان ماهیگیری به بندر بازگشت."],["The navy sent its fleet to the region.","نیروی دریایی ناوگان خود را به منطقه اعزام کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:crop','crop','n','محصول کشاورزی','a plant grown in large amounts, especially for food','Wheat is the main crop in this region.','[["Wheat is the main crop in this region.","گندم محصول اصلی این منطقه است."],["The drought destroyed the crops.","خشکسالی باعث نابودی محصولات شد."],["Farmers rotate their crops to keep the soil fertile.","کشاورزان محصولات خود را به چرخش در می‌آورند تا خاک حاصلخیز بماند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:erode','erode','v','فرسوده کردن، فرسایش یافتن؛ تضعیف کردن','to gradually damage or destroy the surface of something; to weaken gradually','The sea has eroded the cliffs.','[["The sea has eroded the cliffs.","دریا صخره‌ها را فرسایش داده است."],["Soil is eroded by wind and rain.","خاک در اثر باد و باران فرسایش می‌یابد."],["Public trust in the government has been eroded.","اعتماد عمومی به دولت از بین رفته است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:drastic','drastic','adj','شدید، جدی، اساسی','severe and having a sudden, strong effect','Drastic measures are needed to save the species.','[["Drastic measures are needed to save the species.","اقدامات جدی برای نجات گونه مورد نیاز است."],["The company made drastic cuts to its budget.","این شرکت بودجه خود را به شدت کاهش داد."],["There has been a drastic fall in rainfall.","بارندگی به شدت کاهش یافته است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intact','intact','adj','سالم، دست‌نخورده','complete and not damaged','The ancient temple has remained intact.','[["The ancient temple has remained intact.","معبد باستانی دست نخورده باقی مانده است."],["Despite the fire, the documents were intact.","با وجود آتش سوزی، اسناد دست نخورده بود."],["The fossil was found almost intact.","فسیل تقریباً دست نخورده پیدا شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:vertical','vertical','adj','عمودی','standing or pointing straight up','The cliff is almost vertical.','[["The cliff is almost vertical.","صخره تقریباً عمودی است."],["Draw a vertical line down the middle of the page.","یک خط عمودی در وسط صفحه بکشید."],["Vertical farming grows crops in tall buildings.","کشاورزی عمودی محصولات را در ساختمان‌های بلند رشد می‌دهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:initiate','initiate','v','آغاز کردن، راه‌اندازی کردن','to cause something to begin','The government initiated a program to plant trees.','[["The government initiated a program to plant trees.","دولت برنامه ای را برای کاشت درخت آغاز کرد."],["Who initiated the conversation?","چه کسی گفتگو را آغاز کرد؟"],["The reaction is initiated by heat.","واکنش با گرما آغاز می‌شود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:horizontal','horizontal','adj','افقی','flat and parallel to the ground','Draw a horizontal line across the page.','[["Draw a horizontal line across the page.","یک خط افقی روی صفحه بکشید."],["The rock layers are horizontal.","لایه‌های سنگ افقی هستند."],["The graph''s horizontal axis shows time.","محور افقی نمودار زمان را نشان می‌دهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:collaboration','collaboration','n','همکاری','the act of working together with others','The project was a collaboration between two universities.','[["The project was a collaboration between two universities.","این پروژه با همکاری دو دانشگاه بود."],["Scientific progress depends on international collaboration.","پیشرفت علمی به همکاری بین المللی بستگی دارد."],["The book was written in collaboration with a journalist.","این کتاب با همکاری یک روزنامه نگار نوشته شده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:drought','drought','n','خشکسالی','a long period with little or no rain','The drought lasted for three years.','[["The drought lasted for three years.","خشکسالی سه سال به طول انجامید."],["Many animals died during the drought.","بسیاری از حیوانات در طول خشکسالی مردند."],["Drought is a serious problem in central Iran.","خشکسالی یک معضل جدی در مرکز ایران است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:wreck','wreck','n','لاشه (کشتی، هواپیما)، خرابه','a ship, car or plane that has been badly damaged or destroyed','Divers explored the wreck of an old ship.','[["Divers explored the wreck of an old ship.","غواصان لاشه یک کشتی قدیمی را کاوش کردند."],["The car was a complete wreck after the accident.","ماشین بعد از تصادف کاملاً خراب شد."],["The wreck lies at the bottom of the sea.","این کشتی در ته دریا قرار دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:pesticide','pesticide','n','آفت‌کش، سم دفع آفات','a chemical used to kill insects or other animals that damage crops','Pesticides can harm bees.','[["Pesticides can harm bees.","آفت کش‌ها می‌توانند به زنبورها آسیب برسانند."],["Organic farmers do not use chemical pesticides.","کشاورزان ارگانیک از آفت کش‌های شیمیایی استفاده نمی‌کنند."],["The use of pesticides has increased crop yields.","استفاده از سموم دفع آفات باعث افزایش عملکرد محصول شده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:feasible','feasible','adj','عملی، امکان‌پذیر، شدنی','possible and likely to succeed','Is it feasible to build a bridge here?','[["Is it feasible to build a bridge here?","آیا ساختن پل در اینجا امکان پذیر است؟"],["The plan is not economically feasible.","این طرح از نظر اقتصادی قابل اجرا نیست."],["Scientists are studying whether it is feasible to live on Mars.","دانشمندان در حال بررسی این هستند که آیا امکان زندگی در مریخ وجود دارد یا خیر."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:edible','edible','adj','خوراکی، قابل خوردن','safe to eat','Some wild mushrooms are edible, but others are poisonous.','[["Some wild mushrooms are edible, but others are poisonous.","برخی از قارچ‌های وحشی خوراکی هستند، اما برخی دیگر سمی هستند."],["The leaves of this plant are edible.","برگ‌های این گیاه خوراکی است."],["Edible insects may be the food of the future.","حشرات خوراکی ممکن است غذای آینده باشند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:distinct','distinct','adj','متمایز، مجزا؛ واضح','clearly different or separate; easy to notice','There are three distinct groups in the population.','[["There are three distinct groups in the population.","سه گروه متمایز در جمعیت وجود دارد."],["Each region has a distinct dialect.","هر منطقه یک گویش مجزا دارد."],["There is a distinct smell of smoke.","بوی مشخصی از دود به مشام می‌رسد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prohibit','prohibit','v','ممنوع کردن، منع کردن','to officially forbid something','Smoking is prohibited in public buildings.','[["Smoking is prohibited in public buildings.","سیگار کشیدن در ساختمان‌های عمومی ممنوع است."],["The law prohibits the sale of alcohol to minors.","قانون فروش مشروبات الکلی به افراد زیر سن قانونی را ممنوع کرده است."],["Fishing is prohibited in this area.","ماهیگیری در این منطقه ممنوع است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:precise','precise','adj','دقیق، صحیح','exact and accurate','We need precise measurements.','[["We need precise measurements.","ما به اندازه گیری‌های دقیق نیاز داریم."],["It is hard to give a precise date.","تعیین تاریخ دقیق دشوار است."],["Scientists used precise instruments to record the earthquake.","دانشمندان از ابزار دقیقی برای ثبت زمین لرزه استفاده کردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:enclose','enclose','v','محصور کردن؛ پیوست کردن','to surround something completely; to put something in an envelope with a letter','The garden is enclosed by a high wall.','[["The garden is enclosed by a high wall.","باغ توسط یک دیوار بلند محصور شده است."],["Please find enclosed a copy of the contract.","لطفاً یک نسخه از قرارداد را پیوست کنید."],["The animals are kept in an enclosed area.","حیوانات در یک منطقه بسته نگهداری می‌شوند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:innovative','innovative','adj','نوآورانه، خلاق','using new methods or ideas','The company is known for its innovative products.','[["The company is known for its innovative products.","این شرکت به خاطر محصولات نوآورانه خود شناخته شده است."],["She came up with an innovative solution.","او با یک راه حل خلاقانه آمد."],["Innovative teaching methods can improve learning.","روش‌های نوین تدریس می‌تواند یادگیری را بهبود بخشد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:keen','keen','adj','مشتاق، علاقه‌مند؛ تیز (حس)','very interested or eager; (of senses) very sensitive','She is keen to learn Spanish.','[["She is keen to learn Spanish.","او مشتاق یادگیری اسپانیایی است."],["He is a keen gardener.","او باغبان مشتاقی است."],["Dogs have a keen sense of smell.","سگ‌ها حس بویایی قوی دارند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:diminish','diminish','v','کاهش یافتن، کم کردن','to become or make something smaller or less','The pain diminished after a few days.','[["The pain diminished after a few days.","درد بعد از چند روز کاهش یافت."],["The number of wild tigers has diminished.","تعداد ببرهای وحشی کاهش یافته است."],["Nothing could diminish her enthusiasm.","هیچ چیز نمی‌توانست از شور و شوق او بکاهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:concept','concept','n','مفهوم، انگاره','an idea or principle','The concept of time is difficult to explain.','[["The concept of time is difficult to explain.","توضیح مفهوم زمان دشوار است."],["Children learn basic mathematical concepts.","کودکان مفاهیم اولیه ریاضی را یاد می‌گیرند."],["The concept of recycling is not new.","مفهوم بازیافت جدید نیست."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:dismantle','dismantle','v','پیاده کردن، از هم باز کردن؛ برچیدن','to take something apart; to end a system or organization gradually','The engine was dismantled and cleaned.','[["The engine was dismantled and cleaned.","موتور برچیده و تمیز شد."],["The old bridge was dismantled.","پل قدیمی برچیده شد."],["The government dismantled the old tax system.","دولت سیستم مالیاتی قدیمی را از بین برد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:sediment','sediment','n','رسوب، ته‌نشست','sand, stones or mud that settle at the bottom of a liquid','Rivers carry sediment to the sea.','[["Rivers carry sediment to the sea.","رودخانه‌ها رسوبات را به دریا می‌برند."],["Fossils are found in layers of sediment.","فسیل‌ها در لایه‌های رسوب یافت می‌شوند."],["The sediment slowly turned into rock.","رسوب به آرامی تبدیل به سنگ شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:float','float','v','شناور بودن، معلق ماندن','to stay on the surface of a liquid or move slowly through the air','Ice floats on water.','[["Ice floats on water.","یخ روی آب شناور است."],["Leaves floated down the river.","برگها در رودخانه شناور بودند."],["Balloons floated in the sky.","بالن‌ها در آسمان شناور بودند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fragile','fragile','adj','شکننده، آسیب‌پذیر','easily broken or damaged','Coral reefs are fragile ecosystems.','[["Coral reefs are fragile ecosystems.","صخره‌های مرجانی اکوسیستم‌های شکننده ای هستند."],["Old manuscripts are very fragile.","دست نوشته‌های قدیمی بسیار شکننده هستند."],["The economy is still fragile.","اقتصاد هنوز شکننده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cog','cog','n','چرخ‌دنده؛ مهره (کوچک یک سیستم)','one of the teeth on the edge of a wheel in a machine; an unimportant part of a large system','The cogs of the old clock were made of wood.','[["The cogs of the old clock were made of wood.","چرخ دنده‌های ساعت قدیمی از چوب ساخته شده بود."],["The machine stopped because a cog was broken.","ماشین متوقف شد چون یک چرخ دنده شکسته بود."],["He felt like a small cog in a big machine.","او مانند یک چرخ دنده کوچک در یک ماشین بزرگ احساس می‌کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:dominance','dominance','n','تسلط، برتری','power or control over others','The company has achieved dominance in the market.','[["The company has achieved dominance in the market.","این شرکت به برتری در بازار دست یافته است."],["The dominance of English on the internet is decreasing.","تسلط انگلیسی در اینترنت در حال کاهش است."],["Male gorillas fight for dominance.","گوریل‌های نر برای تسلط مبارزه می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:weld','weld','v','جوش دادن','to join pieces of metal by heating them','The pipes were welded together.','[["The pipes were welded together.","لوله‌ها به هم جوش داده شدند."],["He learned to weld at technical school.","جوشکاری را در دانشکده فنی آموخت."],["Robots weld car parts in modern factories.","ربات‌ها قطعات خودرو را در کارخانه‌های مدرن جوش می‌دهند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:refute','refute','v','رد کردن، نقض کردن','to prove that a statement or theory is wrong','New evidence refuted the old theory.','[["New evidence refuted the old theory.","شواهد جدید نظریه قدیمی را رد کرد."],["She refuted the claims against her.","او ادعاهای علیه خود را رد کرد."],["Scientists have refuted the idea that the Earth is flat.","دانشمندان این ایده که زمین مسطح است را رد کرده اند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:commemorate','commemorate','v','بزرگداشت گرفتن، یادبود برگزار کردن','to do something to remember an important person or event','A statue was built to commemorate the poet.','[["A statue was built to commemorate the poet.","مجسمه ای به یاد شاعر ساخته شد."],["The festival commemorates the founding of the city.","این جشنواره یادبود تأسیس شهر است."],["Stamps were issued to commemorate the anniversary.","تمبرهایی برای بزرگداشت این سالگرد صادر شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deforestation','deforestation','n','جنگل‌زدایی','the cutting down of trees in a large area','Deforestation is destroying the Amazon rainforest.','[["Deforestation is destroying the Amazon rainforest.","جنگل زدایی جنگل‌های آمازون را نابود می‌کند."],["Deforestation contributes to climate change.","جنگل زدایی به تغییرات آب و هوایی کمک می‌کند."],["Soil erosion is a result of deforestation.","فرسایش خاک نتیجه جنگل زدایی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:consist of','consist of','phr','تشکیل شدن از، شامل بودن','to be made of particular parts or things','The team consists of five scientists.','[["The team consists of five scientists.","این تیم متشکل از پنج دانشمند است."],["Water consists of hydrogen and oxygen.","آب از هیدروژن و اکسیژن تشکیل شده است."],["The test consists of three sections.","آزمون از سه بخش تشکیل شده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ingenious','ingenious','adj','مبتکرانه، هوشمندانه','very clever and original','The qanat is an ingenious system for carrying water.','[["The qanat is an ingenious system for carrying water.","قنات یک سیستم مبتکرانه برای حمل آب است."],["She came up with an ingenious solution.","او با یک راه حل مبتکرانه آمد."],["The inventor created an ingenious device.","مخترع دستگاهی مبتکرانه ساخت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inevitable','inevitable','adj','اجتناب‌ناپذیر، حتمی','certain to happen and impossible to avoid','Some changes are inevitable.','[["Some changes are inevitable.","برخی تغییرات اجتناب ناپذیر هستند."],["Without rain, crop failure was inevitable.","بدون باران، شکست محصول اجتناب ناپذیر بود."],["It was inevitable that the old system would fail.","شکست سیستم قدیمی اجتناب ناپذیر بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:haphazard','haphazard','adj','بی‌نظم، بی‌برنامه، اتفاقی','not organized or planned','The city grew in a haphazard way.','[["The city grew in a haphazard way.","شهر به طور تصادفی رشد کرد."],["The books were arranged in a haphazard manner.","کتاب‌ها به صورت تصادفی چیده شده بودند."],["A haphazard approach to study rarely works.","یک رویکرد تصادفی برای مطالعه به ندرت جواب می‌دهد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:consequently','consequently','adv','در نتیجه، بنابراین','as a result','He did not study; consequently, he failed the exam.','[["He did not study; consequently, he failed the exam.","درس نخواند؛ در نتیجه در امتحان مردود شد."],["The forest was cut down and, consequently, many animals died.","جنگل قطع شد و در نتیجه حیوانات زیادی مردند."],["Prices rose and consequently sales fell.","قیمت‌ها افزایش یافت و در نتیجه فروش کاهش یافت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:sceptic','sceptic','n','شکاک، آدم بدبین (به یک ادعا)','a person who doubts that something is true or useful','Sceptics doubt that the plan will work.','[["Sceptics doubt that the plan will work.","شکاکان شک دارند که این طرح عملی شود."],["Even the sceptics were impressed by the results.","حتی شکاکان نیز تحت تأثیر نتایج قرار گرفتند."],["He is a sceptic about alternative medicine.","او نسبت به طب جایگزین بدبین است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:large-scale','large-scale','adj','در مقیاس بزرگ، گسترده','involving many people or things; happening over a large area','Large-scale farming uses a lot of water.','[["Large-scale farming uses a lot of water.","کشاورزی در مقیاس بزرگ آب زیادی مصرف می‌کند."],["There was large-scale damage after the storm.","پس از طوفان خسارات زیادی وارد شد."],["The government planned a large-scale vaccination program.","دولت یک برنامه واکسیناسیون در مقیاس بزرگ را برنامه ریزی کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:masterpiece','masterpiece','n','شاهکار','an excellent piece of art, writing or work, or the best work of an artist','The Mona Lisa is a masterpiece.','[["The Mona Lisa is a masterpiece.","مونالیزا یک شاهکار است."],["The Shahnameh is a masterpiece of Persian literature.","شاهنامه شاهکار ادبیات فارسی است."],["The bridge is a masterpiece of engineering.","پل یک شاهکار مهندسی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:proponent','proponent','n','طرفدار، حامی','a person who supports an idea or plan','Proponents of nuclear energy say it is clean.','[["Proponents of nuclear energy say it is clean.","طرفداران انرژی هسته ای می‌گویند که این انرژی پاک است."],["She is a leading proponent of online learning.","او یکی از حامیان اصلی یادگیری آنلاین است."],["Proponents argue that the law will reduce crime.","موافقان معتقدند که این قانون باعث کاهش جرم و جنایت می‌شود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ambiguous','ambiguous','adj','مبهم، دوپهلو','having more than one possible meaning; unclear','The question was ambiguous.','[["The question was ambiguous.","سوال مبهم بود."],["The results of the experiment were ambiguous.","نتایج آزمایش مبهم بود."],["He gave an ambiguous answer.","جواب مبهم داد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:transparent','transparent','adj','شفاف؛ روشن و قابل‌درک','clear enough to see through; open and honest','Glass is transparent.','[["Glass is transparent.","شیشه شفاف است."],["The government promised a more transparent system.","دولت وعده داده است که یک سیستم شفاف‌تر داشته باشد."],["Some deep-sea animals have transparent bodies.","برخی از حیوانات اعماق دریا دارای بدن شفاف هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:scrutinize','scrutinize','v','موشکافانه بررسی کردن','to examine something very carefully','Scientists scrutinized the data for errors.','[["Scientists scrutinized the data for errors.","دانشمندان داده‌ها را برای خطاها بررسی کردند."],["The committee scrutinized every detail of the plan.","کمیته تمام جزئیات طرح را مورد بررسی قرار داد."],["Customs officers scrutinized his passport.","ماموران گمرک پاسپورت او را بررسی کردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:decipher','decipher','v','رمزگشایی کردن، کشف معنا کردن','to discover the meaning of something difficult to read or understand','Scholars deciphered the ancient inscription.','[["Scholars deciphered the ancient inscription.","دانشمندان کتیبه باستانی را رمزگشایی کردند."],["I couldn''t decipher his handwriting.","نتوانستم دستخطش را رمزگشایی کنم."],["It took years to decipher the code.","رمزگشایی کد سال‌ها طول کشید."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:replenish','replenish','v','دوباره پر کردن، جایگزین کردن','to fill something again or replace what has been used','Rain replenishes underground water.','[["Rain replenishes underground water.","باران آب زیرزمینی را پر می‌کند."],["Drink water to replenish fluids after exercise.","بعد از ورزش آب بنوشید تا مایعات را دوباره پر کنید."],["Fish stocks need time to replenish.","ذخایر ماهی برای تکمیل مجدد نیاز به زمان دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:meticulous','meticulous','adj','بسیار دقیق، موشکاف','very careful and paying attention to every detail','The scientist kept meticulous records.','[["The scientist kept meticulous records.","این دانشمند سوابق دقیقی داشت."],["Restoring old paintings requires meticulous work.","بازسازی تابلوهای قدیمی نیاز به کار دقیق دارد."],["She is meticulous about her research.","او در مورد تحقیقات خود دقیق است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:implement','implement','v','اجرا کردن، به کار بستن','to start using a plan or system','The new rules will be implemented next year.','[["The new rules will be implemented next year.","قوانین جدید در سال آینده اجرا می‌شود."],["The city implemented a recycling program.","این شهر برنامه بازیافت را اجرا کرد."],["It is easier to make plans than to implement them.","برنامه ریزی آسان‌تر از اجرای آن است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hypothesis','hypothesis','n','فرضیه','an idea that is suggested as a possible explanation and needs to be tested','The experiment was designed to test the hypothesis.','[["The experiment was designed to test the hypothesis.","آزمایش برای آزمون فرضیه طراحی شد."],["The data support the hypothesis.","داده‌ها فرضیه را تایید می‌کنند."],["Scientists proposed a new hypothesis about the origin of life.","دانشمندان فرضیه جدیدی در مورد منشا حیات ارائه کردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:radiation','radiation','n','تابش، تشعشع','energy that comes from a source as heat, light or harmful rays','Sunscreen protects skin from ultraviolet radiation.','[["Sunscreen protects skin from ultraviolet radiation.","کرم ضد آفتاب از پوست در برابر اشعه ماوراء بنفش محافظت می‌کند."],["Exposure to radiation can cause cancer.","قرار گرفتن در معرض اشعه می‌تواند باعث سرطان شود."],["The Earth absorbs radiation from the sun.","زمین تابش خورشید را جذب می‌کند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:adapt','adapt','v','سازگار شدن، تطبیق دادن','to change to suit new conditions','Animals must adapt to survive.','[["Animals must adapt to survive.","حیوانات برای زنده ماندن باید سازگار شوند."],["Camels have adapted to desert life.","شترها با زندگی بیابانی سازگار شده اند."],["The novel was adapted for television.","این رمان برای تلویزیون اقتباس شده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cocoon','cocoon','n','پیله','a silk covering made by some insects to protect themselves while they develop','The caterpillar spins a cocoon.','[["The caterpillar spins a cocoon.","کاترپیلار یک پیله می‌چرخد."],["Silk is made from the cocoons of silkworms.","ابریشم از پیله‌های کرم ابریشم به دست می‌آید."],["The moth emerged from its cocoon.","پروانه از پیله خود بیرون آمد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:nurture','nurture','v','پرورش دادن، تربیت کردن، پروراندن','to care for and help someone or something grow and develop','Parents nurture their children.','[["Parents nurture their children.","والدین فرزندان خود را تربیت می‌کنند."],["The school nurtures young talent.","مدرسه استعدادهای جوان را پرورش می‌دهد."],["Birds nurture their young until they can fly.","پرندگان بچه‌های خود را تا زمانی که بتوانند پرواز کنند پرورش می‌دهند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unravel','unravel','v','باز کردن (گره)؛ کشف کردن، حل کردن','to separate twisted threads; to solve or explain something complicated','Scientists are trying to unravel the mysteries of the brain.','[["Scientists are trying to unravel the mysteries of the brain.","دانشمندان در تلاش برای کشف رازهای مغز هستند."],["The rope began to unravel.","طناب شروع به باز شدن کرد."],["Detectives unraveled the truth.","کارآگاهان حقیقت را کشف کردند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:identical twin','identical twin','n','دوقلوی همسان','one of two children born at the same time from the same egg, who look exactly alike','Identical twins share the same genes.','[["Identical twins share the same genes.","دوقلوهای همسان ژن‌های مشابهی دارند."],["Studies of identical twins help scientists understand heredity.","مطالعات روی دوقلوهای همسان به دانشمندان کمک می‌کند تا وراثت را درک کنند."],["She has an identical twin sister.","او یک خواهر دوقلوی همسان دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:subsequently','subsequently','adv','متعاقباً، سپس، بعداً','after something else has happened','He was arrested and subsequently released.','[["He was arrested and subsequently released.","وی دستگیر و سپس آزاد شد."],["The disease subsequently spread to other countries.","این بیماری متعاقباً به کشورهای دیگر سرایت کرد."],["The theory was subsequently proved wrong.","بعداً ثابت شد که این نظریه اشتباه است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ailment','ailment','n','بیماری، ناخوشی (معمولاً جزئی)','an illness, usually not serious','The plant was used to treat common ailments.','[["The plant was used to treat common ailments.","از این گیاه برای درمان بیماری‌های رایج استفاده می‌شد."],["Headaches are a common ailment.","سردرد یک بیماری شایع است."],["Many ailments are caused by poor diet.","بسیاری از بیماری‌ها ناشی از رژیم غذایی نامناسب است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:vulnerable','vulnerable','adj','آسیب‌پذیر','easily harmed or attacked','Children are vulnerable to infection.','[["Children are vulnerable to infection.","کودکان در برابر عفونت آسیب پذیر هستند."],["Coastal cities are vulnerable to flooding.","شهرهای ساحلی در برابر سیل آسیب پذیر هستند."],["The species is vulnerable to climate change.","این گونه در برابر تغییرات آب و هوایی آسیب پذیر است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:harvest','harvest','v','برداشت کردن (محصول)','to gather crops from the fields','Farmers harvest wheat in summer.','[["Farmers harvest wheat in summer.","کشاورزان در تابستان گندم برداشت می‌کنند."],["The grapes are harvested by hand.","انگور با دست برداشت می‌شود."],["Rainwater can be harvested for use in gardens.","آب باران را می‌توان برای استفاده در باغ‌ها برداشت کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inherit','inherit','v','به ارث بردن','to receive money or property from someone who has died; to get a quality from parents','She inherited a house from her grandmother.','[["She inherited a house from her grandmother.","او خانه ای را از مادربزرگش به ارث برده است."],["Children inherit genes from both parents.","کودکان از هر دو والد ژن به ارث می‌برند."],["He inherited his father''s love of music.","او عشق پدرش به موسیقی را به ارث برده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:exotic','exotic','adj','عجیب و غیربومی، خارجی و جالب','unusual and exciting because it comes from a distant country','The garden is full of exotic plants.','[["The garden is full of exotic plants.","باغ پر از گیاهان عجیب و غریب است."],["They traveled to exotic places.","آنها به مکان‌های عجیب و غریب سفر کردند."],["Exotic species can harm local wildlife.","گونه‌های عجیب و غریب می‌توانند به حیات وحش محلی آسیب بزنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:represent','represent','v','نمایندگی کردن؛ نشان دادن، بیانگر بودن','to act or speak for someone; to be a sign or example of something','The dots on the map represent cities.','[["The dots on the map represent cities.","نقاط روی نقشه نشان دهنده شهرها هستند."],["She represented her country at the Olympics.","او نماینده کشورش در المپیک بود."],["This discovery represents a major step forward.","این کشف نشان دهنده یک گام بزرگ به جلو است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:magnificent','magnificent','adj','باشکوه، فوق‌العاده','extremely beautiful or impressive','The palace is magnificent.','[["The palace is magnificent.","کاخ با شکوه است."],["We had a magnificent view of the mountains.","ما منظره ای باشکوه از کوه‌ها داشتیم."],["The museum has a magnificent collection.","این موزه مجموعه ای باشکوه دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:eventually','eventually','adv','سرانجام، در نهایت','after a long time or many difficulties','The river eventually reaches the sea.','[["The river eventually reaches the sea.","رودخانه در نهایت به دریا می‌رسد."],["After many attempts, they eventually succeeded.","پس از تلاش‌های فراوان در نهایت موفق شدند."],["The small village eventually became a big city.","روستای کوچک در نهایت تبدیل به یک شهر بزرگ شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:component','component','n','جزء، بخش تشکیل‌دهنده','one of the parts of a machine or system','The factory produces components for cars.','[["The factory produces components for cars.","این کارخانه قطعات خودرو را تولید می‌کند."],["Trust is a key component of any relationship.","اعتماد جزء اصلی هر رابطه است."],["The main component of the air is nitrogen.","جزء اصلی هوا نیتروژن است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:route','route','n','مسیر، راه','a way from one place to another','The Silk Road was a famous trade route.','[["The Silk Road was a famous trade route.","جاده ابریشم یک مسیر تجاری معروف بود."],["Birds follow the same route every year.","پرندگان هر سال یک مسیر را دنبال می‌کنند."],["What is the fastest route to the airport?","سریع‌ترین مسیر برای رسیدن به فرودگاه کدام است؟"]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:interval','interval','n','فاصله (زمانی یا مکانی)، بازه','a period of time or space between two events or things','Trees were planted at regular intervals.','[["Trees were planted at regular intervals.","درختان در فواصل منظم کاشته شدند."],["The buses run at ten-minute intervals.","اتوبوس‌ها در فواصل ده دقیقه ای حرکت می‌کنند."],["There was a long interval between the two eruptions.","فاصله زیادی بین دو فوران وجود داشت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:heredity','heredity','n','وراثت','the passing of characteristics from parents to children through genes','Heredity plays a role in many diseases.','[["Heredity plays a role in many diseases.","وراثت در بسیاری از بیماری‌ها نقش دارد."],["Height is largely determined by heredity.","قد تا حد زیادی توسط وراثت تعیین می‌شود."],["Mendel studied heredity in pea plants.","مندل به مطالعه وراثت در گیاهان نخود پرداخت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:habitat','habitat','n','زیستگاه','the natural home of a plant or animal','Pollution is destroying the habitat of many fish.','[["Pollution is destroying the habitat of many fish.","آلودگی زیستگاه بسیاری از ماهی‌ها را از بین می‌برد."],["The panda''s natural habitat is bamboo forest.","زیستگاه طبیعی پاندا جنگل بامبو است."],["Wetlands are important habitats for birds.","تالاب‌ها زیستگاه مهمی برای پرندگان هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ultimately','ultimately','adv','در نهایت، سرانجام','finally, after a long process; at the most basic level','Ultimately, the decision is yours.','[["Ultimately, the decision is yours.","در نهایت تصمیم با شماست."],["The plan ultimately failed.","این طرح در نهایت شکست خورد."],["All life ultimately depends on the sun.","تمام زندگی در نهایت به خورشید بستگی دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:voracious','voracious','adj','حریص، پرخور؛ سیری‌ناپذیر','wanting or eating very large amounts','Locusts are voracious insects.','[["Locusts are voracious insects.","ملخ‌ها حشرات حریص هستند."],["She is a voracious reader.","او خواننده ای مشتاق است."],["The voracious fish ate everything in the pond.","ماهی حریص همه چیز را در برکه خورد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:merge','merge','v','ادغام شدن، یکی شدن','to combine or join together','The two companies merged last year.','[["The two companies merged last year.","این دو شرکت سال گذشته ادغام شدند."],["The two rivers merge near the city.","این دو رودخانه در نزدیکی شهر به هم می‌پیوندند."],["The villages gradually merged into one town.","روستاها به تدریج در یک شهر ادغام شدند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:admirable','admirable','adj','قابل تحسین، ستودنی','deserving respect and approval','She showed admirable courage.','[["She showed admirable courage.","او شجاعت قابل تحسینی از خود نشان داد."],["His patience is admirable.","صبر او قابل تحسین است."],["The project had admirable goals.","این پروژه اهداف قابل تحسینی داشت."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:evident','evident','adj','آشکار، واضح','clear and easy to see or understand','It was evident that he was tired.','[["It was evident that he was tired.","معلوم بود که خسته است."],["The effects of climate change are already evident.","اثرات تغییرات آب و هوایی در حال حاضر مشهود است."],["Her talent was evident from an early age.","استعداد او از همان دوران کودکی مشهود بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:offspring','offspring','n','فرزند، زاده (به‌ویژه حیوانات)','the young of an animal or the children of a person','The female protects her offspring.','[["The female protects her offspring.","ماده از فرزندان خود محافظت می‌کند."],["Parents pass genes to their offspring.","والدین ژن‌ها را به فرزندان خود منتقل می‌کنند."],["Some fish produce thousands of offspring.","برخی از ماهی‌ها هزاران فرزند تولید می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intrinsic','intrinsic','adj','ذاتی، درونی','belonging to the basic nature of something','The painting has little intrinsic value.','[["The painting has little intrinsic value.","این نقاشی ارزش ذاتی کمی دارد."],["Curiosity is an intrinsic part of learning.","کنجکاوی بخشی ذاتی یادگیری است."],["Intrinsic motivation comes from inside a person.","انگیزه درونی از درون فرد می‌آید."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:detrimental','detrimental','adj','زیان‌آور، مضر','causing harm or damage','Smoking is detrimental to health.','[["Smoking is detrimental to health.","سیگار برای سلامتی مضر است."],["Pollution has a detrimental effect on wildlife.","آلودگی اثرات مخربی بر حیات وحش دارد."],["Too much stress can be detrimental to performance.","استرس بیش از حد می‌تواند برای عملکرد مضر باشد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:plot','plot','n','طرح داستان؛ قطعه زمین؛ توطئه','the series of events in a story; a small piece of land; a secret plan','The plot of the novel is very complex.','[["The plot of the novel is very complex.","طرح رمان بسیار پیچیده است."],["They grow vegetables on a small plot.","آنها سبزیجات را در یک زمین کوچک پرورش می‌دهند."],["The police discovered a plot to rob the bank.","پلیس نقشه سرقت از بانک را کشف کرد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:resemble','resemble','v','شبیه بودن','to look like or be similar to someone or something','The child resembles her mother.','[["The child resembles her mother.","کودک شبیه مادرش است."],["The rock resembles a human face.","صخره شبیه چهره انسان است."],["Some insects resemble leaves.","برخی از حشرات شبیه برگ هستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:portray','portray','v','به تصویر کشیدن، نمایش دادن','to show or describe someone or something in a picture, book or film','The film portrays life in a small village.','[["The film portrays life in a small village.","این فیلم زندگی در یک روستای کوچک را به تصویر می‌کشد."],["The artist portrayed the king as a hero.","این هنرمند پادشاه را به عنوان یک قهرمان به تصویر می‌کشد."],["Scientists are often portrayed as lonely geniuses.","دانشمندان اغلب به عنوان نابغه‌های تنها به تصویر کشیده می‌شوند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:severity','severity','n','شدت، وخامت','how serious or bad something is','The severity of the storm surprised everyone.','[["The severity of the storm surprised everyone.","شدت طوفان همه را شگفت زده کرد."],["Treatment depends on the severity of the illness.","درمان بستگی به شدت بیماری دارد."],["Punishments vary in severity.","شدت مجازات‌ها متفاوت است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:subtle','subtle','adj','ظریف، نامحسوس، دقیق','not obvious; small but important','There are subtle differences between the two species.','[["There are subtle differences between the two species.","تفاوت‌های ظریفی بین این دو گونه وجود دارد."],["The change in color was subtle.","تغییر رنگ ظریف بود."],["She has a subtle sense of humor.","او حس شوخ طبعی ظریفی دارد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:graze','graze','v','چریدن، چراندن','(of animals) to eat grass in a field','Sheep were grazing on the hillside.','[["Sheep were grazing on the hillside.","گوسفندها در دامنه تپه در حال چرا بودند."],["Cattle graze in the fields all summer.","گاوها در تمام تابستان در مزارع چرا می‌کنند."],["Too many animals grazing can damage the land.","چرای بیش از حد حیوانات می‌تواند به زمین آسیب برساند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:perceive','perceive','v','درک کردن، دریافتن، تشخیص دادن','to notice or understand something; to think of something in a particular way','Some animals can perceive colors we cannot see.','[["Some animals can perceive colors we cannot see.","برخی از حیوانات می‌توانند رنگ‌هایی را که ما نمی‌بینیم درک کنند."],["The public perceived the change as positive.","عموم مردم این تغییر را مثبت تلقی کردند."],["Bats perceive objects using sound.","خفاش‌ها اجسام را با استفاده از صدا درک می‌کنند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:geometry','geometry','n','هندسه','the type of mathematics that deals with lines, angles, shapes and spaces','Islamic art uses complex geometry.','[["Islamic art uses complex geometry.","هنر اسلامی از هندسه پیچیده استفاده می‌کند."],["We studied geometry at school.","ما در مدرسه هندسه خواندیم."],["The geometry of the crystal is perfect.","هندسه کریستال عالی است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:advent','advent','n','ظهور، آمدن','the arrival or beginning of something important','The advent of the internet changed society.','[["The advent of the internet changed society.","ظهور اینترنت جامعه را تغییر داد."],["Before the advent of cars, people traveled by horse.","قبل از ظهور ماشین‌ها، مردم با اسب سفر می‌کردند."],["The advent of printing spread knowledge.","ظهور چاپ باعث گسترش دانش شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intuitive','intuitive','adj','شهودی، غریزی؛ آسان‌فهم (در کار با آن)','based on feelings rather than facts; easy to use without learning','She has an intuitive understanding of people.','[["She has an intuitive understanding of people.","او درک شهودی از مردم دارد."],["The app has an intuitive design.","برنامه دارای طراحی بصری است."],["Intuitive decisions are not always wrong.","تصمیمات شهودی همیشه اشتباه نیستند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unparalleled','unparalleled','adj','بی‌نظیر، بی‌همتا','having no equal; better or greater than any other','The city enjoyed unparalleled growth.','[["The city enjoyed unparalleled growth.","این شهر از رشد بی نظیری برخوردار بود."],["The view from the summit is unparalleled.","منظره ای از قله بی نظیر است."],["The discovery was of unparalleled importance.","این کشف از اهمیت بی نظیری برخوردار بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:adept','adept','adj','ماهر، چیره‌دست','skilled at doing something','She is adept at solving problems.','[["She is adept at solving problems.","او در حل مشکلات ماهر است."],["Monkeys are adept climbers.","میمون‌ها کوهنوردان ماهری هستند."],["He became adept at using the new software.","او در استفاده از نرم افزار جدید ماهر شد."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:conceal','conceal','v','پنهان کردن، مخفی کردن','to hide something','The animal''s color conceals it from predators.','[["The animal''s color conceals it from predators.","رنگ حیوان آن را از شکارچیان پنهان می‌کند."],["He tried to conceal his feelings.","سعی کرد احساساتش را پنهان کند."],["The entrance was concealed by trees.","ورودی توسط درختان پنهان شده بود."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:numerical','numerical','adj','عددی، مربوط به اعداد','relating to or expressed in numbers','The data are shown in numerical order.','[["The data are shown in numerical order.","داده‌ها به ترتیب عددی نشان داده شده اند."],["The test measures numerical ability.","این آزمون توانایی عددی را اندازه گیری می‌کند."],["Numerical results are given in the table.","نتایج عددی در جدول آورده شده است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:core','core','n','هسته، مرکز، بخش اصلی','the central or most important part of something','The Earth''s core is extremely hot.','[["The Earth''s core is extremely hot.","هسته زمین بسیار داغ است."],["Reading is at the core of the program.","خواندن در هسته اصلی برنامه است."],["The core of the problem is a lack of money.","هسته اصلی مشکل کمبود پول است."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:spectator','spectator','n','تماشاگر','a person who watches an event, especially a sport','Thousands of spectators watched the match.','[["Thousands of spectators watched the match.","هزاران تماشاگر این مسابقه را تماشا کردند."],["The spectators cheered loudly.","تماشاگران با صدای بلند تشویق کردند."],["Ancient Romans built huge stadiums for spectators.","رومیان باستان استادیوم‌های بزرگی برای تماشاگران می‌ساختند."]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deceptive','deceptive','adj','فریبنده، گمراه‌کننده','making you believe something that is not true','Appearances can be deceptive.','[["Appearances can be deceptive.","ظاهر می‌تواند فریبنده باشد."],["The calm sea was deceptive; the currents were strong.","دریای آرام فریبنده بود. جریانات قوی بود"],["The advertisement was deceptive.","تبلیغ فریبنده بود"]]','ielts',4,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:insight','insight','n','بینش، درک عمیق','a clear, deep understanding of a situation','The study gives new insight into animal behavior.','[["The study gives new insight into animal behavior.","این مطالعه بینش جدیدی از رفتار حیوانات می‌دهد."],["Her book offers valuable insights into Persian culture.","کتاب او بینش‌های ارزشمندی از فرهنگ ایرانی ارائه می‌دهد."],["The interview provided insight into his thinking.","این مصاحبه بینشی از تفکر او ارائه کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:merely','merely','adv','صرفاً، فقط','only; simply','It is merely a matter of time.','[["It is merely a matter of time.","صرفاً موضوع زمان است."],["The figures are merely estimates.","ارقام صرفاً تخمینی هستند."],["He was merely trying to help.","او فقط سعی می‌کرد کمک کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:thorough','thorough','adj','کامل و دقیق، جامع','done completely and carefully','The police made a thorough investigation.','[["The police made a thorough investigation.","پلیس تحقیقات کاملی انجام داد."],["She has a thorough knowledge of the subject.","او شناخت کاملی از موضوع دارد."],["A thorough cleaning removed all the dust.","یک تمیز کردن کامل تمام گرد و غبار را از بین برد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:dwell','dwell','v','ساکن بودن، زندگی کردن؛ (dwell on) فکر کردن زیاد به','to live in a place; to think or talk about something for a long time','Ancient people dwelled in caves.','[["Ancient people dwelled in caves.","مردم باستان در غارها زندگی می‌کردند."],["Some fish dwell at great depths.","برخی از ماهی‌ها در اعماق زیاد زندگی می‌کنند."],["Don''t dwell on your mistakes.","روی اشتباهاتت فکر نکن"]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:overcome','overcome','v','غلبه کردن، فائق آمدن','to succeed in dealing with a problem or difficulty','She overcame her fear of public speaking.','[["She overcame her fear of public speaking.","او بر ترس خود از سخنرانی در جمع غلبه کرد."],["Scientists overcame many technical problems.","دانشمندان بر بسیاری از مشکلات فنی غلبه کردند."],["The team overcame strong opposition to win.","این تیم با غلبه بر حریفان شدید توانست پیروز شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:stunt','stunt','n','حرکت نمایشی/خطرناک، شیرین‌کاری','a dangerous action done to entertain people, especially in films; something done to attract attention','The actor did all his own stunts.','[["The actor did all his own stunts.","این بازیگر تمام بدلکاری‌های خودش را انجام داد."],["The stunt was performed by a professional.","این شیرین کاری توسط یک حرفه ای انجام شد."],["Critics called the announcement a publicity stunt.","منتقدان این اعلامیه را یک ترفند تبلیغاتی خواندند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:allege','allege','v','ادعا کردن (بدون اثبات)','to say that something is true without giving proof','The newspaper alleged that the minister had lied.','[["The newspaper alleged that the minister had lied.","روزنامه مدعی شد که وزیر دروغ گفته است."],["It is alleged that he stole the money.","گفته می‌شود او این پول را دزدیده است."],["Critics allege that the tests are unfair.","منتقدان ادعا می‌کنند که این آزمایش‌ها ناعادلانه است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:nifty','nifty','adj','زیرکانه و کاربردی، هوشمندانه','cleverly designed and useful','This is a nifty little tool for cutting glass.','[["This is a nifty little tool for cutting glass.","این یک ابزار کوچک زیبا برای برش شیشه است."],["The app has some nifty features.","این برنامه دارای ویژگی‌های جالبی است."],["She found a nifty way to save space.","او یک راه خوب برای صرفه جویی در فضا پیدا کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:insulate','insulate','v','عایق‌بندی کردن، جدا نگه داشتن','to cover something to stop heat, sound or electricity from passing through','Thick walls insulate the house from the cold.','[["Thick walls insulate the house from the cold.","دیوارهای ضخیم خانه را از سرما عایق می‌کند."],["Feathers insulate birds against the cold.","پرها پرندگان را در برابر سرما عایق می‌کنند."],["The wires are insulated with plastic.","سیم‌ها با پلاستیک عایق بندی شده اند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:distinguish','distinguish','v','تمیز دادن، تشخیص دادن، متمایز کردن','to recognize the difference between things','Some animals cannot distinguish colors.','[["Some animals cannot distinguish colors.","برخی از حیوانات نمی‌توانند رنگ‌ها را تشخیص دهند."],["It is hard to distinguish the twins.","تشخیص دوقلوها سخت است."],["What distinguishes humans from other animals?","چه چیزی انسان را از سایر حیوانات متمایز می‌کند؟"]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cellular','cellular','adj','سلولی','relating to the cells of plants or animals','The disease affects cellular growth.','[["The disease affects cellular growth.","این بیماری بر رشد سلولی تأثیر می‌گذارد."],["Scientists study cellular processes in the lab.","دانشمندان فرآیندهای سلولی را در آزمایشگاه مطالعه می‌کنند."],["Cellular damage increases with age.","آسیب سلولی با افزایش سن افزایش می‌یابد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:volatile','volatile','adj','بی‌ثبات، متغیر؛ فرّار (مایع)','likely to change suddenly; (of a liquid) changing easily into gas','The stock market is very volatile.','[["The stock market is very volatile.","بازار سهام بسیار نوسان است."],["The political situation is volatile.","اوضاع سیاسی متزلزل است."],["Petrol is a volatile liquid.","بنزین یک مایع فرار است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:buoyant','buoyant','adj','شناور؛ رو به رشد؛ سرزنده','able to float; (of an economy) successful; cheerful','Salt water makes swimmers more buoyant.','[["Salt water makes swimmers more buoyant.","آب نمک شناگران را شناورتر می‌کند."],["The economy remains buoyant.","اقتصاد سرزنده باقی می‌ماند."],["She was in a buoyant mood.","او در خلق و خوی سرزنده بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:mitigate','mitigate','v','کاهش دادن، تسکین دادن','to make something less harmful or serious','Planting trees can mitigate the effects of pollution.','[["Planting trees can mitigate the effects of pollution.","کاشت درخت می‌تواند اثرات آلودگی را کاهش دهد."],["Measures were taken to mitigate flood damage.","اقدامات لازم برای کاهش خسارات سیل انجام شد."],["Nothing could mitigate the impact of the drought.","هیچ چیز نمی‌تواند تاثیر خشکسالی را کاهش دهد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:moisture','moisture','n','رطوبت','a small amount of water in the air or on a surface','The soil retains moisture well.','[["The soil retains moisture well.","خاک به خوبی رطوبت را حفظ می‌کند."],["Plants absorb moisture through their roots.","گیاهان از طریق ریشه خود رطوبت را جذب می‌کنند."],["Moisture in the air causes metal to rust.","رطوبت موجود در هوا باعث زنگ زدگی فلز می‌شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:procure','procure','v','تهیه کردن، به دست آوردن (با زحمت)','to obtain something, especially with effort','The museum procured rare manuscripts.','[["The museum procured rare manuscripts.","این موزه دست نوشته‌های کمیاب را تهیه کرد."],["It was difficult to procure food during the war.","تهیه غذا در طول جنگ دشوار بود."],["The army procured new equipment.","ارتش تجهیزات جدیدی تهیه کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:axe','axe','n','تبر','a tool with a heavy metal blade on a long handle, used for cutting wood','He chopped the wood with an axe.','[["He chopped the wood with an axe.","چوب را با تبر خرد کرد."],["Stone axes were used by early humans.","تبرهای سنگی توسط انسان‌های اولیه استفاده می‌شد."],["The axe was found in an ancient grave.","تبر در یک گور باستانی پیدا شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:thermal','thermal','adj','حرارتی، گرمایی','relating to heat','Thermal energy can be used to heat homes.','[["Thermal energy can be used to heat homes.","از انرژی حرارتی می‌توان برای گرم کردن خانه‌ها استفاده کرد."],["The town is famous for its thermal springs.","این شهر به خاطر چشمه‌های آب گرمش معروف است."],["Thermal cameras detect body heat.","دوربین‌های حرارتی گرمای بدن را تشخیص می‌دهند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:commodity','commodity','n','کالا، متاع','a product that can be bought and sold, especially raw materials','Oil is the country''s most important commodity.','[["Oil is the country''s most important commodity.","نفت مهمترین کالای کشور است."],["Coffee is a valuable commodity.","قهوه یک کالای ارزشمند است."],["Water is becoming a precious commodity.","آب در حال تبدیل شدن به یک کالای گرانبها است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:substitute','substitute','n','جایگزین، جانشین','a person or thing that takes the place of another','Honey can be used as a substitute for sugar.','[["Honey can be used as a substitute for sugar.","می‌توان از عسل به عنوان جایگزین شکر استفاده کرد."],["There is no substitute for hard work.","هیچ جایگزینی برای کار سخت وجود ندارد."],["The coach sent on a substitute.","مربی یک بازیکن تعویضی به زمین فرستاد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:scheme','scheme','n','طرح، برنامه؛ نقشه (گاهی فریبکارانه)','an official plan or system; a clever plan','The government introduced a recycling scheme.','[["The government introduced a recycling scheme.","دولت طرح بازیافت را معرفی کرد."],["A new pension scheme was launched.","طرح بازنشستگی جدید راه اندازی شد."],["The scheme to cheat investors failed.","طرح فریب سرمایه گذاران شکست خورد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:promising','promising','adj','امیدوارکننده، نویدبخش','showing signs of future success','The results are very promising.','[["The results are very promising.","نتایج بسیار امیدوار کننده است."],["She is a promising young scientist.","او یک دانشمند جوان آینده دار است."],["The new drug looks promising.","داروی جدید امیدوارکننده به نظر می‌رسد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:adopt','adopt','v','پذیرفتن، اتخاذ کردن (روش/طرح)؛ به فرزندی گرفتن','to start to use a method or plan; to take a child into your family','Many farmers have adopted modern methods.','[["Many farmers have adopted modern methods.","بسیاری از کشاورزان روش‌های مدرن را اتخاذ کرده اند."],["The country adopted a new constitution.","این کشور قانون اساسی جدیدی را تصویب کرد."],["They adopted a baby girl.","آنها یک دختر را به فرزندی قبول کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:concrete','concrete','n','بتن','a hard building material made from cement, sand, stones and water','The bridge is made of concrete.','[["The bridge is made of concrete.","پل از بتن ساخته شده است."],["Romans used a type of concrete in their buildings.","رومی‌ها از نوعی بتن در ساختمان‌های خود استفاده می‌کردند."],["Concrete production releases a lot of carbon dioxide.","تولید بتن مقدار زیادی دی اکسید کربن آزاد می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:amass','amass','v','انباشتن، جمع‌آوری کردن (مقدار زیاد)','to collect a large amount of something over time','He amassed a fortune in business.','[["He amassed a fortune in business.","او در تجارت ثروت اندوزی کرد."],["Researchers have amassed a large amount of data.","محققان حجم زیادی از داده‌ها را جمع آوری کرده اند."],["The museum amassed a huge collection of coins.","این موزه مجموعه عظیمی از سکه‌ها را جمع آوری کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:triumph','triumph','n','پیروزی، موفقیت بزرگ','a great victory or success','The discovery was a triumph of modern science.','[["The discovery was a triumph of modern science.","این کشف یک پیروزی علم مدرن بود."],["The team celebrated their triumph.","این تیم قهرمانی خود را جشن گرفت."],["The opening of the bridge was a triumph of engineering.","افتتاح پل یک پیروزی مهندسی بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:companion','companion','n','همراه، همدم','a person or animal you spend time or travel with','The dog was his constant companion.','[["The dog was his constant companion.","سگ همراه همیشگی او بود."],["She was a good companion on the long journey.","او در سفر طولانی همراه خوبی بود."],["Older people often keep pets as companions.","افراد مسن اغلب از حیوانات خانگی به عنوان همراه نگهداری می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inferior','inferior','adj','پایین‌تر، بی‌کیفیت‌تر، درجه دو','not as good as something else','These products are inferior to the originals.','[["These products are inferior to the originals.","این محصولات نسبت به اصل پایین‌تر هستند."],["Cheap materials are often inferior in quality.","مواد ارزان قیمت اغلب از نظر کیفیت پایین‌تر هستند."],["He never made others feel inferior.","او هرگز به دیگران احساس حقارت نمی‌داد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:vivid','vivid','adj','زنده، واضح، روشن','producing very clear pictures in the mind; very bright','She has vivid memories of her childhood.','[["She has vivid memories of her childhood.","او خاطرات روشنی از دوران کودکی خود دارد."],["The writer gives a vivid description of the city.","نویسنده توصیف واضحی از شهر ارائه می‌دهد."],["The flowers were painted in vivid colors.","گل‌ها با رنگ‌های زنده رنگ آمیزی شده بودند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:specifications','specifications','n','مشخصات (فنی)','detailed descriptions of how something should be made or what it can do','The building was built to the client''s specifications.','[["The building was built to the client''s specifications.","این ساختمان مطابق با مشخصات مشتری ساخته شده است."],["Check the technical specifications before you buy.","قبل از خرید مشخصات فنی را بررسی کنید."],["The car meets all safety specifications.","این خودرو تمام مشخصات ایمنی را دارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:pursuit','pursuit','n','دنبال کردن، جست‌وجو، پیگیری','the act of trying to achieve something; the act of chasing','The pursuit of happiness is a basic human goal.','[["The pursuit of happiness is a basic human goal.","جستجوی خوشبختی یک هدف اساسی انسان است."],["Scientists in pursuit of knowledge.","دانشمندان در جستجوی دانش"],["The police were in pursuit of the thief.","پلیس در تعقیب سارق بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inspire','inspire','v','الهام بخشیدن، الهام‌بخش بودن','to make someone want to do or create something','The landscape inspired many poets.','[["The landscape inspired many poets.","منظره الهام بخش بسیاری از شاعران بود."],["Her success inspired other women.","موفقیت او الهام بخش زنان دیگر بود."],["The building was inspired by Persian gardens.","این بنا از باغ‌های ایرانی الهام گرفته شده است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:desperate','desperate','adj','ناامید، درمانده؛ به‌شدت نیازمند','having little hope; needing something very much','The refugees were desperate for food.','[["The refugees were desperate for food.","پناهجویان به دنبال غذا بودند."],["After days without water, they became desperate.","بعد از روزها بدون آب، مستأصل شدند."],["There is a desperate need for doctors.","نیاز مبرم به پزشک وجود دارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:conscious','conscious','adj','آگاه، هشیار','aware of something; awake','She was conscious of being watched.','[["She was conscious of being watched.","او حواسش بود که تحت نظر باشد."],["People are becoming more conscious of their health.","مردم بیشتر از سلامتی خود آگاه می‌شوند."],["The patient was conscious after the operation.","بیمار بعد از عمل هوشیار بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:emperor','emperor','n','امپراتور','the ruler of an empire','Cyrus was a famous Persian emperor.','[["Cyrus was a famous Persian emperor.","کوروش شاهنشاه معروف ایرانی بود."],["The emperor ordered a new palace to be built.","امپراتور دستور داد تا قصر جدیدی بسازند."],["Roman emperors had great power.","امپراتوران روم قدرت زیادی داشتند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:convey','convey','v','منتقل کردن (مفهوم، احساس)؛ حمل کردن','to communicate an idea or feeling; to carry something','Music can convey strong emotions.','[["Music can convey strong emotions.","موسیقی می‌تواند احساسات قوی را منتقل کند."],["Pipes convey water to the city.","لوله‌ها آب را به شهر می‌رساند."],["It is hard to convey the meaning in another language.","به سختی می‌توان معنی را به زبان دیگری منتقل کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:engrossing','engrossing','adj','بسیار جذاب، مجذوب‌کننده','so interesting that it takes all your attention','The novel is engrossing.','[["The novel is engrossing.","رمان جذاب است."],["We watched an engrossing documentary about whales.","ما یک مستند جذاب در مورد نهنگ‌ها تماشا کردیم."],["The game was so engrossing that I forgot the time.","بازی آنقدر جذاب بود که زمان را فراموش کردم."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:extent','extent','n','میزان، حد، وسعت','the size, degree or importance of something','The extent of the damage was not clear.','[["The extent of the damage was not clear.","میزان خسارت مشخص نبود."],["To what extent do you agree?","تا چه حد موافقید؟"],["Scientists measured the extent of the ice.","دانشمندان وسعت یخ را اندازه گیری کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:globe','globe','n','کره زمین؛ کره جغرافیایی','the world; a round model of the Earth','Tourists come from all over the globe.','[["Tourists come from all over the globe.","گردشگران از سراسر جهان می‌آیند."],["He pointed to Iran on the globe.","او به ایران در کره زمین اشاره کرد."],["Climate change affects every part of the globe.","تغییرات آب و هوایی بر هر قسمت از کره زمین تأثیر می‌گذارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:civilization','civilization','n','تمدن','a developed society with its own culture and way of life','Ancient Egyptian civilization lasted thousands of years.','[["Ancient Egyptian civilization lasted thousands of years.","تمدن مصر باستان هزاران سال به طول انجامید."],["The Persian civilization made great contributions to science.","تمدن ایران کمک‌های زیادی به علم کرد."],["Writing is a sign of civilization.","نوشتن نشانه تمدن است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:founder','founder','n','بنیان‌گذار، مؤسس','a person who starts an organization or institution','He was the founder of the university.','[["He was the founder of the university.","او مؤسس دانشگاه بود."],["The company''s founder retired last year.","موسس این شرکت سال گذشته بازنشسته شد."],["The founders of the city came from the north.","بنیانگذاران شهر از شمال آمده اند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:bilingual','bilingual','adj','دوزبانه','able to speak two languages equally well; written in two languages','Many children in Canada are bilingual.','[["Many children in Canada are bilingual.","بسیاری از کودکان در کانادا دو زبانه هستند."],["The book has a bilingual dictionary at the back.","کتاب دارای فرهنگ لغت دو زبانه در پشت است."],["Bilingual people may have cognitive advantages.","افراد دو زبانه ممکن است از مزایای شناختی برخوردار باشند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prospective','prospective','adj','آینده، بالقوه، احتمالی','expected or likely to happen or become something','Prospective students can visit the campus.','[["Prospective students can visit the campus.","دانشجویان آینده نگر می‌توانند از پردیس بازدید کنند."],["The prospective buyers looked at the house.","خریداران احتمالی به خانه نگاه کردند."],["We discussed the prospective changes.","ما در مورد تغییرات آینده صحبت کردیم."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cognitive','cognitive','adj','شناختی، مربوط به ادراک و یادگیری','relating to thinking, learning and understanding','Sleep improves cognitive performance.','[["Sleep improves cognitive performance.","خواب عملکرد شناختی را بهبود می‌بخشد."],["Cognitive skills develop rapidly in children.","مهارت‌های شناختی در کودکان به سرعت رشد می‌کند."],["The disease causes cognitive decline.","این بیماری باعث زوال شناختی می‌شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deliberately','deliberately','adv','عمداً، آگاهانه','on purpose','The fire was started deliberately.','[["The fire was started deliberately.","آتش سوزی عمدی آغاز شد."],["He deliberately ignored the warning.","او عمداً به این هشدار توجهی نکرد."],["The design was deliberately simple.","طراحی عمدا ساده بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:compelling','compelling','adj','قانع‌کننده، قوی؛ گیرا','very convincing; so interesting that you pay attention','There is compelling evidence that smoking causes cancer.','[["There is compelling evidence that smoking causes cancer.","شواهد قانع کننده ای وجود دارد که نشان می‌دهد سیگار باعث سرطان می‌شود."],["She made a compelling argument.","او استدلال قانع کننده ای آورد."],["The film tells a compelling story.","این فیلم داستانی جذاب را روایت می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ethical','ethical','adj','اخلاقی','relating to beliefs about what is morally right and wrong','Animal testing raises ethical questions.','[["Animal testing raises ethical questions.","آزمایش بر روی حیوانات سوالات اخلاقی را مطرح می‌کند."],["The company follows strict ethical standards.","این شرکت از استانداردهای اخلاقی سختگیرانه پیروی می‌کند."],["Is it ethical to clone animals?","آیا شبیه سازی حیوانات اخلاقی است؟"]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:persistent','persistent','adj','مداوم، پیگیر، سرسخت','continuing for a long time; refusing to give up','He has a persistent cough.','[["He has a persistent cough.","سرفه مداوم دارد."],["Persistent rain caused flooding.","بارش مداوم باران باعث جاری شدن سیل شد."],["Persistent efforts eventually brought success.","تلاش‌های مداوم در نهایت موفقیت را به همراه داشت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:assume','assume','v','فرض کردن؛ بر عهده گرفتن','to think something is true without proof; to take on a role','We assume that the results are accurate.','[["We assume that the results are accurate.","ما فرض می‌کنیم که نتایج دقیق هستند."],["Don''t assume everyone agrees with you.","تصور نکنید که همه با شما موافق هستند."],["She assumed responsibility for the project.","او مسئولیت پروژه را بر عهده گرفت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:excel','excel','v','عالی بودن، برتری داشتن، متبحر بودن','to be extremely good at something','She excels at mathematics.','[["She excels at mathematics.","او در ریاضیات عالی است."],["The school excels in science education.","مدرسه در آموزش علوم سرآمد است."],["He excelled as a writer.","او به عنوان یک نویسنده سرآمد بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:irrelevant','irrelevant','adj','نامربوط، بی‌ربط','not connected with the subject','His age is irrelevant to the job.','[["His age is irrelevant to the job.","سن او به شغل ربطی ندارد."],["Remove irrelevant information from your answer.","اطلاعات نامربوط را از پاسخ خود حذف کنید."],["Such details are irrelevant to the question.","چنین جزئیاتی به سؤال بی ربط است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intervene','intervene','v','مداخله کردن، دخالت کردن','to become involved in a situation to change or stop it','The government intervened to stop prices rising.','[["The government intervened to stop prices rising.","دولت برای جلوگیری از افزایش قیمت‌ها مداخله کرد."],["The teacher intervened in the fight.","معلم در دعوا دخالت کرد."],["Doctors had to intervene quickly.","پزشکان مجبور شدند به سرعت مداخله کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prosecute','prosecute','v','تحت پیگرد قانونی قرار دادن، محاکمه کردن','to officially accuse someone of a crime in court','Shoplifters will be prosecuted.','[["Shoplifters will be prosecuted.","سارقان مغازه تحت پیگرد قانونی قرار خواهند گرفت."],["He was prosecuted for fraud.","او به اتهام کلاهبرداری تحت تعقیب قرار گرفت."],["The company was prosecuted for polluting the river.","این شرکت به دلیل آلودگی رودخانه تحت پیگرد قانونی قرار گرفت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:welfare','welfare','n','رفاه، آسایش؛ تأمین اجتماعی','the health, happiness and safety of a person or group; government help for people in need','The organization works for animal welfare.','[["The organization works for animal welfare.","این سازمان برای رفاه حیوانات کار می‌کند."],["Parents are concerned about their children''s welfare.","والدین نگران رفاه فرزندان خود هستند."],["The country spends a lot on social welfare.","این کشور برای رفاه اجتماعی هزینه‌های زیادی می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:perception','perception','n','ادراک، برداشت، درک','the way you notice or understand something; an opinion','Our perception of color depends on light.','[["Our perception of color depends on light.","درک ما از رنگ به نور بستگی دارد."],["Public perception of the company has improved.","درک عمومی از شرکت بهبود یافته است."],["Age affects perception of time.","سن بر درک زمان تأثیر می‌گذارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:reckless','reckless','adj','بی‌احتیاط، بی‌پروا','not caring about danger or the results of your actions','Reckless driving causes many accidents.','[["Reckless driving causes many accidents.","رانندگی بی احتیاطی باعث تصادفات زیادی می‌شود."],["It was reckless to climb without a rope.","صعود بدون طناب بی پروا بود."],["He was fined for reckless behavior.","او به دلیل رفتار بی پروا جریمه شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:counterpart','counterpart','n','همتا، همانند','a person or thing with the same position or function in a different place','The minister met his French counterpart.','[["The minister met his French counterpart.","وزیر امور خارجه با همتای فرانسوی خود دیدار کرد."],["Female birds are less colorful than their male counterparts.","پرندگان ماده نسبت به پرندگان نر رنگی کمتری دارند."],["Urban schools have more funding than their rural counterparts.","مدارس شهری نسبت به مدارس روستایی خود بودجه بیشتری دارند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:uneven','uneven','adj','ناهموار؛ نابرابر','not flat or smooth; not equal or regular','The road surface was uneven.','[["The road surface was uneven.","سطح جاده ناهموار بود."],["Economic growth has been uneven across regions.","رشد اقتصادی در بین مناطق نابرابر بوده است."],["The quality of the work was uneven.","کیفیت کار نابرابر بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:erupt','erupt','v','فوران کردن؛ ناگهان آغاز شدن','(of a volcano) to throw out lava; to start suddenly','The volcano erupted in 1980.','[["The volcano erupted in 1980.","این آتشفشان در سال 1980 فوران کرد."],["Violence erupted in the city.","خشونت در شهر رخ داد."],["Mount Vesuvius erupted and buried Pompeii.","کوه وزوویوس فوران کرد و پمپئی را مدفون کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:molten','molten','adj','مذاب','turned into liquid by very great heat','Molten rock flowed from the volcano.','[["Molten rock flowed from the volcano.","سنگ مذاب از آتشفشان جاری شد."],["The Earth''s outer core is molten.","هسته بیرونی زمین مذاب است."],["Molten glass is shaped by blowing.","شیشه مذاب با دمیدن شکل می‌گیرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hospitable','hospitable','adj','مهمان‌نواز؛ مساعد (برای زندگی)','friendly and welcoming to guests; (of a place) pleasant to live in','Iranians are known for being hospitable.','[["Iranians are known for being hospitable.","ایرانی‌ها به مهمان نواز بودن شهرت دارند."],["The local people were very hospitable.","مردم محلی بسیار مهمان نواز بودند."],["Mars is not a hospitable environment for life.","مریخ محیطی مهمان نواز برای زندگی نیست."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:milestone','milestone','n','نقطه عطف، رویداد مهم','a very important event in the development of something','The moon landing was a milestone in history.','[["The moon landing was a milestone in history.","فرود ماه نقطه عطفی در تاریخ بود."],["Learning to walk is a milestone for a baby.","یادگیری راه رفتن یک نقطه عطف برای نوزاد است."],["The company reached a major milestone this year.","این شرکت در سال جاری به یک نقطه عطف بزرگ رسید."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:predator','predator','n','شکارچی، درنده','an animal that kills and eats other animals','Lions are predators.','[["Lions are predators.","شیرها شکارچی هستند."],["Small fish hide from predators among rocks.","ماهی‌های کوچک از شکارچیان در میان صخره‌ها پنهان می‌شوند."],["The island has no natural predators.","این جزیره هیچ شکارچی طبیعی ندارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:repeal','repeal','v','لغو کردن (قانون)','to officially end a law','The law was repealed in 1990.','[["The law was repealed in 1990.","این قانون در سال 1990 لغو شد."],["Campaigners want to repeal the tax.","کمپین‌ها می‌خواهند مالیات را لغو کنند."],["Parliament voted to repeal the ban.","پارلمان به لغو این ممنوعیت رأی داد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:exploit','exploit','v','بهره‌برداری کردن؛ استثمار کردن','to use something fully for profit; to use someone unfairly','The country exploits its oil reserves.','[["The country exploits its oil reserves.","این کشور از ذخایر نفت خود بهره برداری می‌کند."],["Workers were exploited by the factory owners.","کارگران توسط کارخانه داران مورد استثمار قرار گرفتند."],["Some plants exploit other plants for nutrients.","برخی از گیاهان از گیاهان دیگر برای مواد مغذی بهره برداری می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:craft','craft','n','صنعت دستی، حرفه، مهارت','an activity involving skill in making things by hand','Carpet weaving is a traditional Persian craft.','[["Carpet weaving is a traditional Persian craft.","قالی بافی از صنایع سنتی ایرانی است."],["He learned the craft of pottery from his father.","صنعت سفالگری را نزد پدرش آموخت."],["Local crafts are sold in the market.","صنایع دستی محلی در بازار فروخته می‌شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:trail','trail','n','ردپا، مسیر (پیاده‌روی)','a path through the countryside; marks left by someone or something','We followed a trail through the forest.','[["We followed a trail through the forest.","مسیری را در میان جنگل دنبال کردیم."],["The animal left a trail of footprints.","حیوان رد پایی از خود به جا گذاشت."],["The hiking trail is ten kilometres long.","مسیر پیاده روی ده کیلومتر طول دارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:landfill','landfill','n','محل دفن زباله','a place where waste is buried under the ground','Most plastic waste ends up in landfill.','[["Most plastic waste ends up in landfill.","بیشتر زباله‌های پلاستیکی به محل دفن زباله‌ها ختم می‌شوند."],["The city plans to close the old landfill.","شهر قصد دارد محل دفن زباله قدیمی را ببندد."],["Recycling reduces the amount of waste sent to landfill.","بازیافت مقدار زباله ارسالی به محل دفن زباله را کاهش می‌دهد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unprecedented','unprecedented','adj','بی‌سابقه','never having happened before','The city saw unprecedented growth.','[["The city saw unprecedented growth.","شهر شاهد رشد بی سابقه ای بود."],["The drought was unprecedented in its severity.","خشکسالی از نظر شدت بی سابقه بود."],["Scientists recorded unprecedented temperatures.","دانشمندان دمای بی سابقه ای را ثبت کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fierce','fierce','adj','شدید؛ وحشی، درنده','very strong or violent; aggressive','There is fierce competition for jobs.','[["There is fierce competition for jobs.","رقابت شدیدی برای مشاغل وجود دارد."],["Fierce winds damaged many buildings.","وزش باد شدید به بسیاری از ساختمان‌ها آسیب رساند."],["Tigers are fierce animals.","ببرها حیوانات خشن هستند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:territory','territory','n','قلمرو، سرزمین؛ حیطه','land controlled by a country or animal; an area of knowledge','Wolves mark their territory.','[["Wolves mark their territory.","گرگ‌ها قلمرو خود را علامت گذاری می‌کنند."],["The island is French territory.","این جزیره در قلمرو فرانسه است."],["This topic is new territory for scientists.","این موضوع قلمرو جدیدی برای دانشمندان است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:invaluable','invaluable','adj','بسیار ارزشمند، گران‌بها','extremely useful','Her advice was invaluable.','[["Her advice was invaluable.","توصیه او بسیار ارزشمند بود."],["The internet is an invaluable source of information.","اینترنت منبع ارزشمندی از اطلاعات است."],["Volunteers provided invaluable help.","داوطلبان کمک‌های ارزشمندی ارائه کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:breed','breed','v','تولید مثل کردن؛ پرورش دادن','(of animals) to produce young; to keep animals to produce young','Many birds breed in spring.','[["Many birds breed in spring.","بسیاری از پرندگان در بهار تولید مثل می‌کنند."],["Pandas rarely breed in captivity.","پانداها به ندرت در اسارت تولید مثل می‌کنند."],["The farmers breed sheep for wool.","کشاورزان برای تولید پشم گوسفند پرورش می‌دهند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:advancement','advancement','n','پیشرفت، ترقی','progress or development','Technological advancement has changed our lives.','[["Technological advancement has changed our lives.","پیشرفت تکنولوژی زندگی ما را تغییر داده است."],["There are opportunities for career advancement.","فرصت‌هایی برای پیشرفت شغلی وجود دارد."],["The advancement of science depends on funding.","پیشرفت علم در گرو تامین مالی است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:intersection','intersection','n','تقاطع، چهارراه','a place where roads or lines cross','Turn left at the next intersection.','[["Turn left at the next intersection.","در تقاطع بعدی به چپ بپیچید."],["Accidents often happen at busy intersections.","تصادفات اغلب در تقاطع‌های شلوغ اتفاق می‌افتد."],["The study lies at the intersection of biology and chemistry.","این مطالعه در تقاطع زیست شناسی و شیمی قرار دارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:poem','poem','n','شعر','a piece of writing arranged in lines, often with rhythm and rhyme','Hafez wrote many beautiful poems.','[["Hafez wrote many beautiful poems.","حافظ شعرهای بسیار زیبایی سروده است."],["She read a poem at the ceremony.","او در این مراسم شعری خواند."],["The poem describes the beauty of spring.","شعر زیبایی بهار را توصیف می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prevalent','prevalent','adj','رایج، شایع (به‌ویژه بیماری یا مشکل)','common or widespread at a particular time or place','Malaria is prevalent in tropical regions.','[["Malaria is prevalent in tropical regions.","مالاریا در مناطق گرمسیری شیوع دارد."],["These ideas were prevalent in the 19th century.","این عقاید در قرن نوزدهم رایج بود."],["Obesity is becoming more prevalent.","چاقی در حال شیوع بیشتر است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:presume','presume','v','فرض کردن، گمان کردن','to believe something is true without proof','I presume you have read the report.','[["I presume you have read the report.","من فکر می‌کنم شما گزارش را خوانده اید."],["The ship was presumed lost.","گمان می‌رفت کشتی گم شده است."],["We cannot presume that the results are correct.","ما نمی‌توانیم فرض کنیم که نتایج صحیح است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:damp','damp','adj','نمناک، مرطوب','slightly wet, often in an unpleasant way','The house was cold and damp.','[["The house was cold and damp.","خانه سرد و نمناک بود."],["Mushrooms grow in damp places.","قارچ‌ها در مکان‌های مرطوب رشد می‌کنند."],["Wipe the table with a damp cloth.","میز را با یک پارچه مرطوب پاک کنید."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:well-being','well-being','n','سلامت و رفاه، بهزیستی','the state of being healthy and happy','Exercise is important for mental well-being.','[["Exercise is important for mental well-being.","ورزش برای سلامت روان مهم است."],["The company cares about the well-being of its staff.","این شرکت به سلامت کارکنان خود اهمیت می‌دهد."],["Green spaces improve people''s well-being.","فضاهای سبز رفاه مردم را بهبود می‌بخشد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:roughly','roughly','adv','تقریباً، حدوداً','approximately; not exactly','Roughly half of the students passed.','[["Roughly half of the students passed.","تقریباً نیمی از دانش آموزان قبول شدند."],["The journey takes roughly two hours.","سفر تقریباً دو ساعت طول می‌کشد."],["The two cities are roughly the same size.","اندازه دو شهر تقریباً یکسان است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:respiratory','respiratory','adj','تنفسی','relating to breathing','Air pollution causes respiratory diseases.','[["Air pollution causes respiratory diseases.","آلودگی هوا باعث بیماری‌های تنفسی می‌شود."],["The virus affects the respiratory system.","این ویروس بر سیستم تنفسی تأثیر می‌گذارد."],["Smoking increases the risk of respiratory problems.","سیگار خطر مشکلات تنفسی را افزایش می‌دهد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:restore','restore','v','بازگرداندن، ترمیم کردن، مرمت کردن','to return something to its earlier good condition','The palace was restored to its original beauty.','[["The palace was restored to its original beauty.","این کاخ به زیبایی اولیه خود بازسازی شد."],["The government restored order in the city.","دولت نظم را به شهر بازگرداند."],["Wetlands were restored to help wildlife.","تالاب‌ها برای کمک به حیات وحش بازسازی شدند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:polio','polio','n','فلج اطفال','a serious infectious disease that can cause paralysis','Polio has almost been eradicated worldwide.','[["Polio has almost been eradicated worldwide.","فلج اطفال تقریباً در سراسر جهان ریشه کن شده است."],["Children are vaccinated against polio.","کودکان در برابر فلج اطفال واکسینه می‌شوند."],["Polio was once a common disease.","فلج اطفال زمانی یک بیماری شایع بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:arbitrary','arbitrary','adj','دلبخواهی، خودسرانه','based on chance or personal choice rather than reason','The choice of colors was arbitrary.','[["The choice of colors was arbitrary.","انتخاب رنگ دلخواه بود."],["Citizens were protected from arbitrary arrest.","شهروندان از دستگیری خودسرانه محافظت شدند."],["The border was drawn in an arbitrary way.","مرز به صورت دلخواه ترسیم شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:discrepancy','discrepancy','n','اختلاف، ناهمخوانی','a difference between things that should be the same','There is a discrepancy between the two reports.','[["There is a discrepancy between the two reports.","بین این دو گزارش تناقض وجود دارد."],["Scientists noticed a discrepancy in the data.","دانشمندان متوجه اختلاف در داده‌ها شدند."],["The discrepancy in prices is hard to explain.","توضیح اختلاف قیمت‌ها سخت است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:articulate','articulate','v','به‌روشنی بیان کردن','to express ideas or feelings clearly in words','She articulated her ideas clearly.','[["She articulated her ideas clearly.","او ایده‌های خود را به وضوح بیان کرد."],["Young children cannot always articulate their feelings.","کودکان خردسال همیشه نمی‌توانند احساسات خود را بیان کنند."],["The report articulates the need for change.","این گزارش نیاز به تغییر را بیان می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:overlook','overlook','v','نادیده گرفتن؛ مشرف بودن به','to fail to notice; to have a view over a place','The importance of sleep is often overlooked.','[["The importance of sleep is often overlooked.","اهمیت خواب اغلب نادیده گرفته می‌شود."],["The hotel overlooks the sea.","هتل مشرف به دریا است."],["We overlooked a small error in the data.","ما یک خطای کوچک در داده‌ها را نادیده گرفتیم."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prey','prey','n','طعمه، شکار','an animal that is hunted and eaten by another animal','The eagle saw its prey from the sky.','[["The eagle saw its prey from the sky.","عقاب طعمه خود را از آسمان دید."],["Mice are prey for owls.","موش‌ها طعمه جغدها هستند."],["Lions hunt their prey in groups.","شیرها به صورت گروهی طعمه خود را شکار می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:devoid of','devoid of','adj','عاری از، خالی از','completely without something','The desert is almost devoid of life.','[["The desert is almost devoid of life.","کویر تقریباً خالی از حیات است."],["His voice was devoid of emotion.","صدایش خالی از احساس بود."],["The room was devoid of furniture.","اتاق خالی از مبلمان بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inquiry','inquiry','n','تحقیق، تحقیقات؛ پرسش','an official investigation; a question','The government ordered an inquiry into the accident.','[["The government ordered an inquiry into the accident.","دولت دستور رسیدگی به این حادثه را صادر کرد."],["We received many inquiries about the course.","ما سوالات زیادی در مورد دوره دریافت کردیم."],["A scientific inquiry begins with a question.","یک تحقیق علمی با یک سوال شروع می‌شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:explicit','explicit','adj','صریح، روشن','clear and exact, with nothing hidden','The instructions were explicit.','[["The instructions were explicit.","دستورالعمل‌ها صریح بود."],["He made an explicit promise.","قول صریح داد."],["The law is explicit about safety standards.","قانون در مورد استانداردهای ایمنی صریح است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:agenda','agenda','n','دستور جلسه، برنامه کار','a list of things to discuss at a meeting; a plan of things to be done','Climate change is high on the agenda.','[["Climate change is high on the agenda.","تغییرات اقلیمی در دستور کار قرار دارد."],["What''s on the agenda for today''s meeting?","دستور جلسه امروز چیست؟"],["The government has a busy agenda.","دولت دستور کار شلوغی دارد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:anticipate','anticipate','v','پیش‌بینی کردن، انتظار داشتن','to expect something and prepare for it','We anticipate a rise in prices.','[["We anticipate a rise in prices.","افزایش قیمت‌ها را پیش بینی می‌کنیم."],["Scientists anticipated the eruption.","دانشمندان فوران را پیش بینی کردند."],["Good drivers anticipate dangers.","رانندگان خوب خطرات را پیش بینی می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:surge','surge','n','افزایش ناگهانی و شدید، موج','a sudden large increase','There was a surge in demand for bicycles.','[["There was a surge in demand for bicycles.","افزایش تقاضا برای دوچرخه وجود داشت."],["A surge of water flooded the streets.","موجی از آب در خیابان‌ها جاری شد."],["The city saw a surge in tourism.","این شهر شاهد جهش گردشگری بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ensure','ensure','v','اطمینان حاصل کردن، تضمین کردن','to make certain that something happens','Please ensure that all windows are closed.','[["Please ensure that all windows are closed.","لطفا مطمئن شوید که همه پنجره‌ها بسته هستند."],["The law ensures equal rights for all.","قانون حقوق برابر را برای همه تضمین می‌کند."],["Regular checks ensure the water is safe.","بررسی‌های منظم از سالم بودن آب اطمینان حاصل می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:dissect','dissect','v','کالبدشکافی کردن؛ موشکافانه تحلیل کردن','to cut open a dead body to study it; to examine something in detail','Students dissected a frog in biology class.','[["Students dissected a frog in biology class.","دانش آموزان یک قورباغه را در کلاس زیست شناسی تشریح کردند."],["The article dissects the causes of the crisis.","این مقاله به تشریح علل بحران می‌پردازد."],["Scientists dissected the insect under a microscope.","دانشمندان این حشره را زیر میکروسکوپ تشریح کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:comprehend','comprehend','v','درک کردن، فهمیدن','to understand something fully','It is difficult to comprehend the size of the universe.','[["It is difficult to comprehend the size of the universe.","درک اندازه کیهان دشوار است."],["She could not comprehend why he left.","او نمی‌توانست بفهمد چرا او رفت."],["Children comprehend more than they can say.","کودکان بیش از آنچه که می‌توانند بگویند درک می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:arise','arise','v','به وجود آمدن، پیش آمدن، ناشی شدن','to begin to exist or happen','Problems may arise during the experiment.','[["Problems may arise during the experiment.","در طول آزمایش ممکن است مشکلاتی ایجاد شود."],["The disease arises from poor hygiene.","این بیماری از عدم رعایت بهداشت ناشی می‌شود."],["New opportunities arose after the war.","فرصت‌های جدیدی پس از جنگ به وجود آمد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:insatiable','insatiable','adj','سیری‌ناپذیر','always wanting more','Children have an insatiable curiosity.','[["Children have an insatiable curiosity.","کودکان کنجکاوی سیری ناپذیری دارند."],["The world has an insatiable demand for energy.","جهان تقاضای سیری ناپذیری برای انرژی دارد."],["He had an insatiable appetite for knowledge.","اشتهای سیری ناپذیری برای دانش داشت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:preserve','preserve','v','حفظ کردن، نگهداری کردن','to keep something in its original state or protect it from harm','The ancient city has been well preserved.','[["The ancient city has been well preserved.","شهر باستانی به خوبی حفظ شده است."],["Salt was used to preserve meat.","از نمک برای نگهداری گوشت استفاده می‌شد."],["We must preserve forests for future generations.","ما باید جنگل‌ها را برای نسل‌های آینده حفظ کنیم."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:shareholder','shareholder','n','سهام‌دار','a person who owns shares in a company','Shareholders voted for the new plan.','[["Shareholders voted for the new plan.","سهامداران به طرح جدید رای دادند."],["The company paid its shareholders a dividend.","این شرکت به سهامداران خود سود سهام پرداخت کرد."],["She is a major shareholder in the bank.","او سهامدار عمده بانک است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:struggle','struggle','v','تقلا کردن، مبارزه کردن، دست‌وپنجه نرم کردن','to try very hard to do something difficult','Many families struggle to pay their bills.','[["Many families struggle to pay their bills.","بسیاری از خانواده‌ها برای پرداخت قبوض خود با مشکل مواجه هستند."],["The animals struggled to survive the winter.","حیوانات برای زنده ماندن در زمستان تلاش کردند."],["He struggled with the heavy box.","او با جعبه سنگین مبارزه کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:debate','debate','n','بحث، مناظره','a discussion in which people express different opinions','There is a heated debate about nuclear power.','[["There is a heated debate about nuclear power.","بحث‌های داغی در مورد انرژی هسته ای وجود دارد."],["The debate lasted two hours.","این مناظره دو ساعت به طول انجامید."],["Scientists continue to debate the cause of the extinction.","دانشمندان همچنان در مورد علت انقراض بحث می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:be associated with','be associated with','phr','مرتبط بودن با، همراه بودن با','to be connected with something','Smoking is associated with lung cancer.','[["Smoking is associated with lung cancer.","سیگار با سرطان ریه مرتبط است."],["The color red is associated with danger.","رنگ قرمز با خطر همراه است."],["High salt intake is associated with heart disease.","مصرف زیاد نمک با بیماری قلبی مرتبط است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:export','export','v','صادر کردن','to sell and send goods to another country','Iran exports pistachios to many countries.','[["Iran exports pistachios to many countries.","ایران به بسیاری از کشورها پسته صادر می‌کند."],["The country exports oil and gas.","این کشور نفت و گاز صادر می‌کند."],["The company exports 70 percent of its products.","این شرکت 70 درصد محصولات خود را صادر می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cinnamon','cinnamon','n','دارچین','a sweet brown spice made from the bark of a tree','Add a little cinnamon to the rice pudding.','[["Add a little cinnamon to the rice pudding.","کمی دارچین به پودینگ برنج اضافه کنید."],["Cinnamon was once more valuable than gold.","دارچین زمانی ارزشمندتر از طلا بود."],["Traders brought cinnamon from Sri Lanka.","تاجران دارچین را از سریلانکا آوردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:exhilarating','exhilarating','adj','نشاط‌آور، هیجان‌انگیز','making you feel very happy and excited','Skiing down the mountain was exhilarating.','[["Skiing down the mountain was exhilarating.","اسکی کردن از کوه نشاط آور بود."],["The view from the top was exhilarating.","منظره از بالا هیجان انگیز بود."],["It was an exhilarating experience.","تجربه هیجان انگیزی بود"]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:scent','scent','n','رایحه، بو','a pleasant smell; the smell left by an animal','The scent of roses filled the garden.','[["The scent of roses filled the garden.","عطر گل رز باغ را پر کرده بود."],["Dogs follow the scent of animals.","سگ‌ها از بوی حیوانات پیروی می‌کنند."],["Flowers use their scent to attract insects.","گل‌ها از رایحه خود برای جذب حشرات استفاده می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:undergo','undergo','v','متحمل شدن، تحت (فرایندی) قرار گرفتن','to experience a process of change or something unpleasant','The city has undergone major changes.','[["The city has undergone major changes.","این شهر دستخوش تغییرات اساسی شده است."],["Patients undergo tests before surgery.","بیماران قبل از جراحی تحت آزمایش قرار می‌گیرند."],["The caterpillar undergoes a transformation.","کاترپیلار دچار دگرگونی می‌شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:stunning','stunning','adj','خیره‌کننده، بسیار زیبا','extremely beautiful or impressive','The beach has stunning views.','[["The beach has stunning views.","ساحل مناظر خیره کننده ای دارد."],["She looked stunning in her dress.","او در لباسش خیره کننده به نظر می‌رسید."],["The team achieved a stunning victory.","این تیم به یک پیروزی خیره کننده دست یافت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:flavor','flavor','n','طعم، مزه','the taste of food or drink','Saffron gives the rice a special flavor.','[["Saffron gives the rice a special flavor.","زعفران طعم خاصی به برنج می‌دهد."],["This ice cream comes in many flavors.","این بستنی طعم‌های مختلفی دارد."],["Herbs add flavor to the dish.","گیاهان به غذا طعم می‌بخشند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inclusion','inclusion','n','گنجاندن، شمول، دربرگیری','the act of including someone or something','The inclusion of new data changed the results.','[["The inclusion of new data changed the results.","گنجاندن داده‌های جدید نتایج را تغییر داد."],["Schools should promote the inclusion of all children.","مدارس باید مشارکت همه کودکان را ترویج کنند."],["Her inclusion in the team surprised everyone.","حضور او در تیم همه را شگفت زده کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:spur','spur','v','تحریک کردن، برانگیختن، باعث شدن','to encourage or cause something to happen faster','Low interest rates spurred economic growth.','[["Low interest rates spurred economic growth.","نرخ بهره پایین باعث رشد اقتصادی شد."],["The discovery spurred further research.","این کشف تحقیقات بیشتری را برانگیخت."],["Her success spurred others to try.","موفقیت او دیگران را به تلاش برانگیخت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:expenditure','expenditure','n','هزینه، مخارج','the amount of money spent','Government expenditure on health has increased.','[["Government expenditure on health has increased.","هزینه‌های دولت برای سلامت افزایش یافته است."],["The expenditure on the project was too high.","هزینه پروژه خیلی زیاد بود."],["We need to reduce our expenditure.","ما باید هزینه‌های خود را کاهش دهیم."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ethnic','ethnic','adj','قومی','relating to a group of people with the same culture or origin','The city has many ethnic groups.','[["The city has many ethnic groups.","این شهر دارای اقوام بسیاری است."],["Ethnic food is popular in big cities.","غذاهای قومی در شهرهای بزرگ رایج است."],["The country is known for its ethnic diversity.","این کشور به دلیل تنوع قومیتی خود شناخته شده است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:undertake','undertake','v','بر عهده گرفتن، اقدام به (کاری) کردن','to accept and begin a task','The university undertook a major research project.','[["The university undertook a major research project.","دانشگاه یک پروژه تحقیقاتی بزرگ را انجام داد."],["She undertook to finish the work by Friday.","او متعهد شد که کار را تا جمعه تمام کند."],["The study was undertaken in five countries.","این مطالعه در پنج کشور انجام شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ally','ally','v','متحد شدن، هم‌پیمان شدن','to join with others to support each other','The two countries allied against their enemy.','[["The two countries allied against their enemy.","دو کشور علیه دشمن خود متحد شدند."],["Small farmers allied with environmental groups.","کشاورزان کوچک با گروه‌های محیط زیست متحد شدند."],["He allied himself with the opposition.","او با مخالفان متحد شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:underlying','underlying','adj','اساسی، زیربنایی، پنهان','real but not obvious; basic','The underlying cause of the problem is poverty.','[["The underlying cause of the problem is poverty.","علت اصلی این مشکل فقر است."],["We need to understand the underlying principles.","ما باید اصول اساسی را درک کنیم."],["The patient had an underlying heart condition.","بیمار یک بیماری قلبی زمینه ای داشت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:lucrative','lucrative','adj','سودآور، پردرآمد','producing a lot of money','Tourism is a lucrative industry.','[["Tourism is a lucrative industry.","گردشگری یک صنعت پرسود است."],["He left for a more lucrative job.","او برای شغلی پردرآمدتر رفت."],["The company won a lucrative contract.","این شرکت برنده یک قرارداد سودآور شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:comprehensive','comprehensive','adj','جامع، کامل','including everything or almost everything','The book is a comprehensive guide to Iranian birds.','[["The book is a comprehensive guide to Iranian birds.","کتاب راهنمای جامع پرندگان ایرانی است."],["We need a comprehensive study of the problem.","ما نیاز به مطالعه جامع مشکل داریم."],["The report is comprehensive and detailed.","گزارش جامع و مفصل است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:thereby','thereby','adv','بدین‌وسیله، در نتیجه','as a result of this action','He stopped smoking, thereby improving his health.','[["He stopped smoking, thereby improving his health.","او سیگار را ترک کرد و در نتیجه سلامت خود را بهبود بخشید."],["Trees absorb carbon, thereby reducing pollution.","درختان کربن را جذب می‌کنند و در نتیجه آلودگی را کاهش می‌دهند."],["The city built new roads, thereby reducing traffic.","این شهر جاده‌های جدیدی ساخت و در نتیجه ترافیک را کاهش داد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:boredom','boredom','n','کسالت، ملال','the state of being bored','Many workers complain of boredom.','[["Many workers complain of boredom.","بسیاری از کارگران از کسالت شکایت دارند."],["Children often eat out of boredom.","بچه‌ها اغلب از روی بی حوصلگی غذا می‌خورند."],["He read books to avoid boredom.","کتاب می‌خواند تا خسته نشود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:gland','gland','n','غده','an organ in the body that produces chemical substances','Sweat glands help cool the body.','[["Sweat glands help cool the body.","غدد عرق به خنک شدن بدن کمک می‌کنند."],["The thyroid gland controls growth.","غده تیروئید رشد را کنترل می‌کند."],["Some snakes have poison glands.","برخی از مارها غدد سمی دارند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:attuned','attuned','adj','هماهنگ، آشنا، حساس (به چیزی)','able to understand or recognize something; used to','Mothers are attuned to their babies'' needs.','[["Mothers are attuned to their babies'' needs.","مادران با نیازهای نوزاد خود هماهنگ هستند."],["Animals are attuned to changes in the weather.","حیوانات با تغییرات آب و هوا هماهنگ هستند."],["She is attuned to the needs of her students.","او با نیازهای شاگردانش هماهنگ است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prone','prone','adj','مستعد، در معرض (prone to)','likely to suffer from or do something','The area is prone to earthquakes.','[["The area is prone to earthquakes.","این منطقه مستعد زلزله است."],["Older people are more prone to falls.","افراد مسن بیشتر مستعد زمین خوردن هستند."],["He is prone to making careless mistakes.","او مستعد اشتباهات بی دقت است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:indifferent','indifferent','adj','بی‌تفاوت، بی‌اعتنا','not interested in or caring about something','He was indifferent to the needs of others.','[["He was indifferent to the needs of others.","نسبت به نیازهای دیگران بی تفاوت بود."],["Many young people are indifferent to politics.","بسیاری از جوانان نسبت به سیاست بی تفاوت هستند."],["The food was indifferent, but the service was good.","غذا بی تفاوت بود ولی سرویس دهی خوب بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:irritate','irritate','v','آزردن، عصبانی کردن؛ تحریک کردن (پوست)','to make someone annoyed; to make a part of the body sore','His constant talking irritated me.','[["His constant talking irritated me.","صحبت‌های مداوم او مرا عصبانی می‌کرد."],["Some soaps irritate the skin.","برخی از صابون‌ها پوست را تحریک می‌کنند."],["Smoke irritates the eyes.","دود چشم را تحریک می‌کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:charitable','charitable','adj','خیریه‌ای، خیرخواهانه','relating to helping people in need; kind','She works for a charitable organization.','[["She works for a charitable organization.","او برای یک موسسه خیریه کار می‌کند."],["The money was given for charitable purposes.","این پول برای اهداف خیریه داده شد."],["He was charitable towards those in need.","نسبت به نیازمندان خیریه می‌کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inhale','inhale','v','استنشاق کردن، دم فرو بردن','to breathe air or a substance into your lungs','Inhale deeply and then breathe out slowly.','[["Inhale deeply and then breathe out slowly.","نفس عمیق بکشید و سپس به آرامی نفس خود را بیرون دهید."],["Workers inhaled toxic dust.","کارگران گرد و غبار سمی را استنشاق کردند."],["Plants inhale carbon dioxide through their leaves.","گیاهان دی اکسید کربن را از طریق برگ‌های خود استنشاق می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:alleviate','alleviate','v','کاهش دادن، تسکین دادن','to make pain or a problem less severe','The medicine alleviated her pain.','[["The medicine alleviated her pain.","دارو درد او را کاهش داد."],["New roads will alleviate traffic congestion.","جاده‌های جدید ازدحام ترافیک را کاهش می‌دهد."],["Aid helped alleviate poverty in the region.","کمک‌ها به کاهش فقر در منطقه کمک کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:goodwill','goodwill','n','حسن نیت، خیرخواهی','friendly and helpful feelings towards others','The visit was a gesture of goodwill.','[["The visit was a gesture of goodwill.","این دیدار نشانه حسن نیت بود."],["The company depends on the goodwill of its customers.","این شرکت به حسن نیت مشتریان خود بستگی دارد."],["They worked together in a spirit of goodwill.","آنها با روحیه حسن نیت با هم کار کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:speculate','speculate','v','گمانه‌زنی کردن، حدس زدن','to guess possible answers without having all the facts','Scientists speculate that the planet may have water.','[["Scientists speculate that the planet may have water.","دانشمندان حدس می‌زنند که این سیاره ممکن است آب داشته باشد."],["It is too early to speculate about the cause.","هنوز زود است که درباره علت آن حدس بزنیم."],["Many people speculated about his reasons.","بسیاری از مردم در مورد دلایل او گمانه زنی کردند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:propel','propel','v','به جلو راندن، به حرکت درآوردن','to push or drive something forward','The boat is propelled by a small engine.','[["The boat is propelled by a small engine.","قایق توسط یک موتور کوچک حرکت می‌کند."],["Fish propel themselves with their tails.","ماهی‌ها با دم خود را به حرکت در می‌آورند."],["The film propelled her to fame.","این فیلم او را به شهرت رساند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:wander','wander','v','پرسه زدن، سرگردان بودن','to walk slowly without a clear purpose or direction','We wandered around the old town.','[["We wandered around the old town.","دور شهر قدیمی گشتیم."],["The sheep wandered across the field.","گوسفندان در سراسر مزرعه سرگردان شدند."],["His mind wandered during the lecture.","در حین سخنرانی ذهنش سرگردان بود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:pinpoint','pinpoint','v','دقیقاً مشخص کردن، ریشه را پیدا کردن','to find or describe something exactly','Scientists pinpointed the cause of the disease.','[["Scientists pinpointed the cause of the disease.","دانشمندان علت این بیماری را مشخص کردند."],["It is hard to pinpoint when the change began.","تعیین دقیق زمان شروع تغییر دشوار است."],["GPS can pinpoint your location.","GPS می‌تواند موقعیت مکانی شما را مشخص کند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:possess','possess','v','داشتن، مالک بودن','to have or own something','He possessed great artistic talent.','[["He possessed great artistic talent.","او استعداد هنری بالایی داشت."],["The country possesses rich mineral resources.","این کشور دارای منابع معدنی غنی است."],["Some animals possess the ability to see in the dark.","برخی از حیوانات توانایی دیدن در تاریکی را دارند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:aspiration','aspiration','n','آرزو، آرمان، جاه‌طلبی','a strong desire to achieve something','She has aspirations to become a doctor.','[["She has aspirations to become a doctor.","او آرزوی دکتر شدن دارد."],["The program supports young people''s aspirations.","این برنامه از آرزوهای جوانان حمایت می‌کند."],["The nation''s aspirations for peace.","آرمان‌های ملت برای صلح."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:sophisticated','sophisticated','adj','پیشرفته، پیچیده؛ باتجربه و فرهیخته','advanced and complex; having knowledge of culture and fashion','The ancient city had a sophisticated water system.','[["The ancient city had a sophisticated water system.","این شهر باستانی سیستم آبی پیچیده ای داشت."],["Sophisticated equipment is used in the lab.","در آزمایشگاه از تجهیزات پیچیده ای استفاده می‌شود."],["She is a sophisticated young woman.","او یک زن جوان پیچیده است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:peripheral','peripheral','adj','جانبی، حاشیه‌ای، فرعی','not central or most important','The issue is peripheral to the main debate.','[["The issue is peripheral to the main debate.","موضوع پیرامون بحث اصلی است."],["Peripheral vision helps you see things to the side.","دید محیطی به شما کمک می‌کند تا چیزها را به پهلو ببینید."],["The city''s peripheral areas are poorer.","مناطق حاشیه ای شهر فقیرتر هستند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:canvas','canvas','n','بوم نقاشی؛ کرباس','strong cloth used for tents and sails; a piece of cloth used for painting','The artist painted on canvas.','[["The artist painted on canvas.","این هنرمند روی بوم نقاشی کرد."],["The tent was made of canvas.","چادر از بوم ساخته شده بود."],["The canvas was damaged in the fire.","بوم در آتش آسیب دید."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unleash','unleash','v','رها کردن، آزاد کردن (نیروی قوی)','to suddenly release a powerful force','The storm unleashed heavy rain.','[["The storm unleashed heavy rain.","طوفان باران شدیدی را به راه انداخت."],["Technology has unleashed new possibilities.","فناوری امکانات جدیدی را به وجود آورده است."],["The decision unleashed a wave of protests.","این تصمیم موجی از اعتراضات را برانگیخت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:criticism','criticism','n','انتقاد','the act of saying what is wrong with someone or something','The plan received strong criticism.','[["The plan received strong criticism.","این طرح مورد انتقاد شدید قرار گرفت."],["She accepted the criticism calmly.","او انتقاد را با آرامش پذیرفت."],["Literary criticism studies the meaning of texts.","نقد ادبی به بررسی معنای متون می‌پردازد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:attribute','attribute','n','ویژگی، صفت، خصوصیت','a quality or feature that someone or something has','Patience is a key attribute of a good teacher.','[["Patience is a key attribute of a good teacher.","صبر یکی از ویژگی‌های کلیدی یک معلم خوب است."],["Size is an important attribute of the animal.","اندازه یک ویژگی مهم حیوان است."],["What attributes make a good leader?","چه ویژگی‌هایی یک رهبر خوب را می‌سازد؟"]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:depict','depict','v','به تصویر کشیدن، نشان دادن','to show or describe someone or something in art or words','The painting depicts a battle.','[["The painting depicts a battle.","این نقاشی یک نبرد را به تصویر می‌کشد."],["The novel depicts life in 19th-century Iran.","این رمان زندگی در ایران قرن نوزدهم را به تصویر می‌کشد."],["Ancient carvings depict kings and soldiers.","کنده کاری‌های باستانی پادشاهان و سربازان را به تصویر می‌کشند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:retailer','retailer','n','خرده‌فروش','a person or company that sells goods to the public','Online retailers have grown quickly.','[["Online retailers have grown quickly.","خرده فروشان آنلاین به سرعت رشد کرده اند."],["The retailer cut its prices.","خرده فروش قیمت‌های خود را کاهش داد."],["Small retailers struggle to compete with supermarkets.","خرده فروشان کوچک برای رقابت با سوپرمارکت‌ها تلاش می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:revere','revere','v','بسیار احترام گذاشتن، تکریم کردن','to respect and admire someone or something deeply','Hafez is revered by Iranians.','[["Hafez is revered by Iranians.","حافظ نزد ایرانیان محترم است."],["The ancient Egyptians revered cats.","مصریان باستان به گربه‌ها احترام می‌گذاشتند."],["He is revered as a national hero.","او به عنوان یک قهرمان ملی مورد احترام است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:augment','augment','v','افزایش دادن، تقویت کردن','to increase the size or value of something','He took a second job to augment his income.','[["He took a second job to augment his income.","او برای افزایش درآمد خود شغل دومی را انتخاب کرد."],["The army was augmented by new soldiers.","ارتش با سربازان جدید تقویت شد."],["Technology can augment human abilities.","فناوری می‌تواند توانایی‌های انسان را افزایش دهد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:outrageous','outrageous','adj','خشم‌برانگیز، گستاخانه؛ فوق‌العاده زیاد','shocking and unacceptable; very unusual','The prices at that hotel are outrageous.','[["The prices at that hotel are outrageous.","قیمت‌های آن هتل افتضاح است."],["His behavior was outrageous.","رفتارش افتضاح بود"],["She made an outrageous claim.","او ادعای ظالمانه ای کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:entail','entail','v','مستلزم بودن، دربرداشتن','to involve something as a necessary part','The job entails a lot of travel.','[["The job entails a lot of travel.","این شغل مستلزم سفرهای زیادی است."],["What does the project entail?","پروژه شامل چه مواردی می‌شود؟"],["Such a change would entail great cost.","چنین تغییری هزینه زیادی را در پی خواهد داشت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:recoil','recoil','v','پس کشیدن، عقب رفتن (از ترس یا انزجار)','to move back suddenly in fear or disgust; to react strongly against','She recoiled at the sight of the snake.','[["She recoiled at the sight of the snake.","او با دیدن مار عقب نشست."],["People recoil from the idea of eating insects.","مردم از ایده خوردن حشرات عقب نشینی می‌کنند."],["The gun recoils when it is fired.","اسلحه هنگام شلیک پس می‌زند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:incorporate','incorporate','v','گنجاندن، دربرگرفتن','to include something as part of a whole','The new design incorporates solar panels.','[["The new design incorporates solar panels.","طراحی جدید شامل پنل‌های خورشیدی است."],["The course incorporates practical training.","این دوره شامل آموزش عملی است."],["Her ideas were incorporated into the plan.","ایده‌های او در طرح گنجانده شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inspiration','inspiration','n','الهام، منبع الهام','someone or something that gives you ideas; the feeling of being inspired','Nature was the inspiration for the design.','[["Nature was the inspiration for the design.","طبیعت الهام بخش طراحی بود."],["She is an inspiration to young athletes.","او الهام بخش ورزشکاران جوان است."],["The poet found inspiration in the mountains.","شاعر در کوهستان الهام گرفت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:determine','determine','v','تعیین کردن، مشخص کردن؛ تصمیم گرفتن','to discover the facts about something; to decide or influence something','Scientists determined the age of the rocks.','[["Scientists determined the age of the rocks.","دانشمندان سن سنگ‌ها را تعیین کردند."],["Genes determine eye color.","ژن‌ها رنگ چشم را تعیین می‌کنند."],["Price often determines what we buy.","قیمت اغلب تعیین می‌کند که چه چیزی بخریم."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:vessel','vessel','n','کشتی، شناور؛ رگ؛ ظرف','a large boat or ship; a tube that carries blood; a container','The vessel sank in the storm.','[["The vessel sank in the storm.","کشتی در طوفان غرق شد."],["Blood vessels carry blood around the body.","رگ‌های خونی خون را در سراسر بدن حمل می‌کنند."],["Clay vessels were used to store water.","از ظروف سفالی برای ذخیره آب استفاده می‌شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:timber','timber','n','الوار، چوب (ساختمانی)','wood used for building or making things','The house is built of timber.','[["The house is built of timber.","خانه از چوب ساخته شده است."],["The forest was cut down for timber.","جنگل برای چوب قطع شد."],["Timber exports have increased.","صادرات چوب افزایش یافته است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:endangered','endangered','adj','در معرض خطر انقراض','at risk of no longer existing','The Asiatic cheetah is an endangered species.','[["The Asiatic cheetah is an endangered species.","یوزپلنگ آسیایی یک گونه در معرض خطر انقراض است."],["Many endangered animals live in this forest.","بسیاری از حیوانات در حال انقراض در این جنگل زندگی می‌کنند."],["Laws protect endangered plants.","قوانین از گیاهان در خطر انقراض محافظت می‌کنند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:voyage','voyage','n','سفر دریایی، سفر طولانی','a long journey, especially by sea or in space','Columbus made his first voyage in 1492.','[["Columbus made his first voyage in 1492.","کلمب اولین سفر خود را در سال 1492 انجام داد."],["The voyage across the ocean took months.","سفر بر روی اقیانوس ماه‌ها طول کشید."],["The spacecraft began its voyage to Mars.","این فضاپیما سفر خود به مریخ را آغاز کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:charcoal','charcoal','n','زغال (چوب)','a black substance made by burning wood slowly','We cooked kebabs over charcoal.','[["We cooked kebabs over charcoal.","کباب را روی زغال پختیم."],["Charcoal can be used to purify water.","از زغال چوب می‌توان برای تصفیه آب استفاده کرد."],["Early artists drew with charcoal.","هنرمندان اولیه با زغال می‌کشیدند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:nutrient','nutrient','n','ماده مغذی','a substance that living things need to grow and stay healthy','Plants absorb nutrients from the soil.','[["Plants absorb nutrients from the soil.","گیاهان مواد مغذی را از خاک جذب می‌کنند."],["Vegetables are rich in nutrients.","سبزیجات سرشار از مواد مغذی هستند."],["The river carries nutrients to the sea.","رودخانه مواد مغذی را به دریا می‌برد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:daunting','daunting','adj','دلهره‌آور، ترسناک (به‌خاطر دشواری)','making you feel nervous and less confident','Moving to a new country can be daunting.','[["Moving to a new country can be daunting.","مهاجرت به یک کشور جدید می‌تواند دلهره آور باشد."],["The task seemed daunting at first.","کار در ابتدا دلهره آور به نظر می‌رسید."],["She faced a daunting challenge.","او با یک چالش دلهره آور روبرو شد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:solidify','solidify','v','تحکیم کردن، استوار کردن؛ جامد شدن','to make something stronger or more certain; to become solid','The victory solidified his position.','[["The victory solidified his position.","این پیروزی موقعیت او را مستحکم کرد."],["Lava solidifies as it cools.","گدازه با سرد شدن جامد می‌شود."],["The agreement solidified the relationship between the two countries.","این توافق روابط بین دو کشور را مستحکم کرد."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:incompetent','incompetent','adj','بی‌کفایت، ناتوان','lacking the skill to do something well','The manager was incompetent.','[["The manager was incompetent.","مدیر ناتوان بود."],["Incompetent doctors can be dangerous.","پزشکان بی کفایت می‌توانند خطرناک باشند."],["The report criticized the incompetent government.","در این گزارش از دولت نالایق انتقاد شده است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:viable','viable','adj','عملی، قابل اجرا؛ ماندگار','able to work successfully; able to survive','Solar power is a viable alternative to oil.','[["Solar power is a viable alternative to oil.","انرژی خورشیدی جایگزین مناسبی برای نفت است."],["The plan is not financially viable.","این طرح از نظر مالی مقرون به صرفه نیست."],["The seeds remained viable for years.","بذرها برای سالها زنده ماندند."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:life expectancy','life expectancy','n','امید به زندگی','the average number of years a person is expected to live','Life expectancy has increased in most countries.','[["Life expectancy has increased in most countries.","امید به زندگی در اکثر کشورها افزایش یافته است."],["Japan has one of the highest life expectancies.","ژاپن یکی از بالاترین امید به زندگی را دارد."],["Poor diet reduces life expectancy.","رژیم غذایی نامناسب باعث کاهش امید به زندگی می‌شود."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:indigenous','indigenous','adj','بومی','naturally existing in a place; belonging to the original people of a place','Indigenous plants need less water.','[["Indigenous plants need less water.","گیاهان بومی به آب کمتری نیاز دارند."],["The indigenous people of Australia have a long history.","مردم بومی استرالیا تاریخچه ای طولانی دارند."],["The tree is indigenous to Iran.","این درخت بومی ایران است."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:miscellaneous','miscellaneous','adj','متفرقه، گوناگون','consisting of different kinds of things that are not connected','The box contained miscellaneous items.','[["The box contained miscellaneous items.","جعبه حاوی اقلام متفرقه بود."],["There is a section for miscellaneous expenses.","بخشی برای هزینه‌های متفرقه وجود دارد."],["She wrote miscellaneous articles for newspapers.","او مقالات متفرقه ای برای روزنامه‌ها می‌نوشت."]]','ielts',5,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:disperse','disperse','v','پراکنده کردن، پخش شدن','to spread over a wide area; to make people leave a place','The wind disperses the seeds.','[["The wind disperses the seeds.","باد دانه‌ها را پراکنده می‌کند."],["Police dispersed the crowd.","پلیس جمعیت را متفرق کرد."],["The fog dispersed by noon.","مه تا ظهر پراکنده شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:harbor','harbor','n','بندر، لنگرگاه','an area of water near the coast where ships are safe','The boats returned to the harbor.','[["The boats returned to the harbor.","قایق‌ها به بندر برگشتند."],["The city grew around its natural harbor.","این شهر در اطراف بندر طبیعی خود رشد کرد."],["Fishing boats are tied up in the harbor.","قایق‌های ماهیگیری در بندر بسته شده اند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:exposure','exposure','n','قرار گرفتن در معرض','the state of being in a situation where something could affect you','Exposure to sunlight is good for plants.','[["Exposure to sunlight is good for plants.","قرار گرفتن در معرض نور خورشید برای گیاهان مفید است."],["Long exposure to noise can damage hearing.","قرار گرفتن طولانی مدت در معرض صدا می‌تواند به شنوایی آسیب برساند."],["Children''s exposure to English starts early.","آشنایی کودکان با زبان انگلیسی زود شروع می‌شود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:decompose','decompose','v','تجزیه شدن، پوسیدن','to be slowly destroyed by natural processes','Leaves decompose and enrich the soil.','[["Leaves decompose and enrich the soil.","برگ‌ها تجزیه می‌شوند و خاک را غنی می‌کنند."],["Plastic takes hundreds of years to decompose.","صدها سال طول می‌کشد تا پلاستیک تجزیه شود."],["Bacteria help dead animals decompose.","باکتری‌ها به تجزیه حیوانات مرده کمک می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:decay','decay','v','پوسیدن، فاسد شدن؛ رو به زوال رفتن','to be gradually destroyed by natural processes; to become weaker','Sugar causes teeth to decay.','[["Sugar causes teeth to decay.","شکر باعث پوسیدگی دندان‌ها می‌شود."],["The wood had decayed over time.","چوب به مرور زمان پوسیده شده بود."],["The old city slowly decayed.","شهر قدیم کم کم از بین رفت."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:regardless of','regardless of','prep','بدون توجه به، صرف‌نظر از','without being affected by something','Everyone has the right to education regardless of income.','[["Everyone has the right to education regardless of income.","هر کس بدون در نظر گرفتن درآمد حق تحصیل دارد."],["The plants grow well regardless of the weather.","گیاهان بدون توجه به آب و هوا به خوبی رشد می‌کنند."],["He continued regardless of the danger.","او بدون توجه به خطر ادامه داد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:indiscriminate','indiscriminate','adj','بی‌رویه، بی‌حساب، بدون تمایز','done without careful thought or without choosing','The indiscriminate use of pesticides kills useful insects.','[["The indiscriminate use of pesticides kills useful insects.","استفاده بی رویه از آفت کش‌ها حشرات مفید را از بین می‌برد."],["Indiscriminate hunting reduced the number of deer.","شکار بی رویه تعداد گوزن‌ها را کاهش داد."],["The bombing was indiscriminate.","بمباران بدون تبعیض بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:babble','babble','v','نامفهوم حرف زدن، ور زدن','to talk quickly in a way that is hard to understand; (of a baby) to make speech-like sounds','Babies babble before they learn to talk.','[["Babies babble before they learn to talk.","نوزادان قبل از اینکه حرف زدن را یاد بگیرند غرغر می‌کنند."],["He babbled nervously.","عصبی غرغر کرد."],["The stream babbled over the stones.","جویبار روی سنگ‌ها غوغا می‌کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fertile','fertile','adj','حاصلخیز؛ بارور','(of land) able to produce good crops; able to have babies','The fertile soil of the valley produces rich harvests.','[["The fertile soil of the valley produces rich harvests.","خاک حاصلخیز دره محصولی غنی تولید می‌کند."],["The region has fertile land near the river.","این منطقه دارای زمین‌های حاصلخیز در نزدیکی رودخانه است."],["Women are most fertile in their twenties.","زنان در دهه بیست خود بیشترین باروری را دارند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:mimic','mimic','v','تقلید کردن، ادای (کسی) را درآوردن','to copy the way someone or something looks, sounds or behaves','Parrots can mimic human speech.','[["Parrots can mimic human speech.","طوطی‌ها می‌توانند گفتار انسان را تقلید کنند."],["Some insects mimic leaves to avoid predators.","برخی از حشرات برای جلوگیری از شکارچیان از برگ‌ها تقلید می‌کنند."],["Robots are designed to mimic human movements.","ربات‌ها برای تقلید حرکات انسان طراحی شده اند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:fertilizer','fertilizer','n','کود','a natural or chemical substance added to soil to help plants grow','Farmers use fertilizer to increase crop yields.','[["Farmers use fertilizer to increase crop yields.","کشاورزان از کود برای افزایش محصول استفاده می‌کنند."],["Too much fertilizer can pollute rivers.","کود زیاد می‌تواند رودخانه‌ها را آلوده کند."],["Animal waste is a natural fertilizer.","فضولات حیوانی یک کود طبیعی است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:induce','induce','v','القا کردن، موجب شدن، وادار کردن','to cause something to happen; to persuade someone','Some drugs induce sleep.','[["Some drugs induce sleep.","برخی داروها خواب را تحریک می‌کنند."],["Stress can induce headaches.","استرس می‌تواند باعث سردرد شود."],["Nothing could induce him to leave.","هیچ چیز نمی‌توانست او را ترغیب به ترک کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:prompt','prompt','v','موجب شدن، برانگیختن','to cause someone to do something; to cause something to happen','The accident prompted a review of safety rules.','[["The accident prompted a review of safety rules.","این حادثه باعث بازنگری قوانین ایمنی شد."],["What prompted you to study biology?","چه چیزی شما را به تحصیل زیست شناسی تشویق کرد؟"],["High prices prompted many people to buy smaller cars.","قیمت‌های بالا بسیاری از مردم را وادار به خرید خودروهای کوچکتر کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:benchmark','benchmark','n','معیار، محک','a standard used to measure or compare other things','The test is a benchmark for English ability.','[["The test is a benchmark for English ability.","این آزمون معیاری برای توانایی زبان انگلیسی است."],["The company set a new benchmark for quality.","این شرکت معیار جدیدی را برای کیفیت تعیین کرد."],["These results will be used as a benchmark.","این نتایج به عنوان معیار استفاده خواهد شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:uncover','uncover','v','کشف کردن، آشکار کردن، فاش کردن','to discover something hidden or secret; to remove a cover','Archaeologists uncovered an ancient city.','[["Archaeologists uncovered an ancient city.","باستان شناسان یک شهر باستانی را کشف کردند."],["Journalists uncovered the truth.","روزنامه نگاران حقیقت را فاش کردند."],["The investigation uncovered serious errors.","تحقیقات به اشتباهات جدی پی برد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:neutral','neutral','adj','بی‌طرف؛ خنثی','not supporting either side; neither acid nor alkaline','Switzerland remained neutral during the war.','[["Switzerland remained neutral during the war.","سوئیس در طول جنگ بی طرف ماند."],["Pure water is chemically neutral.","آب خالص از نظر شیمیایی خنثی است."],["The article was written in a neutral tone.","مقاله با لحنی خنثی نوشته شده است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:launch','launch','v','راه‌اندازی کردن، آغاز کردن؛ پرتاب کردن','to start something new; to send a rocket into space','The company launched a new product.','[["The company launched a new product.","این شرکت محصول جدیدی را روانه بازار کرد."],["The government launched a campaign against smoking.","دولت کمپینی را علیه استعمال دخانیات راه اندازی کرد."],["The rocket was launched in 1969.","این موشک در سال 1969 پرتاب شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:degrade','degrade','v','تخریب کردن، تنزل دادن؛ تجزیه شدن','to make something worse in quality; to break down chemically','Pollution degrades the environment.','[["Pollution degrades the environment.","آلودگی محیط زیست را تخریب می‌کند."],["Some plastics degrade quickly in sunlight.","برخی از پلاستیک‌ها به سرعت در برابر نور خورشید تجزیه می‌شوند."],["The soil was degraded by overuse.","خاک در اثر استفاده بیش از حد تخریب شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:flourish','flourish','v','شکوفا شدن، رشد کردن، رونق یافتن','to grow or develop successfully','Trade flourished along the Silk Road.','[["Trade flourished along the Silk Road.","تجارت در امتداد جاده ابریشم رونق گرفت."],["The plants flourish in warm weather.","گیاهان در هوای گرم شکوفا می‌شوند."],["Art and science flourished under the Safavids.","هنر و علم در زمان صفویان شکوفا شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ultimate','ultimate','adj','نهایی، غایی؛ بزرگ‌ترین','final; the greatest or most extreme','Our ultimate goal is to protect the forest.','[["Our ultimate goal is to protect the forest.","هدف نهایی ما حفاظت از جنگل است."],["The ultimate responsibility lies with the government.","مسئولیت نهایی بر عهده دولت است."],["Climbing Everest is the ultimate challenge.","صعود به اورست چالش نهایی است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:temple','temple','n','معبد','a building used for worship','The ancient temple was built of stone.','[["The ancient temple was built of stone.","معبد باستانی از سنگ ساخته شده بود."],["Tourists visited the temples of Kyoto.","گردشگران از معابد کیوتو بازدید کردند."],["The temple was dedicated to the sun god.","معبد به خدای خورشید تقدیم شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:explore','explore','v','کاوش کردن، جست‌وجو کردن، بررسی کردن','to travel to a place to learn about it; to examine something','Scientists are exploring the deep ocean.','[["Scientists are exploring the deep ocean.","دانشمندان در حال کاوش در اعماق اقیانوس هستند."],["We explored the old city on foot.","شهر قدیمی را پیاده گشتیم."],["The study explores the effects of social media.","این مطالعه به بررسی اثرات رسانه‌های اجتماعی می‌پردازد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:exempt','exempt','adj','معاف','not required to do or pay something','Children are exempt from the tax.','[["Children are exempt from the tax.","کودکان از پرداخت مالیات معاف هستند."],["Some goods are exempt from import duties.","برخی از کالاها از حقوق ورودی معاف هستند."],["Students are exempt from military service until they graduate.","دانشجویان تا زمان فارغ التحصیلی از خدمت سربازی معاف هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:demise','demise','n','مرگ؛ زوال، نابودی','death; the end or failure of something','The demise of the dinosaurs happened 66 million years ago.','[["The demise of the dinosaurs happened 66 million years ago.","مرگ دایناسورها 66 میلیون سال پیش اتفاق افتاد."],["The demise of the company surprised many.","سقوط شرکت بسیاری را شگفت زده کرد."],["The internet led to the demise of many newspapers.","اینترنت منجر به از بین رفتن بسیاری از روزنامه‌ها شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:reconcile','reconcile','v','آشتی دادن؛ هماهنگ کردن، سازگار کردن','to make two ideas or facts agree; to make people friends again','It is hard to reconcile economic growth with protecting nature.','[["It is hard to reconcile economic growth with protecting nature.","تطبیق رشد اقتصادی با حفاظت از طبیعت دشوار است."],["The two brothers were finally reconciled.","بالاخره دو برادر با هم آشتی کردند."],["Scientists tried to reconcile the two theories.","دانشمندان سعی کردند این دو نظریه را با هم تطبیق دهند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:invade','invade','v','حمله کردن، تهاجم کردن، وارد حریم شدن','to enter a country by force; to spread into an area in a harmful way','The army invaded the country.','[["The army invaded the country.","ارتش به کشور حمله کرد."],["Weeds invaded the garden.","علف‌های هرز به باغ هجوم آوردند."],["Bacteria invade the body through cuts.","باکتری‌ها از طریق بریدگی به بدن حمله می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:pioneer','pioneer','n','پیشگام، پیشرو','one of the first people to do something','She was a pioneer of modern medicine.','[["She was a pioneer of modern medicine.","او پیشگام طب مدرن بود."],["The company is a pioneer in solar technology.","این شرکت پیشگام در فناوری خورشیدی است."],["Early pioneers crossed the mountains.","پیشگامان اولیه از کوه‌ها عبور کردند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:flaw','flaw','n','نقص، عیب، ایراد','a fault or weakness','There is a serious flaw in the argument.','[["There is a serious flaw in the argument.","یک اشکال جدی در استدلال وجود دارد."],["The diamond has a small flaw.","الماس یک عیب کوچک دارد."],["Experts found flaws in the design.","کارشناسان ایراداتی در طراحی پیدا کردند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:integral','integral','adj','جدایی‌ناپذیر، ضروری، اساسی','necessary and important as part of a whole','Music is an integral part of the culture.','[["Music is an integral part of the culture.","موسیقی بخشی جدایی ناپذیر از فرهنگ است."],["Exercise is integral to good health.","ورزش جزء لاینفک سلامتی است."],["The kitchen is integral to the design of the house.","آشپزخانه جزء لاینفک طراحی خانه است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:evaporation','evaporation','n','تبخیر','the process of a liquid changing into gas','Evaporation is faster on hot days.','[["Evaporation is faster on hot days.","تبخیر در روزهای گرم سریعتر است."],["Salt is produced by the evaporation of sea water.","نمک از تبخیر آب دریا تولید می‌شود."],["Lakes lose water through evaporation.","دریاچه‌ها از طریق تبخیر آب خود را از دست می‌دهند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:tendency','tendency','n','تمایل، گرایش','a habit or likelihood of behaving in a particular way','There is a tendency for prices to rise in winter.','[["There is a tendency for prices to rise in winter.","تمایل به افزایش قیمت‌ها در زمستان وجود دارد."],["He has a tendency to exaggerate.","او تمایل به اغراق دارد."],["Young people show a tendency towards online shopping.","جوانان تمایل به خرید آنلاین نشان می‌دهند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:threat','threat','n','تهدید','a person or thing likely to cause damage or danger','Climate change is a threat to many species.','[["Climate change is a threat to many species.","تغییرات آب و هوایی تهدیدی برای بسیاری از گونه‌ها است."],["Pollution poses a serious threat to health.","آلودگی یک تهدید جدی برای سلامتی است."],["The animals live under constant threat from hunters.","این حیوانات تحت تهدید دائمی شکارچیان زندگی می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:quantify','quantify','v','کمّی کردن، اندازه‌گیری کردن','to measure or express the amount of something','It is difficult to quantify the benefits of education.','[["It is difficult to quantify the benefits of education.","کمی کردن مزایای آموزش دشوار است."],["Scientists tried to quantify the damage.","دانشمندان سعی کردند میزان آسیب را تعیین کنند."],["The risks are hard to quantify.","کمیت کردن خطرات سخت است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:enchanting','enchanting','adj','دلربا، افسونگر، جذاب','very attractive and pleasant','The village is enchanting in spring.','[["The village is enchanting in spring.","روستا در فصل بهار مسحور کننده است."],["She has an enchanting voice.","او صدای دلربایی دارد."],["The garden was an enchanting place.","باغ جای دلربایی بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:outskirts','outskirts','n','حومه شهر','the outer areas of a city or town','They live on the outskirts of Tehran.','[["They live on the outskirts of Tehran.","آنها در حومه تهران زندگی می‌کنند."],["The factory is on the outskirts of the city.","این کارخانه در حومه شهر است."],["New houses were built on the outskirts.","خانه‌های جدید در حاشیه ساخته شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:millennium','millennium','n','هزاره','a period of a thousand years','The city was founded more than a millennium ago.','[["The city was founded more than a millennium ago.","این شهر بیش از یک هزار سال پیش تأسیس شد."],["The celebrations marked the new millennium.","این جشن‌ها هزاره جدید را رقم زد."],["Writing developed in the fourth millennium BC.","نوشتن در هزاره چهارم قبل از میلاد توسعه یافت."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:excursion','excursion','n','گردش، سفر کوتاه','a short journey for pleasure or study','The class went on an excursion to the museum.','[["The class went on an excursion to the museum.","کلاس به گشت و گذار در موزه رفت."],["We made an excursion to the mountains.","گشتی به کوه زدیم."],["The hotel organizes excursions for guests.","این هتل برای میهمانان تورهای گردشگری برگزار می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:scarce','scarce','adj','کمیاب، نایاب','not available in large amounts','Water is scarce in the desert.','[["Water is scarce in the desert.","آب در کویر کمیاب است."],["Food became scarce during the war.","غذا در طول جنگ کمیاب شد."],["Jobs are scarce in rural areas.","شغل در مناطق روستایی کمیاب است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:found','found','v','بنیان نهادن، تأسیس کردن','to start an organization or build a town','The university was founded in 1934.','[["The university was founded in 1934.","این دانشگاه در سال 1934 تاسیس شد."],["The city was founded by traders.","این شهر توسط بازرگانان تأسیس شد."],["She founded a charity to help children.","او یک موسسه خیریه برای کمک به کودکان تاسیس کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:implication','implication','n','پیامد، نتیجه ضمنی، تلویح','a possible effect or result; something suggested but not said directly','The new law has serious implications for farmers.','[["The new law has serious implications for farmers.","قانون جدید پیامدهای جدی برای کشاورزان دارد."],["What are the implications of the study?","پیامدهای مطالعه چیست؟"],["The implication was that he had lied.","مفهومش این بود که دروغ گفته بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:province','province','n','استان','one of the areas into which a country is divided','Fars is a province in southern Iran.','[["Fars is a province in southern Iran.","فارس استانی در جنوب ایران است."],["Each province has its own government.","هر استانی دولت خود را دارد."],["Canada is divided into ten provinces.","کانادا به ده استان تقسیم شده است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:spontaneous','spontaneous','adj','خودجوش، خودبه‌خودی، بی‌مقدمه','happening naturally, without being planned','The crowd broke into spontaneous applause.','[["The crowd broke into spontaneous applause.","جمعیت با تشویق خودجوش شکستند."],["Forest fires can be spontaneous in hot weather.","آتش سوزی جنگل‌ها می‌تواند در هوای گرم خود به خود باشد."],["Their decision to travel was spontaneous.","تصمیم آنها برای سفر خودجوش بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cater','cater','v','تأمین کردن، رسیدگی کردن؛ پذیرایی کردن','to provide what is needed; to provide food for an event','The school caters for students of all abilities.','[["The school caters for students of all abilities.","این مدرسه برای دانش آموزان با تمام توانایی‌ها آماده است."],["The hotel caters to business travelers.","این هتل پذیرای مسافران تجاری است."],["A local company catered the wedding.","یک شرکت محلی مراسم عروسی را تهیه کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:mansion','mansion','n','عمارت، قصر','a very large and impressive house','The family lives in a mansion.','[["The family lives in a mansion.","خانواده در یک عمارت زندگی می‌کنند."],["The old mansion is now a museum.","عمارت قدیمی اکنون به موزه تبدیل شده است."],["Rich merchants built mansions near the river.","تجار ثروتمند در نزدیکی رودخانه عمارت‌هایی ساختند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:controversy','controversy','n','جنجال، مناقشه، بحث‌وجدل','public disagreement about something','The decision caused controversy.','[["The decision caused controversy.","این تصمیم جنجال به پا کرد."],["There is controversy over the use of animals in research.","در مورد استفاده از حیوانات در تحقیقات اختلاف نظر وجود دارد."],["The book created a lot of controversy.","این کتاب جنجال زیادی ایجاد کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hold','hold','v','برگزار کردن؛ نگه داشتن؛ گنجایش داشتن','to organize an event; to keep something in your hands; to contain','The conference will be held in May.','[["The conference will be held in May.","این کنفرانس در اردیبهشت ماه برگزار می‌شود."],["The stadium holds 80,000 people.","این ورزشگاه 80000 نفر را در خود جای داده است."],["Elections are held every four years.","انتخابات هر چهار سال یکبار برگزار می‌شود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:disorder','disorder','n','اختلال، بی‌نظمی','an illness of the mind or body; a lack of order','Sleep disorders affect millions of people.','[["Sleep disorders affect millions of people.","اختلالات خواب میلیون‌ها نفر را تحت تاثیر قرار می‌دهد."],["The room was in complete disorder.","اتاق کاملا به هم ریخته بود."],["Some genetic disorders are rare.","برخی از اختلالات ژنتیکی نادر هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:wicked','wicked','adj','شرور، بدجنس، پلید','morally very bad','The story is about a wicked queen.','[["The story is about a wicked queen.","داستان در مورد یک ملکه شریر است."],["It was a wicked thing to do.","این کار زشتی بود."],["The wicked witch was defeated in the end.","جادوگر بدجنس در نهایت شکست خورد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:artificial','artificial','adj','مصنوعی','made by people rather than nature','The lake is artificial.','[["The lake is artificial.","دریاچه مصنوعی است."],["Artificial intelligence is changing many industries.","هوش مصنوعی در حال تغییر بسیاری از صنایع است."],["The food contains no artificial colors.","غذا حاوی هیچ رنگ مصنوعی نیست."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:crisis','crisis','n','بحران','a time of great danger or difficulty','The country faced an economic crisis.','[["The country faced an economic crisis.","کشور با بحران اقتصادی مواجه شد."],["There is a water crisis in many cities.","در بسیاری از شهرها بحران آب وجود دارد."],["The government acted quickly in the crisis.","دولت در این بحران به سرعت عمل کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:consumerism','consumerism','n','مصرف‌گرایی','the belief that buying more goods is good; concern with buying things','Critics say consumerism harms the environment.','[["Critics say consumerism harms the environment.","منتقدان می‌گویند مصرف گرایی به محیط زیست آسیب می‌زند."],["Consumerism grew rapidly after the war.","مصرف گرایی پس از جنگ به سرعت رشد کرد."],["The film criticizes modern consumerism.","این فیلم به نقد مصرف گرایی مدرن می‌پردازد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:skyscraper','skyscraper','n','آسمان‌خراش','a very tall building in a city','Dubai is famous for its skyscrapers.','[["Dubai is famous for its skyscrapers.","دبی به خاطر آسمان خراش هایش معروف است."],["The skyscraper has 100 floors.","این آسمان خراش 100 طبقه دارد."],["New skyscrapers changed the city''s skyline.","آسمان خراش‌های جدید افق شهر را تغییر دادند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:seize','seize','v','قاپیدن، به‌زور گرفتن؛ غنیمت شمردن','to take something quickly and firmly; to take control by force','The police seized the drugs.','[["The police seized the drugs.","پلیس مواد مخدر را کشف و ضبط کرد."],["Rebels seized control of the city.","شورشیان کنترل شهر را به دست گرفتند."],["She seized the opportunity to study abroad.","او از این فرصت برای تحصیل در خارج از کشور استفاده کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:relentless','relentless','adj','بی‌امان، بی‌وقفه؛ بی‌رحم','continuing strongly without stopping','The relentless rain caused floods.','[["The relentless rain caused floods.","باران بی امان باعث جاری شدن سیل شد."],["He faced relentless criticism.","او با انتقادهای بی امان روبرو شد."],["Their relentless efforts finally succeeded.","تلاش‌های بی وقفه آنها سرانجام به نتیجه رسید."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:arouse','arouse','v','برانگیختن، ایجاد کردن (احساس یا علاقه)','to cause a feeling or interest','The discovery aroused great interest.','[["The discovery aroused great interest.","این کشف علاقه زیادی را برانگیخت."],["His behavior aroused suspicion.","رفتار او شبهه را برانگیخت."],["The story aroused the children''s curiosity.","این داستان کنجکاوی بچه‌ها را برانگیخت."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:habitable','habitable','adj','قابل سکونت','suitable for living in','Scientists search for habitable planets.','[["Scientists search for habitable planets.","دانشمندان در جستجوی سیارات قابل سکونت هستند."],["The old house was no longer habitable.","خانه قدیمی دیگر قابل سکونت نبود."],["Only a small part of the island is habitable.","تنها بخش کوچکی از جزیره قابل سکونت است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:pivotal','pivotal','adj','محوری، بسیار مهم، تعیین‌کننده','of great importance because other things depend on it','She played a pivotal role in the project.','[["She played a pivotal role in the project.","او نقش مهمی در این پروژه ایفا کرد."],["The battle was a pivotal moment in history.","نبرد یک لحظه مهم در تاریخ بود."],["Education is pivotal to development.","آموزش نقش اساسی در توسعه دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ventilation','ventilation','n','تهویه','the supply of fresh air to a room or building','Good ventilation is important in kitchens.','[["Good ventilation is important in kitchens.","تهویه خوب در آشپزخانه‌ها مهم است."],["The mine has a poor ventilation system.","معدن سیستم تهویه ضعیفی دارد."],["Traditional windcatchers provide natural ventilation.","بادگیرهای سنتی تهویه طبیعی را فراهم می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:decisive','decisive','adj','تعیین‌کننده، قاطع','very important for the result; able to make decisions quickly','The battle was decisive in ending the war.','[["The battle was decisive in ending the war.","نبرد در پایان جنگ تعیین کننده بود."],["She is a decisive leader.","او یک رهبر تعیین کننده است."],["Price was the decisive factor.","قیمت عامل تعیین کننده بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:outbreak','outbreak','n','شیوع ناگهانی، بروز (بیماری یا جنگ)','the sudden start of something unpleasant, especially disease or war','There was an outbreak of cholera in the city.','[["There was an outbreak of cholera in the city.","شیوع وبا در شهر رخ داد."],["The outbreak of war changed everything.","شروع جنگ همه چیز را تغییر داد."],["Doctors are trying to control the outbreak.","پزشکان در تلاش برای کنترل شیوع این بیماری هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:gadget','gadget','n','وسیله کوچک کاربردی، ابزار','a small, useful device','The kitchen is full of modern gadgets.','[["The kitchen is full of modern gadgets.","آشپزخانه پر از وسایل مدرن است."],["He loves the latest electronic gadgets.","او عاشق جدیدترین ابزارهای الکترونیکی است."],["This gadget opens bottles easily.","این گجت بطری‌ها را به راحتی باز می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:municipality','municipality','n','شهرداری؛ شهر/منطقه دارای حکومت محلی','a town or city with its own local government; that government','The municipality is responsible for waste collection.','[["The municipality is responsible for waste collection.","شهرداری مسئول جمع آوری زباله است."],["Tehran municipality planted thousands of trees.","شهرداری تهران هزاران اصله درخت کاشت."],["Each municipality sets its own rules.","هر شهرداری قوانین خود را تعیین می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:excessive','excessive','adj','بیش از حد، افراطی','more than is necessary or reasonable','Excessive use of water caused the lake to dry up.','[["Excessive use of water caused the lake to dry up.","استفاده بیش از حد از آب باعث خشک شدن دریاچه شد."],["Excessive noise can damage hearing.","سر و صدای زیاد می‌تواند به شنوایی آسیب برساند."],["The prices were excessive.","قیمت‌ها بیش از حد بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hospitality','hospitality','n','مهمان‌نوازی؛ صنعت پذیرایی و هتلداری','friendly treatment of guests; the business of hotels and restaurants','Thank you for your hospitality.','[["Thank you for your hospitality.","ممنون از مهمان نوازی شما"],["Persian hospitality is famous.","مهمان نوازی ایرانی زبانزد است."],["She works in the hospitality industry.","او در صنعت مهمان نوازی کار می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:outcome','outcome','n','نتیجه، پیامد','the result of an action or process','The outcome of the experiment was surprising.','[["The outcome of the experiment was surprising.","نتیجه آزمایش شگفت آور بود."],["Nobody can predict the outcome of the election.","هیچ کس نمی‌تواند نتیجه انتخابات را پیش بینی کند."],["The outcome depends on many factors.","نتیجه به عوامل زیادی بستگی دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:entrepreneur','entrepreneur','n','کارآفرین','a person who starts a business and takes financial risks','Young entrepreneurs are starting tech companies.','[["Young entrepreneurs are starting tech companies.","کارآفرینان جوان در حال راه اندازی شرکت‌های فناوری هستند."],["She is a successful entrepreneur.","او یک کارآفرین موفق است."],["The government supports local entrepreneurs.","دولت از کارآفرینان محلی حمایت می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:recur','recur','v','دوباره رخ دادن، عود کردن','to happen again or many times','The problem recurred after a few weeks.','[["The problem recurred after a few weeks.","مشکل بعد از چند هفته عود کرد."],["The theme recurs throughout the novel.","موضوع در سراسر رمان تکرار می‌شود."],["If the pain recurs, see a doctor.","اگر درد عود کرد، به پزشک مراجعه کنید."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:obsession','obsession','n','وسواس، دل‌مشغولی شدید','something you think about all the time; an unhealthy interest','He has an obsession with cleanliness.','[["He has an obsession with cleanliness.","او به نظافت علاقه دارد."],["Football is his obsession.","فوتبال وسواس اوست."],["Society''s obsession with appearance worries experts.","وسواس جامعه نسبت به ظاهر، کارشناسان را نگران می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:retention','retention','n','حفظ، نگهداری، به‌خاطر سپاری','the act of keeping something','Regular review improves memory retention.','[["Regular review improves memory retention.","مرور منظم حفظ حافظه را بهبود می‌بخشد."],["The company focuses on staff retention.","تمرکز این شرکت بر حفظ کارکنان است."],["The soil has good water retention.","خاک حفظ آب خوبی دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:cite','cite','v','نقل قول کردن، استناد کردن','to mention something as an example or proof; to quote','The report cites several studies.','[["The report cites several studies.","در این گزارش به چندین مطالعه اشاره شده است."],["She cited lack of time as the reason.","او دلیل آن را کمبود وقت عنوان کرد."],["Always cite your sources in an essay.","همیشه منابع خود را در مقاله ذکر کنید."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:outweigh','outweigh','v','بیشتر بودن (در اهمیت یا ارزش)، چربیدن','to be greater or more important than something else','The benefits outweigh the risks.','[["The benefits outweigh the risks.","مزایای آن بیشتر از خطرات است."],["The disadvantages outweigh the advantages.","معایب بیشتر از مزایا است."],["His experience outweighs his age.","تجربه او بیشتر از سنش است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:morale','morale','n','روحیه','the confidence and enthusiasm of a person or group','The victory raised the team''s morale.','[["The victory raised the team''s morale.","این پیروزی روحیه تیم را بالا برد."],["Staff morale is low.","روحیه کارکنان پایین است."],["Good news boosted public morale.","اخبار خوب روحیه عمومی را تقویت کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hierarchy','hierarchy','n','سلسله‌مراتب','a system in which people or things are arranged by importance','Ants live in a strict social hierarchy.','[["Ants live in a strict social hierarchy.","مورچه‌ها در یک سلسله مراتب اجتماعی سخت زندگی می‌کنند."],["He moved up the company hierarchy.","او سلسله مراتب شرکت را ارتقا داد."],["There is a hierarchy of needs.","سلسله مراتبی از نیازها وجود دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:inherently','inherently','adv','ذاتاً، به‌طور ذاتی','as a basic and permanent part of something','No language is inherently more difficult than another.','[["No language is inherently more difficult than another.","هیچ زبانی ذاتا دشوارتر از زبان دیگر نیست."],["The job is inherently dangerous.","شغل ذاتاً خطرناک است."],["Humans are inherently social.","انسان‌ها ذاتا اجتماعی هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:collaborate','collaborate','v','همکاری کردن','to work together with others','Scientists from five countries collaborated on the project.','[["Scientists from five countries collaborated on the project.","دانشمندان پنج کشور در این پروژه همکاری کردند."],["The two artists collaborated on an album.","این دو هنرمند در یک آلبوم با یکدیگر همکاری کردند."],["Students collaborate in small groups.","دانش آموزان در گروه‌های کوچک با هم همکاری می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:predisposition','predisposition','n','استعداد ذاتی، زمینه (ابتلا)، تمایل','a tendency to behave in a certain way or suffer from a disease','Some people have a genetic predisposition to diabetes.','[["Some people have a genetic predisposition to diabetes.","برخی افراد استعداد ژنتیکی دیابت دارند."],["Children have a natural predisposition to learn language.","کودکان استعداد طبیعی برای یادگیری زبان دارند."],["A predisposition to anxiety can run in families.","تمایل به اضطراب می‌تواند در خانواده‌ها ایجاد شود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:debris','debris','n','آوار، بقایا، خرده‌ریز','pieces of something that has been broken or destroyed','Workers cleared debris after the earthquake.','[["Workers cleared debris after the earthquake.","کارگران پس از زلزله آوار را پاکسازی کردند."],["Space debris is a danger to satellites.","زباله‌های فضایی برای ماهواره‌ها خطرناک است."],["The beach was covered with plastic debris.","ساحل با زباله‌های پلاستیکی پوشیده شده بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:notion','notion','n','تصور، ایده، مفهوم','an idea or belief','The notion that the Earth is flat was rejected.','[["The notion that the Earth is flat was rejected.","این تصور که زمین مسطح است رد شد."],["I have no notion of what he means.","من نمی‌دانم منظور او چیست."],["The book challenges traditional notions of success.","این کتاب مفاهیم سنتی موفقیت را به چالش می‌کشد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:unconscious','unconscious','adj','ناخودآگاه؛ بیهوش','not aware; not awake because of injury','He was unconscious for two hours after the accident.','[["He was unconscious for two hours after the accident.","او دو ساعت پس از تصادف بیهوش بود."],["Many of our decisions are unconscious.","بسیاری از تصمیمات ما ناخودآگاه است."],["She has an unconscious habit of touching her hair.","او عادت ناخودآگاه دارد که موهایش را لمس کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:thesis','thesis','n','پایان‌نامه، رساله؛ نظریه، تز','a long piece of writing for a university degree; an idea supported by arguments','She wrote her thesis on Persian poetry.','[["She wrote her thesis on Persian poetry.","او پایان نامه خود را در مورد شعر فارسی نوشت."],["The main thesis of the book is simple.","پایان نامه اصلی کتاب ساده است."],["He is writing a doctoral thesis.","او در حال نوشتن رساله دکتری است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:implicit','implicit','adj','ضمنی، تلویحی، غیرمستقیم','suggested but not stated directly','There was an implicit criticism in his words.','[["There was an implicit criticism in his words.","انتقاد تلویحی در سخنان او بود."],["The rules are implicit rather than written.","قوانین به جای نوشته شدن، ضمنی هستند."],["Her agreement was implicit in her silence.","موافقت او در سکوت او آشکار بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deteriorate','deteriorate','v','بدتر شدن، رو به زوال رفتن','to become worse','His health deteriorated quickly.','[["His health deteriorated quickly.","سلامتی او به سرعت رو به وخامت رفت."],["Air quality has deteriorated in the city.","کیفیت هوا در این شهر بدتر شده است."],["The old manuscripts are deteriorating.","نسخه‌های خطی قدیمی رو به زوال هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:aggressive','aggressive','adj','پرخاشگر، تهاجمی؛ شدید','behaving angrily or violently; strongly determined','Some dogs are aggressive towards strangers.','[["Some dogs are aggressive towards strangers.","برخی از سگ‌ها نسبت به غریبه‌ها پرخاشگر هستند."],["The company has an aggressive marketing strategy.","این شرکت یک استراتژی بازاریابی تهاجمی دارد."],["The disease is aggressive and spreads quickly.","این بیماری تهاجمی است و به سرعت گسترش می‌یابد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:chemical','chemical','n','ماده شیمیایی','a substance made by or used in chemistry','Farmers use chemicals to protect their crops.','[["Farmers use chemicals to protect their crops.","کشاورزان برای محافظت از محصولات خود از مواد شیمیایی استفاده می‌کنند."],["The factory released dangerous chemicals into the river.","کارخانه مواد شیمیایی خطرناکی را به رودخانه رها کرد."],["Some chemicals are harmful to health.","برخی از مواد شیمیایی برای سلامتی مضر هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:misleading','misleading','adj','گمراه‌کننده','giving the wrong idea or impression','The advertisement was misleading.','[["The advertisement was misleading.","تبلیغات گمراه کننده بود."],["The title of the article is misleading.","عنوان مقاله گمراه کننده است."],["Statistics can be misleading.","آمار می‌تواند گمراه کننده باشد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:experiment','experiment','v','آزمایش کردن','to try new ideas or methods to find out what happens','Scientists experimented with different materials.','[["Scientists experimented with different materials.","دانشمندان با مواد مختلف آزمایش کردند."],["The chef likes to experiment with new flavors.","سرآشپز دوست دارد طعم‌های جدید را آزمایش کند."],["Young people often experiment with fashion.","جوانان اغلب مد را تجربه می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:chaos','chaos','n','هرج‌ومرج، آشوب','a state of complete confusion and disorder','The storm caused chaos on the roads.','[["The storm caused chaos on the roads.","طوفان باعث هرج و مرج در جاده‌ها شد."],["The city was in chaos after the earthquake.","پس از زلزله شهر در هرج و مرج بود."],["There was chaos when the lights went out.","وقتی چراغ‌ها خاموش شد هرج و مرج بود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:entire','entire','adj','کامل، تمام، کل','whole; complete','The entire village was destroyed.','[["The entire village was destroyed.","تمام روستا ویران شد."],["She spent the entire day reading.","او تمام روز را صرف خواندن کرد."],["The entire process takes three hours.","کل فرآیند سه ساعت طول می‌کشد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deter','deter','v','بازداشتن، منصرف کردن، جلوگیری کردن','to make someone decide not to do something','High prices deter many tourists.','[["High prices deter many tourists.","قیمت‌های بالا بسیاری از گردشگران را منصرف می‌کند."],["Cameras are used to deter crime.","از دوربین‌ها برای جلوگیری از جرم استفاده می‌شود."],["Nothing could deter her from her goal.","هیچ چیز نتوانست او را از هدفش باز دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:nasty','nasty','adj','ناخوشایند، بد، زننده','very unpleasant','The medicine has a nasty taste.','[["The medicine has a nasty taste.","این دارو طعم بدی دارد."],["He had a nasty accident.","تصادف بدی داشت"],["There is a nasty smell in the kitchen.","بوی بدی در آشپزخانه می‌آید."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:modify','modify','v','اصلاح کردن، تغییر دادن (جزئی)','to change something slightly to improve it','The plan was modified after the test.','[["The plan was modified after the test.","این طرح پس از آزمایش اصلاح شد."],["Scientists modified the genes of the plant.","دانشمندان ژن‌های این گیاه را اصلاح کردند."],["You may need to modify your diet.","ممکن است لازم باشد رژیم غذایی خود را اصلاح کنید."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:become extinct','become extinct','phr','منقرض شدن','to stop existing as a species','Dinosaurs became extinct 66 million years ago.','[["Dinosaurs became extinct 66 million years ago.","دایناسورها 66 میلیون سال پیش منقرض شدند."],["Many species may become extinct this century.","بسیاری از گونه‌ها ممکن است در این قرن منقرض شوند."],["The bird became extinct because of hunting.","این پرنده به دلیل شکار منقرض شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:hurdle','hurdle','n','مانع، دشواری','a problem or difficulty that must be solved','Money is the biggest hurdle for the project.','[["Money is the biggest hurdle for the project.","پول بزرگترین مانع برای پروژه است."],["Language is a major hurdle for immigrants.","زبان یک مانع بزرگ برای مهاجران است."],["The team cleared the final hurdle.","این تیم مانع نهایی را برطرف کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:initiative','initiative','n','ابتکار عمل؛ طرح جدید','the ability to act without being told; a new plan to solve a problem','She showed initiative by solving the problem herself.','[["She showed initiative by solving the problem herself.","او با حل این مشکل خودش ابتکار عمل نشان داد."],["The government launched a new initiative to reduce waste.","دولت ابتکار جدیدی را برای کاهش ضایعات آغاز کرد."],["Employees are encouraged to take the initiative.","کارکنان تشویق می‌شوند تا ابتکار عمل را به دست بگیرند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:compound','compound','n','ترکیب (شیمیایی)؛ محوطه محصور','a substance made of two or more elements; an enclosed area','Water is a compound of hydrogen and oxygen.','[["Water is a compound of hydrogen and oxygen.","آب ترکیبی از هیدروژن و اکسیژن است."],["Scientists discovered a new compound.","دانشمندان ترکیب جدیدی کشف کردند."],["The soldiers lived in a compound.","سربازان در یک محوطه زندگی می‌کردند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:specimen','specimen','n','نمونه (برای آزمایش یا مطالعه)','a single example of something; a small amount of something for testing','The museum has rare specimens of butterflies.','[["The museum has rare specimens of butterflies.","این موزه دارای نمونه‌های کمیاب از پروانه‌ها است."],["Blood specimens were sent to the lab.","نمونه‌های خون به آزمایشگاه ارسال شد."],["Scientists collected plant specimens in the forest.","دانشمندان نمونه‌های گیاهی را در جنگل جمع آوری کردند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:therapeutic','therapeutic','adj','درمانی، شفابخش','helping to treat or cure an illness; relaxing','The plant has therapeutic properties.','[["The plant has therapeutic properties.","این گیاه دارای خواص درمانی است."],["Gardening can be very therapeutic.","باغبانی می‌تواند بسیار درمانی باشد."],["Music is used for therapeutic purposes.","از موسیقی برای اهداف درمانی استفاده می‌شود."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:ongoing','ongoing','adj','جاری، در حال انجام، مستمر','continuing to exist or develop','Research into the disease is ongoing.','[["Research into the disease is ongoing.","تحقیقات در مورد این بیماری ادامه دارد."],["There is an ongoing debate about the issue.","بحث در مورد این موضوع ادامه دارد."],["The project is ongoing.","پروژه در حال انجام است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:subsequent','subsequent','adj','بعدی، متعاقب','happening after something else','Subsequent studies confirmed the results.','[["Subsequent studies confirmed the results.","مطالعات بعدی نتایج را تایید کرد."],["The earthquake and subsequent fire destroyed the town.","زلزله و آتش سوزی متعاقب آن شهر را ویران کرد."],["In subsequent years, the city grew rapidly.","در سال‌های بعد، شهر به سرعت رشد کرد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:deprive','deprive','v','محروم کردن','to take something away from someone or prevent them from having it','Lack of sleep deprives the brain of rest.','[["Lack of sleep deprives the brain of rest.","کم خوابی مغز را از استراحت محروم می‌کند."],["The war deprived children of education.","جنگ کودکان را از تحصیل محروم کرد."],["Plants deprived of light cannot grow.","گیاهان محروم از نور نمی‌توانند رشد کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:numerous','numerous','adj','متعدد، فراوان','many','Numerous studies show the benefits of exercise.','[["Numerous studies show the benefits of exercise.","مطالعات متعدد فواید ورزش را نشان می‌دهد."],["The city has numerous parks.","این شهر دارای پارک‌های متعددی است."],["He has received numerous awards.","او جوایز متعددی دریافت کرده است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:diverse','diverse','adj','متنوع، گوناگون','including many different types','Iran has a diverse landscape.','[["Iran has a diverse landscape.","ایران چشم انداز متنوعی دارد."],["The class includes students from diverse backgrounds.","این کلاس شامل دانش آموزانی با زمینه‌های مختلف است."],["Coral reefs support diverse marine life.","صخره‌های مرجانی از حیات دریایی متنوع پشتیبانی می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:starve','starve','v','از گرسنگی مردن یا رنج بردن','to suffer or die because of lack of food','Many animals starve during long winters.','[["Many animals starve during long winters.","بسیاری از حیوانات در زمستان‌های طولانی گرسنگی می‌کشند."],["Millions of people starved during the famine.","میلیون‌ها نفر در طول قحطی گرسنه بودند."],["I''m starving! Let''s eat.","من دارم از گرسنگی میمیرم! بیا بخوریم"]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:imply','imply','v','به‌طور ضمنی رساندن، دلالت داشتن','to suggest something without saying it directly','His silence implied agreement.','[["His silence implied agreement.","سکوت او به معنای توافق بود."],["The results imply that the drug is effective.","نتایج حاکی از موثر بودن دارو است."],["Are you implying that I am wrong?","منظورتان این است که من اشتباه می‌کنم؟"]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:elude','elude','v','طفره رفتن، فرار کردن از؛ درک نشدن','to escape from someone; to fail to be understood or achieved','The thief eluded the police for weeks.','[["The thief eluded the police for weeks.","دزد هفته‌ها از پلیس فرار کرد."],["The answer still eludes scientists.","پاسخ هنوز از دانشمندان فراری است."],["Success eluded him for many years.","موفقیت سالها از او دوری گزید."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:broad','broad','adj','پهن، گسترده، کلی','wide; including many different things; general','The river is broad and slow.','[["The river is broad and slow.","رودخانه عریض و کند است."],["The course covers a broad range of topics.","این دوره طیف گسترده ای از موضوعات را پوشش می‌دهد."],["There is broad agreement on the plan.","توافق گسترده ای در مورد این طرح وجود دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:regulate','regulate','v','تنظیم کردن، کنترل کردن (با قانون)','to control something by rules; to control speed, temperature etc.','The government regulates the use of pesticides.','[["The government regulates the use of pesticides.","دولت استفاده از آفت کش‌ها را تنظیم می‌کند."],["Sweating helps regulate body temperature.","تعریق به تنظیم دمای بدن کمک می‌کند."],["Laws regulate fishing in the area.","قوانین ماهیگیری در منطقه را تنظیم می‌کند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:striking','striking','adj','چشمگیر، قابل‌توجه، برجسته','very unusual and easy to notice; attractive','There is a striking similarity between the two languages.','[["There is a striking similarity between the two languages.","شباهت قابل توجهی بین این دو زبان وجود دارد."],["She is a woman of striking beauty.","او زنی با زیبایی چشمگیر است."],["The results show a striking difference.","نتایج یک تفاوت قابل توجه را نشان می‌دهد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:observation','observation','n','مشاهده؛ اظهارنظر','the act of watching something carefully; a remark','Scientists made careful observations of the stars.','[["Scientists made careful observations of the stars.","دانشمندان مشاهدات دقیقی از ستارگان انجام دادند."],["The patient is under observation.","بیمار تحت نظر است."],["She made an interesting observation about the results.","او در مورد نتایج مشاهدات جالبی انجام داد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:entangle','entangle','v','گیر انداختن، گرفتار کردن','to make something become caught in nets, ropes etc.; to involve in difficulty','Dolphins became entangled in fishing nets.','[["Dolphins became entangled in fishing nets.","دلفین‌ها در تورهای ماهیگیری گیر کردند."],["The bird''s wings were entangled in plastic.","بال‌های پرنده در پلاستیک در هم پیچیده بود."],["He became entangled in a legal dispute.","او در یک دعوای حقوقی گرفتار شد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:attitude','attitude','n','نگرش، طرز فکر، رویکرد','the way you think and feel about something','Attitudes towards women have changed.','[["Attitudes towards women have changed.","نگرش نسبت به زنان تغییر کرده است."],["She has a positive attitude to life.","او نگرش مثبتی به زندگی دارد."],["Public attitudes to recycling are improving.","نگرش عمومی نسبت به بازیافت در حال بهبود است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:enrich','enrich','v','غنی کردن، پربار کردن','to improve the quality of something by adding to it','Fallen leaves enrich the soil.','[["Fallen leaves enrich the soil.","برگ‌های افتاده خاک را غنی می‌کنند."],["Travel enriches our understanding of the world.","سفر درک ما از جهان را غنی می‌کند."],["The flour is enriched with vitamins.","آرد با ویتامین‌ها غنی شده است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:tissue','tissue','n','بافت (بدن)؛ دستمال کاغذی','the material that forms animal or plant cells; soft paper','Muscle tissue repairs itself after exercise.','[["Muscle tissue repairs itself after exercise.","بافت عضلانی پس از ورزش خود را ترمیم می‌کند."],["The doctor took a sample of tissue.","دکتر یک نمونه از بافت برداشت."],["She took a tissue from her bag.","دستمال کاغذی از کیفش برداشت."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:predominant','predominant','adj','غالب، مسلط، عمده','most common or most important','Green is the predominant color in the forest.','[["Green is the predominant color in the forest.","سبز رنگ غالب در جنگل است."],["Farming is the predominant industry.","کشاورزی صنعت غالب است."],["The predominant view among scientists has changed.","دیدگاه غالب در میان دانشمندان تغییر کرده است."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:absorb','absorb','v','جذب کردن','to take in liquid, gas, heat or information','Plants absorb water through their roots.','[["Plants absorb water through their roots.","گیاهان آب را از طریق ریشه جذب می‌کنند."],["Dark colors absorb heat.","رنگ‌های تیره گرما را جذب می‌کنند."],["Children absorb information quickly.","کودکان به سرعت اطلاعات را جذب می‌کنند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:robust','robust','adj','قوی، مقاوم، محکم','strong and healthy; not likely to fail','The economy remains robust.','[["The economy remains robust.","اقتصاد قوی باقی می‌ماند."],["The plant is robust and needs little care.","این گیاه قوی است و نیاز به مراقبت کمی دارد."],["The study provides robust evidence.","این مطالعه شواهد قوی ارائه می‌دهد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:severe','severe','adj','شدید، سخت، جدی','very bad or serious','The region suffered a severe drought.','[["The region suffered a severe drought.","این منطقه دچار خشکسالی شدید شد."],["He has severe back pain.","کمردرد شدید دارد."],["There are severe penalties for breaking the law.","قانون شکنی مجازات سنگینی دارد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:playful','playful','adj','بازیگوش، شوخ','full of fun; liking to play','Dolphins are playful animals.','[["Dolphins are playful animals.","دلفین‌ها حیواناتی بازیگوش هستند."],["The puppy is very playful.","توله سگ بسیار بازیگوش است."],["She gave him a playful smile.","لبخندی بازیگوش به او تحویل داد."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
INSERT INTO words(slug,word,pos,meaning_fa,definition,example,examples,category_id,level_no,created_at,updated_at) VALUES('ieltsr:marine','marine','adj','دریایی','relating to the sea','Marine pollution threatens coral reefs.','[["Marine pollution threatens coral reefs.","آلودگی دریایی صخره‌های مرجانی را تهدید می‌کند."],["She studies marine biology.","او زیست شناسی دریایی می‌خواند."],["Whales are marine mammals.","نهنگ‌ها پستانداران دریایی هستند."]]','ielts',6,1792231925620,1792231925620) ON CONFLICT(slug) DO UPDATE SET examples=excluded.examples, updated_at=excluded.updated_at;
